# Req 49 — friendly 500 / 503 pages + structured traceback logging.
# Bare Flask shows "Internal Server Error" with no clue what to do; the
# user reported repeated 500s during testing. We now log the path,
# method, candidate id (if present in URL), and traceback so Railway
# logs surface root-cause info, and render a small HTML banner so the
# user can retry without staring at a generic stack page.
@app.errorhandler(500)
@app.errorhandler(503)
def _friendly_server_error(exc):
    import traceback as _tb
    import html as _html_mod
    try:
        cur_app = current_app._get_current_object()
        cur_app.logger.error(
            "5xx hit: path=%s method=%s args=%s",
            request.path, request.method, dict(request.args),
            exc_info=exc,
        )
    except Exception:
        pass

    # Surface the actual exception details to logged-in staff so they
    # don't have to dig into Railway logs to diagnose. End-users still
    # see the friendly message.
    detail_block = ""
    try:
        if current_user.is_authenticated:
            # Try to pull the original exception (Flask wraps in HTTPException).
            original = getattr(exc, "original_exception", None) or exc
            exc_name = type(original).__name__
            exc_msg = str(original) or "(no message)"
            tb_text = "".join(_tb.format_exception(type(original), original, original.__traceback__))[-3000:]
            detail_block = (
                "<details style='margin-top:24px; background:#fef2f2; "
                "border:1px solid #fecaca; border-radius:8px; padding:12px;'>"
                "<summary style='cursor:pointer; font-weight:600; color:#991b1b;'>"
                "Technical details (staff only)</summary>"
                f"<p style='margin:8px 0 4px; font-weight:600;'>{_html_mod.escape(exc_name)}</p>"
                f"<pre style='font-size:12px; white-space:pre-wrap; "
                f"background:#fff; border:1px solid #fecaca; padding:8px; "
                f"border-radius:4px; color:#7f1d1d; max-height:360px; overflow:auto;'>"
                f"{_html_mod.escape(exc_msg)}\n\n{_html_mod.escape(tb_text)}"
                "</pre>"
                "</details>"
            )
    except Exception:
        pass

    body = (
        "<!doctype html><html><head><title>Service hiccup</title>"
        "<style>body{font-family:system-ui,sans-serif;max-width:720px;"
        "margin:60px auto;padding:0 20px;color:#111;line-height:1.55}"
        "h1{font-size:20px}p{color:#374151}.btn{display:inline-block;"
        "margin-top:16px;padding:10px 16px;background:#1e3a8a;color:#fff;"
        "border-radius:6px;text-decoration:none;font-weight:600}</style>"
        "</head><body>"
        "<h1>Something went wrong on our side</h1>"
        "<p>The server hit an unexpected error or an external service "
        "was slow to respond. Please try the action again — your work "
        "is usually saved.</p>"
        "<p>If it keeps happening, paste the URL into a message to the "
        "Optimus team.</p>"
        "<a class='btn' href='javascript:history.back()'>Go back</a>"
        f"{detail_block}"
        "</body></html>"
    )
    return body, getattr(exc, "code", 500)

# Security headers
@app.after_request
def set_security_headers(response):
    response.headers['X-Content-Type-Options'] = 'nosniff'
    response.headers['X-Frame-Options'] = 'SAMEORIGIN'
    response.headers['X-XSS-Protection'] = '1; mode=block'
    response.headers['Strict-Transport-Security'] = 'max-age=31536000; includeSubDomains'
    response.headers['Content-Security-Policy'] = "default-src 'self' https://cdn.tailwindcss.com https://cdn.jsdelivr.net https://cdnjs.cloudflare.com; script-src 'self' 'unsafe-inline' https://cdn.tailwindcss.com https://cdn.jsdelivr.net; style-src 'self' 'unsafe-inline' https://cdn.tailwindcss.com https://cdn.jsdelivr.net https://cdnjs.cloudflare.com https://fonts.googleapis.com; font-src 'self' https://cdn.jsdelivr.net https://cdnjs.cloudflare.com https://fonts.gstatic.com data:; img-src 'self' data: https://api.qrserver.com; frame-src 'self' https://sign.signable.app https://*.signable.app"
    return response

