@app.route("/admin/timesheets", methods=["GET"])
@login_required
def admin_timesheets():
    """Phase 4 / TS 19 — every timesheet across every placement with
    status / WC / approver / last-action timestamp. Filterable by client,
    project, associate, status, type, WC. Drill-through to Edit on
    behalf; Approve / Decline inline for Submitted rows."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("index"))
    client_filter = (request.args.get("client") or "").strip()
    project_filter = (request.args.get("project") or "").strip()
    associate_filter = (request.args.get("associate") or "").strip()
    status_filter = (request.args.get("status") or "").strip().lower()
    wc_filter = (request.args.get("wc") or "").strip()
    type_filter = (request.args.get("type") or "").strip().lower()
    sql = """
        SELECT t.id, t.status, t.period_start, t.period_end, t.billable_days,
               t.submitted_at, t.approved_at, t.user_id, t.engagement_id,
               COALESCE(t.timesheet_type,'Standard') AS ts_type,
               t.originating_timesheet_id,
               e.name AS engagement_name, e.client AS client_name,
               c.name AS associate_name
        FROM timesheets t
        LEFT JOIN engagements e ON e.id = t.engagement_id
        LEFT JOIN candidates c ON c.id = t.user_id
        WHERE 1=1
    """
    params = {}
    if client_filter:
        sql += " AND e.client = :client"
        params["client"] = client_filter
    if project_filter:
        sql += " AND e.name = :project"
        params["project"] = project_filter
    if associate_filter:
        sql += " AND c.name = :associate"
        params["associate"] = associate_filter
    if status_filter and status_filter != "all":
        sql += " AND LOWER(t.status) = :status"
        params["status"] = status_filter
    if type_filter and type_filter in ("standard", "adjustment"):
        sql += " AND LOWER(COALESCE(t.timesheet_type,'Standard')) = :type"
        params["type"] = type_filter
    if wc_filter:
        sql += " AND t.period_start = :wc"
        params["wc"] = wc_filter
    sql += " ORDER BY t.period_start DESC, t.id DESC LIMIT 1000"
    # Dashboard tile thresholds. A Draft is "Not submitted (overdue)"
    # once we're past the Tuesday of the week FOLLOWING its WC — i.e.
    # week_start + 8 calendar days. Configurable here if the deadline
    # ever moves.
    _today = date.today()
    _overdue_cutoff = _today - timedelta(days=8)
    # OT/Expenses permissions card — optional engagement focus. When
    # the admin picks an engagement from the picker the page reloads
    # with ?perm_engagement=<id>, the Associates on that engagement
    # are loaded with their current permission window (if any), and
    # the Apply form lets the admin grant/revoke OT/Expenses.
    perm_engagement_id = request.args.get("perm_engagement", type=int)
    with Session(engine) as s:
        rows = s.execute(text(sql).bindparams(**params)).all()
        # Distinct filter dropdown options across all timesheets.
        clients = [r[0] for r in s.execute(text(
            "SELECT DISTINCT client FROM engagements WHERE client IS NOT NULL AND TRIM(client) <> '' ORDER BY client"
        )).all()]
        projects = [r[0] for r in s.execute(text(
            "SELECT DISTINCT name FROM engagements WHERE name IS NOT NULL AND TRIM(name) <> '' ORDER BY name"
        )).all()]
        # Associates with at least one timesheet — drives the new
        # Associate filter dropdown.
        associates = [r[0] for r in s.execute(text(
            "SELECT DISTINCT c.name FROM candidates c "
            "JOIN timesheets t ON t.user_id = c.id "
            "WHERE c.name IS NOT NULL AND TRIM(c.name) <> '' "
            "ORDER BY c.name"
        )).all()]
        # ----- Dashboard counts (org-wide) -----
        # Tiles are NOT scoped by the page filters — they reflect the
        # whole org so the recruiter always sees the true backlog.
        overall = s.execute(text("""
            SELECT
              SUM(CASE WHEN LOWER(status) = 'draft' AND period_start <= :cutoff THEN 1 ELSE 0 END) AS not_submitted,
              SUM(CASE WHEN LOWER(status) = 'submitted' THEN 1 ELSE 0 END) AS awaiting,
              SUM(CASE WHEN LOWER(status) = 'rejected' THEN 1 ELSE 0 END) AS rejected
            FROM timesheets
        """).bindparams(cutoff=_overdue_cutoff)).first()
        overall_counts = {
            "not_submitted": int(overall.not_submitted or 0) if overall else 0,
            "awaiting":      int(overall.awaiting or 0)      if overall else 0,
            "rejected":      int(overall.rejected or 0)      if overall else 0,
        }
        # ----- Per-engagement breakdown -----
        # Per (client, project) row carrying the same three counters.
        # Only engagements with at least one outstanding TS appear so the
        # table stays focused on what needs action.
        bd_rows = s.execute(text("""
            SELECT e.id, e.client AS client_name, e.name AS engagement_name,
                   SUM(CASE WHEN LOWER(t.status) = 'draft' AND t.period_start <= :cutoff THEN 1 ELSE 0 END) AS not_submitted,
                   SUM(CASE WHEN LOWER(t.status) = 'submitted' THEN 1 ELSE 0 END) AS awaiting,
                   SUM(CASE WHEN LOWER(t.status) = 'rejected' THEN 1 ELSE 0 END) AS rejected
            FROM engagements e
            LEFT JOIN timesheets t ON t.engagement_id = e.id
            GROUP BY e.id, e.client, e.name
            HAVING
              SUM(CASE WHEN LOWER(t.status) = 'draft' AND t.period_start <= :cutoff THEN 1 ELSE 0 END)
              + SUM(CASE WHEN LOWER(t.status) = 'submitted' THEN 1 ELSE 0 END)
              + SUM(CASE WHEN LOWER(t.status) = 'rejected' THEN 1 ELSE 0 END) > 0
            ORDER BY e.client, e.name
        """).bindparams(cutoff=_overdue_cutoff)).all()
        breakdown = [
            {
                "client_name":   r.client_name or "(no client)",
                "engagement_name": r.engagement_name or "(unnamed)",
                "not_submitted": int(r.not_submitted or 0),
                "awaiting":      int(r.awaiting or 0),
                "rejected":      int(r.rejected or 0),
            }
            for r in bd_rows
        ]
        # ----- TS 20: Create-for-Associate picker -----
        # All Candidates with at least one Placed-style Application,
        # plus all engagements they're attached to via Job rows. A
        # small JSON map (assoc_engagement_map) lets the modal narrow
        # the Engagement dropdown once an Associate is picked.
        create_candidates = [
            {"id": r.id, "name": r.name or f"#{r.id}", "email": r.email or ""}
            for r in s.execute(text(
                "SELECT DISTINCT c.id, c.name, c.email FROM candidates c "
                "JOIN applications a ON a.candidate_id = c.id "
                "WHERE a.status IN ('Placed','Contract Signed','On Assignment','Active','Contracted','Hired') "
                "ORDER BY c.name"
            )).all()
        ]
        create_eng_pairs = s.execute(text(
            "SELECT DISTINCT a.candidate_id AS cand_id, j.engagement_id AS eng_id "
            "FROM applications a JOIN jobs j ON j.id = a.job_id "
            "WHERE a.status IN ('Placed','Contract Signed','On Assignment','Active','Contracted','Hired')"
        )).all()
        assoc_engagement_map = {}
        for pair in create_eng_pairs:
            assoc_engagement_map.setdefault(pair.cand_id, []).append(pair.eng_id)

        # ----- OT/Expenses permissions card -----
        # All engagements for the picker.
        perm_engagements = [
            {"id": r.id, "client": r.client or "", "name": r.name or "",
             "start_date": r.start_date, "end_date": r.end_date}
            for r in s.execute(text(
                "SELECT id, client, name, start_date, end_date FROM engagements "
                "ORDER BY client, name"
            )).all()
        ]
        # Quick-pick preset dates (server-side so the template can fill
        # the date inputs without per-template date math).
        _today_mon = _today - timedelta(days=_today.weekday())
        _next_mon  = _today_mon + timedelta(days=7)
        _next_sun  = _next_mon + timedelta(days=6)
        _this_sun  = _today_mon + timedelta(days=6)
        perm_presets = {
            "this_week_from": _today_mon.isoformat(),
            "this_week_to":   _this_sun.isoformat(),
            "next_week_from": _next_mon.isoformat(),
            "next_week_to":   _next_sun.isoformat(),
        }
        # Associates on the selected engagement + their current effective
        # permission for today (so the checkboxes pre-tick when the
        # Associate already has a live grant covering today).
        perm_associates = []
        perm_engagement = None
        if perm_engagement_id:
            perm_engagement = next((e for e in perm_engagements if e["id"] == perm_engagement_id), None)
            if perm_engagement:
                perm_presets["project_from"] = (
                    perm_engagement["start_date"].date().isoformat()
                    if perm_engagement["start_date"] and hasattr(perm_engagement["start_date"], "date")
                    else (perm_engagement["start_date"].isoformat() if perm_engagement["start_date"] else _today_mon.isoformat())
                )
                perm_presets["project_to"] = (
                    perm_engagement["end_date"].date().isoformat()
                    if perm_engagement["end_date"] and hasattr(perm_engagement["end_date"], "date")
                    else (perm_engagement["end_date"].isoformat() if perm_engagement["end_date"] else "")
                )
                # Associates linked to the engagement via Placed-style
                # Applications (canonical placement record).
                placed_rows = s.execute(text(
                    "SELECT DISTINCT c.id AS cand_id, c.name AS cand_name "
                    "FROM applications a "
                    "JOIN candidates c ON c.id = a.candidate_id "
                    "JOIN jobs j ON j.id = a.job_id "
                    "WHERE j.engagement_id = :eid "
                    "  AND a.status IN ('Placed','Contract Signed','On Assignment','Active','Contracted','Hired') "
                    "ORDER BY c.name"
                ).bindparams(eid=perm_engagement_id)).all()
                for pr in placed_rows:
                    perms = _associate_ts_permissions(s, pr.cand_id, perm_engagement_id, _today_mon)
                    # Find the latest end date across active grants
                    # covering today. NULL effective_to means open-ended
                    # — any such row trumps a dated one when reporting
                    # "when does the allowance run out".
                    end_rows = s.execute(text(
                        "SELECT effective_to, overtime_enabled, expense_enabled "
                        "FROM associate_ts_permissions "
                        "WHERE user_id = :uid AND engagement_id = :eid "
                        "  AND effective_from <= :today "
                        "  AND (effective_to IS NULL OR effective_to >= :today)"
                    ).bindparams(uid=pr.cand_id, eid=perm_engagement_id, today=_today_mon)).all()
                    active_rows = [r for r in end_rows if r.overtime_enabled or r.expense_enabled]
                    allowance_end_label = None
                    if active_rows:
                        if any(r.effective_to is None for r in active_rows):
                            allowance_end_label = "Open-ended"
                        else:
                            max_end = max(r.effective_to for r in active_rows)
                            allowance_end_label = (
                                max_end.strftime("%d/%m/%Y")
                                if hasattr(max_end, "strftime")
                                else str(max_end)
                            )
                    perm_associates.append({
                        "user_id": pr.cand_id,
                        "name": pr.cand_name or f"#{pr.cand_id}",
                        "ot_active": perms["overtime_enabled"],
                        "expense_active": perms["expense_enabled"],
                        "allowance_end": allowance_end_label,
                    })
    timesheets = [
        {
            "id": r.id,
            "status": r.status,
            "period_start": r.period_start,
            "period_end": r.period_end,
            "billable_days": r.billable_days or 0,
            "submitted_at": r.submitted_at,
            "approved_at": r.approved_at,
            "associate_name": r.associate_name or "(unknown)",
            "engagement_name": r.engagement_name or "",
            "client_name": r.client_name or "",
            "ts_type": r.ts_type or "Standard",
            "originating_id": r.originating_timesheet_id,
        }
        for r in rows
    ]
    return render_template(
        "admin_timesheets.html",
        timesheets=timesheets,
        clients=clients,
        projects=projects,
        associates=associates,
        client_filter=client_filter,
        project_filter=project_filter,
        associate_filter=associate_filter,
        status_filter=status_filter or "all",
        type_filter=type_filter or "all",
        wc_filter=wc_filter,
        overall_counts=overall_counts,
        breakdown=breakdown,
        overdue_cutoff=_overdue_cutoff,
        perm_engagements=perm_engagements,
        perm_engagement_id=perm_engagement_id,
        perm_engagement=perm_engagement,
        perm_associates=perm_associates,
        perm_presets=perm_presets,
        create_candidates=create_candidates,
        assoc_engagement_map=assoc_engagement_map,
    )


@app.route("/admin/timesheets/permissions/apply", methods=["POST"])
@login_required
def admin_ts_permissions_apply():
    """Grant Overtime / Expenses claim rights to one or more Associates
    on an engagement for a date window. Default state with no row is
    OFF; multiple overlapping rows union together (any TRUE wins).
    Audit-logged. Card lives at the top of /admin/timesheets."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_timesheets"))
    try:
        engagement_id = int(request.form.get("engagement_id") or "")
    except ValueError:
        flash("Pick an engagement first.", "warning")
        return redirect(url_for("admin_timesheets"))
    eff_from_raw = (request.form.get("effective_from") or "").strip()
    eff_to_raw   = (request.form.get("effective_to") or "").strip()
    try:
        eff_from = datetime.date.fromisoformat(eff_from_raw) if eff_from_raw else None
    except ValueError:
        eff_from = None
    try:
        eff_to = datetime.date.fromisoformat(eff_to_raw) if eff_to_raw else None
    except ValueError:
        eff_to = None
    if not eff_from:
        flash("Pick a start date for the grant.", "warning")
        return redirect(url_for("admin_timesheets", perm_engagement=engagement_id))
    if eff_to and eff_to < eff_from:
        flash("End date can't be before the start date.", "warning")
        return redirect(url_for("admin_timesheets", perm_engagement=engagement_id))
    # The form posts user_id[] for each ticked Associate row, plus
    # checkbox fields ot_<user_id> and exp_<user_id> for that row.
    user_ids = request.form.getlist("user_id[]")
    if not user_ids:
        flash("Tick at least one Associate to grant permissions to.", "warning")
        return redirect(url_for("admin_timesheets", perm_engagement=engagement_id))
    inserted = 0
    with Session(engine) as s:
        for raw_uid in user_ids:
            try:
                uid = int(raw_uid)
            except (TypeError, ValueError):
                continue
            ot  = request.form.get(f"ot_{uid}")  in ("1", "on", "true")
            exp = request.form.get(f"exp_{uid}") in ("1", "on", "true")
            if not ot and not exp:
                # Nothing to grant — skip rather than write a no-op row.
                continue
            s.add(AssociateTimesheetPermission(
                user_id=uid,
                engagement_id=engagement_id,
                effective_from=eff_from,
                effective_to=eff_to,
                overtime_enabled=ot,
                expense_enabled=exp,
                created_by=current_user.id,
            ))
            inserted += 1
        s.commit()
        try:
            log_audit_event(
                "create", "config",
                f"Granted Timesheet permissions on engagement {engagement_id} to {inserted} Associate(s)",
                "engagement", engagement_id,
                {"from": eff_from_raw, "to": eff_to_raw or None, "user_ids": user_ids, "count": inserted},
            )
        except Exception:
            pass
    if inserted:
        flash(f"Permissions granted to {inserted} Associate(s) from {eff_from_raw} "
              f"to {eff_to_raw or 'open-ended'}.", "success")
    else:
        flash("No grants written — make sure at least one OT or Expenses box is ticked per Associate.", "warning")
    return redirect(url_for("admin_timesheets", perm_engagement=engagement_id))


@app.route("/admin/timesheets/permissions/<int:perm_id>/revoke", methods=["POST"])
@login_required
def admin_ts_permissions_revoke(perm_id: int):
    """Delete a single permission row (so the Associate's effective
    grant for the affected weeks reverts to whatever any other
    overlapping row still says — or to OFF if none remains)."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_timesheets"))
    eng_id = None
    with Session(engine) as s:
        row = s.get(AssociateTimesheetPermission, perm_id)
        if not row:
            flash("Permission row not found (may have already been revoked).", "warning")
            return redirect(url_for("admin_timesheets"))
        eng_id = row.engagement_id
        s.delete(row)
        s.commit()
        try:
            log_audit_event("delete", "config",
                            f"Revoked Timesheet permission #{perm_id}",
                            "engagement", eng_id, {"perm_id": perm_id})
        except Exception:
            pass
    flash("Permission revoked.", "success")
    return redirect(url_for("admin_timesheets", perm_engagement=eng_id))


@app.route("/admin/timesheets/<int:ts_id>/approve", methods=["POST"])
@login_required
def admin_ts_approve(ts_id):
    """Admin Approve from /admin/timesheets row — uses the canonical
    _apply_timesheet_approval helper (same path the Approver Portal
    uses) so the status transition, expense-line stamping (TS 31)
    and audit log all stay consistent."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_timesheets"))
    with Session(engine) as s:
        ts = s.get(Timesheet, ts_id)
        if not ts:
            flash("Timesheet not found.", "warning")
            return redirect(url_for("admin_timesheets"))
        _apply_timesheet_approval(s, ts, current_user.id)
        s.commit()
    flash(f"Timesheet #{ts_id} approved.", "success")
    return redirect(url_for("admin_timesheets"))


@app.route("/admin/timesheets/<int:ts_id>/reject", methods=["POST"])
@login_required
def admin_ts_reject(ts_id):
    """Admin Decline from /admin/timesheets row. Reason is optional
    (associate sees it as the rejection_reason banner)."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_timesheets"))
    reason = (request.form.get("reject_reason") or "").strip()
    with Session(engine) as s:
        ts = s.get(Timesheet, ts_id)
        if not ts:
            flash("Timesheet not found.", "warning")
            return redirect(url_for("admin_timesheets"))
