@app.route("/admin/approvals/leave/create", methods=["POST"])
@login_required
def admin_create_leave():
    cand_id = request.form.get("candidate_id", type=int)
    reason = (request.form.get("reason") or "").strip()
    notice_start = request.form.get("notice_start_date", "")
    notice_end = request.form.get("notice_end_date", "")
    notes = (request.form.get("notes") or "").strip()
    if not cand_id or not reason:
        flash("Associate and reason are required.", "danger")
        return redirect(url_for("admin_approvals"))
    _ns = datetime.datetime.strptime(notice_start, "%Y-%m-%d").date() if notice_start else None
    _ne = datetime.datetime.strptime(notice_end, "%Y-%m-%d").date() if notice_end else None
    try:
        with Session(engine) as s:
            lr = LeaveRequest(
                candidate_id=cand_id,
                reason=reason,
                notice_start_date=_ns,
                notice_end_date=_ne,
                last_working_date=_ne,
                start_date=_ns or datetime.date.today(),
                end_date=_ne or datetime.date.today(),
                notes=notes,
                status="Pending",
                created_by=getattr(current_user, "email", "") or "staff",
                created_at=datetime.datetime.utcnow(),
            )
            s.add(lr)
            s.commit()
        flash("Leave request created.", "success")
    except Exception as exc:
        print(f"[LEAVE-CREATE] ERROR: {exc}", flush=True)
        # Fallback: raw SQL insert — include old NOT NULL columns (start_date, end_date)
        try:
            with engine.connect().execution_options(isolation_level="AUTOCOMMIT") as conn:
                conn.execute(text("""
                    INSERT INTO leave_requests (candidate_id, reason, notice_start_date, notice_end_date,
                        last_working_date, start_date, end_date, notes, status, created_by, created_at)
                    VALUES (:cid, :reason, :ns, :ne, :ne, :ns, :ne, :notes, 'Pending', :by, CURRENT_TIMESTAMP)
                """).bindparams(cid=cand_id, reason=reason, ns=_ns or datetime.date.today(),
                               ne=_ne or datetime.date.today(), notes=notes,
                               by=getattr(current_user, "email", "") or "staff"))
            flash("Leave request created.", "success")
        except Exception as exc2:
            print(f"[LEAVE-CREATE] RAW SQL ALSO FAILED: {exc2}", flush=True)
            flash(f"Failed to create leave request: {exc2}", "danger")
    return redirect(url_for("admin_approvals"))


@app.route("/admin/approvals/leave/<int:lr_id>/approve", methods=["POST"])
@login_required
def admin_approve_leave(lr_id):
    with Session(engine) as s:
        lr = s.get(LeaveRequest, lr_id)
        if lr:
            lr.status = "Approved"
            s.commit()
            flash(f"Leave request approved.", "success")
    return redirect(url_for("admin_approvals"))


@app.route("/admin/approvals/leave/<int:lr_id>/reject", methods=["POST"])
@login_required
def admin_reject_leave(lr_id):
    with Session(engine) as s:
        lr = s.get(LeaveRequest, lr_id)
        if lr:
            lr.status = "Rejected"
            s.commit()
            flash(f"Leave request rejected.", "success")
    return redirect(url_for("admin_approvals"))


@app.route("/admin/timesheets/<int:ts_id>/reopen", methods=["POST"])
@login_required
def admin_reopen_timesheet(ts_id):
    """Phase 1 / TS 6 — admin-only re-open of an Approved timesheet so the
    associate can amend and re-submit. Audit-logged. Called from the Re-open
    button on the all-engagements timesheet list (/admin/timesheets)."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_timesheets"))
    with Session(engine) as s:
        ts = s.get(Timesheet, ts_id)
        if not ts:
            flash("Timesheet not found.", "warning")
            return redirect(url_for("admin_timesheets"))
        old_status = ts.status
        ts.status = "Draft"
        # Clear approval stamps so the new submit gets a fresh approval.
        ts.approved_by = None
        ts.approved_at = None
        s.commit()
        try:
            log_audit_event("update", "timesheet",
                            f"Timesheet #{ts_id} re-opened: {old_status} -> Draft",
                            "timesheet", ts_id, {"old_status": old_status, "new_status": "Draft"})
        except Exception:
            pass
    flash(f"Timesheet #{ts_id} re-opened (was {old_status}). The associate can now amend and re-submit.", "success")
    return redirect(url_for("admin_timesheets"))


@app.route("/admin/invoices")
@login_required
def admin_invoices():
    """Invoices management page — Phase 8 / IR 34 extended filters.
    Phase 6 / IR 9 — per-(project, month) auto-generation tiles."""
    import json
    client_filter = (request.args.get("client") or "").strip()
    project_filter = (request.args.get("project") or "").strip()
    month_filter = (request.args.get("month") or "").strip()   # 'YYYY-MM' or ''
    status_filter = (request.args.get("status") or "").strip().lower()

    with Session(engine) as s:
        # Build filtered list (renamed Pending→Sent / Cancelled→Void already
        # via the boot-time migration; status filters use the new names).
        q = select(Invoice).order_by(Invoice.invoice_date.desc())
        if client_filter:
            q = q.where(Invoice.client_name == client_filter)
        if project_filter:
            q = q.where(Invoice.engagement_name == project_filter)
        if status_filter and status_filter != "all":
            q = q.where(func.lower(Invoice.status) == status_filter)
        if month_filter and len(month_filter) == 7:
            try:
                y, m = month_filter.split("-")
                q = q.where(func.strftime("%Y-%m", Invoice.invoice_date) == month_filter) if engine.dialect.name == "sqlite" else q.where(
                    func.to_char(Invoice.invoice_date, "YYYY-MM") == month_filter
                )
            except Exception:
                pass
        invoices = s.scalars(q).all()

        # Status summary uses the new enum (Sent / Void). Legacy Pending /
        # Cancelled have already been migrated by the boot UPDATE.
        draft_invoices = [i for i in invoices if (i.status or "").lower() == "draft"]
        sent_invoices = [i for i in invoices if (i.status or "").lower() == "sent"]
        paid_invoices = [i for i in invoices if (i.status or "").lower() == "paid"]
        overdue_invoices = [i for i in invoices if (i.status or "").lower() == "overdue"]
        void_invoices = [i for i in invoices if (i.status or "").lower() == "void"]

        # Filter-dropdown sources span ALL invoices, not the filtered set.
        clients_rows = s.execute(text(
            "SELECT DISTINCT client_name FROM invoices WHERE client_name IS NOT NULL AND client_name <> '' ORDER BY client_name"
        )).all()
        client_list = [{"id": c[0], "name": c[0]} for c in clients_rows if c[0]]

        engagements_rows = s.execute(text(
            "SELECT id, COALESCE(name, client || ' Engagement'), client FROM engagements WHERE client IS NOT NULL"
        )).fetchall()
        engagement_list = [{"id": e[0], "name": e[1], "client": e[2]} for e in engagements_rows]
        projects_options = sorted({i.engagement_name for i in s.scalars(select(Invoice)).all() if i.engagement_name})

        # IR 9 — per-(engagement, current month) tiles showing approved /
        # total counts so an admin can see who's ready to invoice. Auto-
        # generate button surfaces the new route. Counts are best-effort —
        # if an engagement has no current-month timesheets, it's skipped.
        autogen_tiles = []
        today = datetime.date.today()
        year, month = today.year, today.month
        # Optionally allow ?autogen_month=YYYY-MM to point at a different month.
        ag_month = (request.args.get("autogen_month") or "").strip()
        if ag_month and len(ag_month) == 7:
            try:
                year = int(ag_month.split("-")[0])
                month = int(ag_month.split("-")[1])
            except ValueError:
                pass
        for eng in s.scalars(select(Engagement).where(Engagement.status == "Active")).all():
            try:
                # Total expected = number of timesheets that exist in this
                # month for this engagement. Approved count = how many are Approved.
                import calendar as _cal
                ms = datetime.date(year, month, 1)
                me = datetime.date(year, month, _cal.monthrange(year, month)[1])
                total = s.execute(text(
                    "SELECT COUNT(*) FROM timesheets WHERE engagement_id = :eid "
                    "AND period_start >= :ms AND period_end <= :me"
                ).bindparams(eid=eng.id, ms=ms, me=me)).scalar() or 0
                if total == 0:
                    continue
                approved = s.execute(text(
                    "SELECT COUNT(*) FROM timesheets WHERE engagement_id = :eid "
                    "AND period_start >= :ms AND period_end <= :me AND LOWER(status) = 'approved'"
                ).bindparams(eid=eng.id, ms=ms, me=me)).scalar() or 0
                # IR 9 — drill-down: list the timesheets NOT yet approved
                # so the collapsible tile body can show them. Joins
                # candidates so the admin sees the Associate name.
                outstanding = []
                if approved < total:
                    out_rows = s.execute(text(
                        "SELECT t.id, t.status, t.period_start, c.name AS associate_name "
                        "FROM timesheets t "
                        "LEFT JOIN candidates c ON c.id = t.user_id "
                        "WHERE t.engagement_id = :eid "
                        "  AND t.period_start >= :ms AND t.period_end <= :me "
                        "  AND LOWER(t.status) <> 'approved' "
                        "ORDER BY t.period_start, c.name"
                    ).bindparams(eid=eng.id, ms=ms, me=me)).all()
                    outstanding = [
                        {
                            "id": r.id,
                            "status": r.status or "Draft",
                            "period_start": r.period_start,
                            "associate_name": r.associate_name or "(unknown)",
                        }
                        for r in out_rows
                    ]
                autogen_tiles.append({
                    "engagement_id": eng.id,
                    "engagement_name": eng.name or "",
                    "client_name": eng.client or "",
                    "approved": approved,
                    "total": total,
                    "ready": approved == total,
                    "year": year,
                    "month": month,
                    "outstanding": outstanding,
                })
            except Exception:
                continue

        return render_template("admin_invoices.html",
            invoices=invoices,
            draft_count=len(draft_invoices),
            draft_amount=sum(i.total_amount or 0 for i in draft_invoices),
            pending_count=len(sent_invoices),   # template still uses 'pending_*' names
            pending_amount=sum(i.total_amount or 0 for i in sent_invoices),
            paid_count=len(paid_invoices),
            paid_amount=sum(i.total_amount or 0 for i in paid_invoices),
            overdue_count=len(overdue_invoices),
            overdue_amount=sum(i.total_amount or 0 for i in overdue_invoices),
            void_count=len(void_invoices),
            clients=client_list,
            engagements=engagement_list,
            projects_options=projects_options,
            client_filter=client_filter,
            project_filter=project_filter,
            month_filter=month_filter,
            status_filter=status_filter or "all",
            autogen_tiles=autogen_tiles,
            autogen_year=year,
            autogen_month=month,
        )

def _ensure_client_for_name(s, name: str) -> "Client":
    """Return an existing Client row matching `name`, else create one
    with an auto-derived 2-5 char code and code_confirmed=False (admin
    review required before invoices generate). Used by the Opportunity
    + Engagement create flows so a free-text client name always lands
    a row on /admin/clients."""
    name = (name or "").strip()
    if not name:
        return None
    existing = s.scalar(select(Client).where(Client.name == name))
    if existing:
        return existing
    import re as _re
    words = [w for w in _re.split(r"\s+", name) if w]
    initials = "".join(w[0] for w in words if w and w[0].isalpha()).upper()
    if 2 <= len(initials) <= 5:
        base = initials
    else:
        letters = _re.sub(r"[^A-Za-z]", "", name).upper()
        base = (letters[:3] or "CLI")
    code = base
    n = 2
    while s.scalar(select(Client).where(Client.client_code == code)) is not None:
        suffix = str(n)
        keep = max(2, 5 - len(suffix))
        code = base[:keep] + suffix
        n += 1
        if n > 99:
            code = (base[:3] + "X")[:5]
            break
    c = Client(name=name, client_code=code, code_confirmed=False)
    s.add(c)
    s.flush()
    return c


def _ensure_client_linked(s, engagement) -> "Client":
    """Phase 5 — make sure an engagement has a Client row linked. If the
    engagement has a free-text `client` string but no client_id, find or
    auto-create a Client matching that name (auto-derived code, code_confirmed
    False so an admin reviews it). Called from create_engagement and
    engagement_edit save paths so every engagement always has a Client.

    Returns the linked Client (or None if the engagement has no client name
    at all)."""
    if not engagement or not (engagement.client or "").strip():
        return None
    name = engagement.client.strip()
    existing = s.scalar(select(Client).where(Client.name == name))
    if existing:
        if engagement.client_id != existing.id:
            engagement.client_id = existing.id
        return existing
    # Auto-derive a 2-5 char code from initials, mirroring _auto_backfill_clients.
    import re as _re
    words = [w for w in _re.split(r"\s+", name) if w]
    initials = "".join(w[0] for w in words if w and w[0].isalpha()).upper()
    if 2 <= len(initials) <= 5:
        base = initials
    else:
        letters = _re.sub(r"[^A-Za-z]", "", name).upper()
        base = (letters[:3] or "CLI")
    code = base
    n = 2
    while s.scalar(select(Client).where(Client.client_code == code)) is not None:
        suffix = str(n)
        keep = max(2, 5 - len(suffix))
        code = base[:keep] + suffix
        n += 1
        if n > 99:
            code = (base[:3] + "X")[:5]
            break
    c = Client(name=name, client_code=code, code_confirmed=False)
    s.add(c)
    s.flush()
    engagement.client_id = c.id
    return c


# ============================================================================
# Phase 6 — Invoice auto-generation pipeline (IR 7-18)
# ============================================================================

def _check_timesheets_ready(s, engagement_id: int, year: int, month: int) -> list:
    """IR 8 — return list of (id, status) for timesheets in the given
    calendar month that are NOT yet Approved. Empty list = ready to invoice."""
    import calendar as _cal
    month_start = date(year, month, 1)
    month_end = date(year, month, _cal.monthrange(year, month)[1])
    rows = s.execute(text(
        "SELECT id, status, period_start FROM timesheets "
        "WHERE engagement_id = :eid "
        "AND period_start >= :ms AND period_end <= :me "
        "AND LOWER(status) != 'approved'"
    ).bindparams(eid=engagement_id, ms=month_start, me=month_end)).all()
    return [{"id": r.id, "status": r.status, "period_start": r.period_start} for r in rows]


def _invoice_period_for_month(engagement, year: int, month: int):
    """IR 13 — invoice period = MAX(engagement.start, month_start) to
    MIN(engagement.end or today, month_end). Returns (period_start, period_end)
    as date objects."""
    import calendar as _cal
    month_start = date(year, month, 1)
    month_end = date(year, month, _cal.monthrange(year, month)[1])
    eng_start = engagement.start_date.date() if engagement and engagement.start_date and hasattr(engagement.start_date, 'date') else (engagement.start_date if engagement else None)
    eng_end = engagement.end_date.date() if engagement and engagement.end_date and hasattr(engagement.end_date, 'date') else (engagement.end_date if engagement else None)
    period_start = max(eng_start, month_start) if eng_start else month_start
    today = date.today()
    period_end = min((eng_end or today), month_end, today)
    if period_end < period_start:
        period_end = period_start
    return period_start, period_end


def _vat_band_label(treatment: str) -> str:
    """Render the VAT-band label for invoice line items."""
    return {
        "standard": "Expenses – Standard Rate (20%)",
        "reduced":  "Expenses – Reduced Rate (5%)",
        "zero":     "Expenses – Zero Rate (0%)",
        "non_vatable": "Expenses – Mileage / Non-VATable",
    }.get(treatment, f"Expenses – {treatment}")


def _engagement_billing_block(eng) -> dict:
    """IR 1, 10 — return the client billing block as a flat dict for the
    invoice generator, PDF renderer, and view template. Always returns a
    dict (empty strings rather than None) so consumers can render
    unconditionally."""
    if eng is None:
        return {"company_name": "", "addr1": "", "addr2": "", "city": "",
                "postcode": "", "company_reg": "", "vat_number": "", "po": ""}
    return {
        "company_name": (eng.client or "").strip(),
        "addr1": (getattr(eng, "billing_address_line1", "") or "").strip(),
        "addr2": (getattr(eng, "billing_address_line2", "") or "").strip(),
        "city": (getattr(eng, "billing_city", "") or "").strip(),
        "postcode": (getattr(eng, "billing_postcode", "") or "").strip(),
        "company_reg": (getattr(eng, "client_company_reg", "") or "").strip(),
        "vat_number": (getattr(eng, "client_vat_number", "") or "").strip(),
        "po": (getattr(eng, "purchase_order_number", "") or "").strip(),
    }


def _generate_invoice_payload(s, engagement_id: int, year: int, month: int) -> dict:
    """IR 7, 10, 13, 15 — aggregate Approved timesheets + their expense
    lines for (engagement, year, month). Returns dict ready to populate
    Invoice + line_items JSON.

    Output shape:
        {
            "engagement_id": ...,
            "client_name": ...,
            "engagement_name": ...,
            "period_start": date,
            "period_end": date,
            "invoice_date": date.today(),
            "due_date": date.today()+30,
            "line_items": [ { description, quantity, rate, amount, vat_pct } ... ],
            "subtotal": float,
            "vat_amount": float,
            "total_amount": float,
            "schedule_days_billed": [...],
            "schedule_expenses": [...],
        }"""
    eng = s.get(Engagement, engagement_id)
    if not eng:
        raise ValueError("Engagement not found")
    period_start, period_end = _invoice_period_for_month(eng, year, month)

    # Pull approved timesheets in the month.
    ts_rows = s.execute(text(
        "SELECT id, user_id, billable_days, day_rate, period_start, period_end, "
        "       COALESCE(timesheet_type,'Standard') AS ts_type "
        "FROM timesheets "
        "WHERE engagement_id = :eid AND LOWER(status) = 'approved' "
        "AND period_start >= :ps AND period_end <= :pe "
        "ORDER BY period_start"
    ).bindparams(eid=engagement_id, ps=period_start, pe=period_end)).all()

    # Associate name lookup.
    cand_ids = list({r.user_id for r in ts_rows if r.user_id})
    names = {}
    if cand_ids:
        cand_tuple = tuple(cand_ids)
        if len(cand_tuple) == 1:
            cand_tuple = (cand_tuple[0], cand_tuple[0])
        for cid, nm in s.execute(text(
            "SELECT id, name FROM candidates WHERE id IN :ids"
        ).bindparams(ids=cand_tuple)).all():
            names[cid] = nm

    # Day rate lookup from EngagementPlan if billable.day_rate is 0.
    # (We use the value already on the timesheet row when present.)

    # Build per-role line items + per-Associate-per-week schedule rows.
    # Adjustment timesheets (Phase 4 / TS 21) are surfaced as separate
    # labelled line items per IR 22/23 so the recipient sees the
    # "undercharge" / "overcharge" explicitly.
    role_buckets = {}  # role_label -> {days, rate}
    adjustment_lines = []   # list of dicts ready to become line_items
    schedule_days = []
    for r in ts_rows:
        rate = r.day_rate or 0
        days = r.billable_days or 0
        associate_name = names.get(r.user_id, "(unknown)")
        is_adjustment = (r.ts_type or "Standard") == "Adjustment"
        if is_adjustment:
            label_prefix = "Adjustment – undercharge" if days >= 0 else "Credit – overcharge"
            wc_str = r.period_start.strftime("%d %b %Y") if r.period_start else ""
            adjustment_lines.append({
                "description": f"{label_prefix} WC {wc_str}: {associate_name}",
                "quantity": abs(days),
                "rate": rate,
                "amount": days * rate,  # signed
                "vat_pct": 20.0,
                "vat_amount": days * rate * 0.20,
                "type": "adjustment",
            })
        else:
            # Standard timesheet — feeds into the role bucket grouped roll-up.
            role_label = "Day rate"
            bucket = role_buckets.setdefault(role_label, {"days": 0, "rate": rate})
            bucket["days"] += days
            if rate and not bucket["rate"]:
                bucket["rate"] = rate
        schedule_days.append({
            "wc": r.period_start,
            "associate": associate_name,
            "role": "Adjustment" if is_adjustment else "Day rate",
            "day_rate": rate,
            "days_billed": days,
            "net_amount": days * rate,
            "is_adjustment": is_adjustment,
        })

    # Pull expense lines.
    exp_rows = []
    if ts_rows:
        ts_ids = tuple(r.id for r in ts_rows)
        # SQL IN with a single-element tuple — append comma to keep python's
        # SQL parameter happy on some drivers.
        if len(ts_ids) == 1:
            ts_ids = (ts_ids[0], ts_ids[0])
        exp_rows = s.execute(text(
            "SELECT te.id, te.timesheet_id, te.expense_type, te.amount, te.vat_rate_pct, "
            "       te.vat_amount, te.date_of_expense, te.expense_category_id, "
            "       ec.vat_treatment, te.receipt_doc_id "
            "FROM timesheet_expenses te "
            "LEFT JOIN expense_categories ec ON ec.id = te.expense_category_id "
            "WHERE te.timesheet_id IN :ids"
        ).bindparams(ids=ts_ids)).all()

    # Group expenses by VAT band for page-1 summary lines (IR 15).
    band_totals = {}  # treatment -> {net, vat}
    schedule_expenses = []
    ts_user_by_id = {r.id: r.user_id for r in ts_rows}
    ts_wc_by_id = {r.id: r.period_start for r in ts_rows}
    for x in exp_rows:
        treatment = (x.vat_treatment or "standard")
        bucket = band_totals.setdefault(treatment, {"net": 0.0, "vat": 0.0})
        bucket["net"] += float(x.amount or 0)
        bucket["vat"] += float(x.vat_amount or 0)
        schedule_expenses.append({
            "wc": ts_wc_by_id.get(x.timesheet_id),
            "associate": names.get(ts_user_by_id.get(x.timesheet_id), "(unknown)"),
            "category": x.expense_type,
            "date": x.date_of_expense,
            "net": float(x.amount or 0),
            "vat_pct": float(x.vat_rate_pct or 0),
            "vat_amount": float(x.vat_amount or 0),
            "receipt_doc_id": x.receipt_doc_id,
        })

    # Build the line_items JSON array.
    line_items = []
    role_subtotal = 0.0
    role_vat = 0.0
    for role, b in role_buckets.items():
        net = b["days"] * b["rate"]
        vat_pct = 20.0
        vat = net * (vat_pct / 100.0)
        role_subtotal += net
        role_vat += vat
        line_items.append({
            "description": role,
            "quantity": b["days"],
            "rate": b["rate"],
            "amount": net,
            "vat_pct": vat_pct,
            "vat_amount": vat,
            "type": "role",
        })
    # Adjustment lines come immediately after the role lines (IR 24 — they
    # carry a distinct "adjustment" type so the PDF renderer can tint them).
    for adj in adjustment_lines:
        line_items.append(adj)
        role_subtotal += adj["amount"]
        role_vat += adj["vat_amount"]
    expense_subtotal = 0.0
    expense_vat = 0.0
    for treatment, b in sorted(band_totals.items()):
        if b["net"] <= 0:
            continue   # IR 15 — suppress empty VAT bands
        expense_subtotal += b["net"]
        expense_vat += b["vat"]
        line_items.append({
            "description": _vat_band_label(treatment),
            "quantity": 1,
            "rate": b["net"],
            "amount": b["net"],
            "vat_pct": {"standard": 20.0, "reduced": 5.0, "zero": 0.0, "non_vatable": 0.0}.get(treatment, 0.0),
            "vat_amount": b["vat"],
            "type": "expense_band",
        })

    subtotal = role_subtotal + expense_subtotal
    vat_amount = role_vat + expense_vat
    total_amount = subtotal + vat_amount

    return {
        "engagement_id": engagement_id,
        "client_name": eng.client or "",
        "engagement_name": eng.name or "",
        "client_billing": _engagement_billing_block(eng),
        "period_start": period_start,
        "period_end": period_end,
        "invoice_date": date.today(),
        "due_date": date.today() + timedelta(days=30),
        "line_items": line_items,
        "subtotal": subtotal,
        "vat_amount": vat_amount,
        "total_amount": total_amount,
        "schedule_days_billed": schedule_days,
        "schedule_expenses": schedule_expenses,
        "outstanding_timesheets": _check_timesheets_ready(s, engagement_id, year, month),
    }


def _reconcile_invoice_expense_totals(payload: dict) -> tuple:
    """IR 17, 18 — sum of schedule_expenses must equal sum of page-1
    expense_band line items (net AND VAT separately). Returns (ok, msg)."""
    sched_net = sum(x["net"] for x in payload.get("schedule_expenses", []))
    sched_vat = sum(x["vat_amount"] for x in payload.get("schedule_expenses", []))
    band_net = sum(li["amount"] for li in payload.get("line_items", []) if li.get("type") == "expense_band")
    band_vat = sum(li["vat_amount"] for li in payload.get("line_items", []) if li.get("type") == "expense_band")
    if round(sched_net, 2) != round(band_net, 2):
        return False, f"Expense net mismatch: schedule £{sched_net:.2f} vs page-1 £{band_net:.2f}"
    if round(sched_vat, 2) != round(band_vat, 2):
        return False, f"Expense VAT mismatch: schedule £{sched_vat:.2f} vs page-1 £{band_vat:.2f}"
    return True, "OK"


def _persist_invoice_pdf(s, invoice, pdf_bytes: bytes, subtype: str = "generated") -> int:
    """Phase 9 / IR 42 — store an invoice PDF in the existing Document
    store, linked to the invoice + engagement. Returns the Document.id.

    subtype: 'generated' (initial Generate) or 'sent' (a copy taken at
    send time so an audit-trail snapshot of what the client received is
    preserved even if the invoice is later edited)."""
    if not pdf_bytes:
        return None
    safe_name = f"{invoice.invoice_number}-{subtype}.pdf"
    # Filename on disk gets a uuid prefix to avoid collisions.
    disk_name = f"{uuid.uuid4().hex[:12]}-{safe_name}"
    try:
        os.makedirs(UPLOAD_FOLDER, exist_ok=True)
        with open(os.path.join(UPLOAD_FOLDER, disk_name), "wb") as f:
            f.write(pdf_bytes)
    except Exception:
        current_app.logger.exception("Failed to write invoice PDF to disk")
        return None
    doc = Document(
        candidate_id=None,
        doc_type=f"invoice_{subtype}",
        filename=disk_name,
        original_name=safe_name,
        engagement_id=invoice.engagement_id,
    )
    s.add(doc)
    s.flush()
    if subtype == "generated" and hasattr(invoice, "pdf_doc_id"):
        invoice.pdf_doc_id = doc.id
    return doc.id


def _existing_invoice_for_month(s, engagement_id: int, year: int, month: int):
    """IR 3 — one invoice per (engagement, year, month). Returns an existing
    non-Void Invoice for the engagement whose billing period falls in the
    given calendar month, or None. Matches on period_start (auto-generated
    invoices) and falls back to invoice_date for legacy/manual rows that have
    no period."""
    import calendar as _cal
    month_start = date(year, month, 1)
    month_end = date(year, month, _cal.monthrange(year, month)[1])
    for inv in s.scalars(
        select(Invoice).where(Invoice.engagement_id == engagement_id)
    ).all():
        if (inv.status or "").lower() == "void":
            continue
        anchor = inv.period_start
        if anchor is None and inv.invoice_date is not None:
            anchor = inv.invoice_date.date() if hasattr(inv.invoice_date, "date") else inv.invoice_date
        if anchor is not None and month_start <= anchor <= month_end:
            return inv
    return None


@app.route("/admin/invoices/auto-generate/<int:engagement_id>/<int:year>/<int:month>", methods=["POST"])
@login_required
def admin_auto_generate_invoice(engagement_id: int, year: int, month: int):
    """IR 7, 8, 10 — auto-generate a Draft invoice for (engagement, year, month)."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_invoices"))
    import json as _json
    with Session(engine) as s:
        eng = s.get(Engagement, engagement_id)
        if not eng:
            abort(404)
        # IR 3 — one invoice per (engagement, year, month). Refuse a duplicate.
        existing = _existing_invoice_for_month(s, engagement_id, year, month)
        if existing:
            flash(
                f"An invoice already exists for this project and month "
                f"({existing.invoice_number}, {existing.status}). "
                f"Open or void it before generating another.",
                "warning",
            )
            return redirect(url_for("admin_view_invoice", invoice_id=existing.id))
        outstanding = _check_timesheets_ready(s, engagement_id, year, month)
        if outstanding:
            names = ", ".join(f"TS-{r['id']:04d} ({r['status']})" for r in outstanding[:5])
            extra = "" if len(outstanding) <= 5 else f" (+{len(outstanding) - 5} more)"
            flash(f"Cannot generate — {len(outstanding)} timesheet(s) not yet Approved: {names}{extra}", "danger")
            return redirect(url_for("admin_invoices"))
        try:
            invoice_number = _next_invoice_number(s, eng)
        except ValueError as exc:
            flash(str(exc), "danger")
            return redirect(url_for("admin_invoices"))
        payload = _generate_invoice_payload(s, engagement_id, year, month)
        ok, msg = _reconcile_invoice_expense_totals(payload)
        if not ok:
            flash(f"Generation aborted — reconciliation failed: {msg}", "danger")
            return redirect(url_for("admin_invoices"))
        invoice = Invoice(
            invoice_number=invoice_number,
            engagement_id=engagement_id,
            client_name=payload["client_name"],
            engagement_name=payload["engagement_name"],
            invoice_date=datetime.datetime.combine(payload["invoice_date"], datetime.time()),
            due_date=datetime.datetime.combine(payload["due_date"], datetime.time()),
            subtotal=payload["subtotal"],
            vat_rate=20.0,
            vat_amount=payload["vat_amount"],
            total_amount=payload["total_amount"],
            status="Draft",
            line_items=_json.dumps(payload["line_items"]),
            notes="",
            payment_terms="Net 30",
            created_by=current_user.id,
            period_start=payload["period_start"],
            period_end=payload["period_end"],
        )
        s.add(invoice)
        s.flush()
        # Stamp consumed timesheets so adjustments are billed once.
        try:
            s.execute(text(
                "UPDATE timesheets SET invoiced_on_invoice_id = :iid "
                "WHERE engagement_id = :eid AND LOWER(status) = 'approved' "
                "AND period_start >= :ps AND period_end <= :pe "
                "AND invoiced_on_invoice_id IS NULL"
            ).bindparams(iid=invoice.id, eid=engagement_id,
                         ps=payload["period_start"], pe=payload["period_end"]))
        except Exception:
            pass
        # Phase 9 / IR 42 — render + persist the PDF up-front so the
        # invoice view can offer a "Download original" even before send.
        try:
            pdf_bytes = _generate_invoice_pdf(invoice, payload["line_items"])
            _persist_invoice_pdf(s, invoice, pdf_bytes, subtype="generated")
        except Exception:
            current_app.logger.exception("Initial PDF render/persist failed at auto-generate")
        s.commit()
        try:
            log_audit_event("create", "billing",
                            f"Auto-generated invoice {invoice_number} ({len(payload['line_items'])} lines, £{payload['total_amount']:.2f})",
                            "invoice", invoice.id, {"engagement_id": engagement_id, "year": year, "month": month})
        except Exception:
            pass
    flash(f"✅ Invoice {invoice_number} generated for {payload['period_start']} – {payload['period_end']} (£{payload['total_amount']:.2f}).", "success")
    return redirect(url_for("admin_invoices"))


def _next_invoice_number(s, engagement) -> str:
    """Phase 5 / IR 6 — generate the next invoice number in the new format
    INV-YYYY-MM-XXXXX-CC where:
      YYYY-MM = year-month of generation
      XXXXX   = 5-digit globally-sequential counter (never resets, never reused)
      CC      = the engagement's client_code (2-5 chars)

    Refuses if the engagement isn't linked to a confirmed Client. Legacy
    invoice rows (format INV-YYYYMM-NNNN) are unaffected — the new format
    coexists with them and `INV-` prefix searches still match either.

    The counter advance + format build is wrapped in a single UPDATE…
    RETURNING (or SELECT-then-UPDATE on SQLite) so concurrent invoice
    generation can't collide on the same number."""
    if engagement is None:
        raise ValueError("Engagement is required to generate an invoice number.")
    client = getattr(engagement, "client_rel", None)
    # Auto-link on the fly when the engagement carries a free-text
    # client name but was never run through create_engagement /
    # engagement_edit (so _ensure_client_linked was never invoked).
    # This means an admin who saved a project before the Client table
    # existed — or via a non-form path — doesn't have to manually link
    # before generating. The Client row will land as code_confirmed=False
    # which the next check still catches with the "needs admin review"
    # message, with a clear pointer to /admin/clients.
    if (client is None or not getattr(client, "client_code", "")) and (engagement.client or "").strip():
        client = _ensure_client_linked(s, engagement)
        s.flush()
    if client is None or not getattr(client, "client_code", ""):
        raise ValueError(
            "This engagement has no Client name on it yet. "
            "Open the engagement and set a Client, then try again."
        )
    if not getattr(client, "code_confirmed", False):
        raise ValueError(
            f"The auto-generated client code {client.client_code!r} for "
            f"\"{client.name}\" still needs an Admin to confirm it before "
            f"invoices can be generated. Go to /admin/clients, review the "
            f"code, click Confirm, then re-try."
        )

    # Atomic advance + read. Postgres supports UPDATE…RETURNING natively;
    # SQLite (dev) needs SELECT-then-UPDATE under a transaction. The Session
    # `s` is already in a transaction here, so both paths are safe.
    seq_val = None
    try:
        result = s.execute(text(
            "UPDATE invoice_sequence SET next_value = next_value + 1 "
            "WHERE id = (SELECT id FROM invoice_sequence ORDER BY id LIMIT 1) "
            "RETURNING next_value - 1"
        )).scalar()
        seq_val = result
    except Exception:
        # SQLite fallback — no RETURNING support before 3.35. Use lock/read/bump.
        row = s.execute(text("SELECT id, next_value FROM invoice_sequence ORDER BY id LIMIT 1")).first()
        if row:
            seq_val = row[1]
            s.execute(text("UPDATE invoice_sequence SET next_value = :v WHERE id = :id")
                      .bindparams(v=seq_val + 1, id=row[0]))
        else:
            # First run on a brand-new DB — seed and use 1.
            s.execute(text("INSERT INTO invoice_sequence (next_value) VALUES (2)"))
            seq_val = 1

    if seq_val is None:
        raise RuntimeError("Failed to advance invoice_sequence counter.")
    now = datetime.datetime.utcnow()
    return f"INV-{now.year}-{now.month:02d}-{int(seq_val):05d}-{client.client_code}"


@app.route("/admin/invoices/create", methods=["GET", "POST"])
@login_required
def admin_create_invoice():
    """Create a new invoice"""
    import json

    if request.method == "POST":
        with Session(engine) as s:
            # Phase 5 / IR 6 — new INV-YYYY-MM-XXXXX-CC format via the
            # Client-aware helper. Falls back to the legacy per-month format
            # only if the engagement has no Client linked yet AND legacy
            # behaviour is explicitly requested — we don't want to silently
            # generate without a client code, so we surface the error
            # instead. Existing legacy invoices keep their INV-YYYYMM-NNNN
            # numbers untouched.
            engagement_id = request.form.get("engagement_id")
            engagement = s.get(Engagement, int(engagement_id)) if engagement_id else None
            # IR 3 — one invoice per (engagement, year, month). A manual invoice
            # is dated today, so guard against an existing invoice this month.
            if engagement_id:
                _now = datetime.datetime.utcnow()
                _dup = _existing_invoice_for_month(s, int(engagement_id), _now.year, _now.month)
                if _dup:
                    flash(
                        f"An invoice already exists for this project this month "
                        f"({_dup.invoice_number}, {_dup.status}). "
                        f"Open or void it before creating another.",
                        "warning",
                    )
                    return redirect(url_for("admin_view_invoice", invoice_id=_dup.id))
            try:
                invoice_number = _next_invoice_number(s, engagement)
            except ValueError as exc:
                flash(str(exc), "danger")
                return redirect(url_for("admin_create_invoice"))

            # Get form data
            client_name = request.form.get("client_name", "").strip()
            engagement_name = request.form.get("engagement_name", "").strip()
            
            # Parse dates
            invoice_date = datetime.datetime.utcnow()
            due_date_str = request.form.get("due_date", "")
            due_date = None
            if due_date_str:
                try:
                    due_date = datetime.datetime.strptime(due_date_str, "%Y-%m-%d")
                except:
                    pass
            
            # Get line items from form
            line_items = []
            descriptions = request.form.getlist("item_description[]")
            quantities = request.form.getlist("item_quantity[]")
            rates = request.form.getlist("item_rate[]")
            
            subtotal = 0
            for i, desc in enumerate(descriptions):
                if desc.strip():
                    qty = float(quantities[i]) if i < len(quantities) and quantities[i] else 1
                    rate = float(rates[i]) if i < len(rates) and rates[i] else 0
                    amount = qty * rate
                    subtotal += amount
                    line_items.append({
                        "description": desc.strip(),
                        "quantity": qty,
                        "rate": rate,
                        "amount": amount
                    })
            
            # Calculate VAT
            vat_rate = float(request.form.get("vat_rate", 20))
            vat_amount = subtotal * (vat_rate / 100)
            total_amount = subtotal + vat_amount
            
            # Create invoice
            invoice = Invoice(
                invoice_number=invoice_number,
                engagement_id=int(engagement_id) if engagement_id else None,
                client_name=client_name,
                engagement_name=engagement_name,
                invoice_date=invoice_date,
                due_date=due_date,
                subtotal=subtotal,
                vat_rate=vat_rate,
                vat_amount=vat_amount,
                total_amount=total_amount,
                status="Draft",
                line_items=json.dumps(line_items),
                notes=request.form.get("notes", ""),
                payment_terms=request.form.get("payment_terms", "Net 30"),
                created_by=current_user.id
            )
            s.add(invoice)
            s.commit()
            
            log_audit_event('create', 'billing', f'Created invoice {invoice_number}',
                          'invoice', invoice.id, {'client': client_name, 'amount': total_amount})
            
            flash(f"✅ Invoice {invoice_number} created successfully!", "success")
            return redirect(url_for('admin_invoices'))
    
    # GET - show create form
    with Session(engine) as s:
        engagements = s.scalars(select(Engagement).order_by(Engagement.name)).all()
        return render_template("admin_invoice_create.html", engagements=engagements)

@app.route("/api/engagement/<int:eng_id>/invoice-lines")
@login_required
def api_engagement_invoice_lines(eng_id):
    """Return placed associates for an engagement as invoice line items."""
    with Session(engine) as s:
        results = s.execute(
            select(Candidate.name, Job.title, Application.offer_day_rate, Application.assignment_fee)
            .select_from(Application)
            .join(Candidate, Candidate.id == Application.candidate_id)
            .join(Job, Job.id == Application.job_id)
            .where(Job.engagement_id == eng_id)
            .where(Application.status.in_(["Placed", "Contract Signed", "On Assignment", "Active", "Contracted"]))
            .order_by(Candidate.name)
        ).all()
        lines = []
        for name, title, offer_rate, assign_fee in results:
            rate = 0
            if offer_rate:
                rate = float(offer_rate)
            elif assign_fee:
                import re as _re
                nums = _re.findall(r"[\d,]+\.?\d*", str(assign_fee).replace(",", ""))
                if nums:
                    try:
                        rate = float(nums[0])
                    except ValueError:
                        pass
            lines.append({
                "description": title or "Associate",
                "quantity": 1,
                "rate": rate,
            })
    return jsonify(lines)


@app.route("/admin/invoices/<int:invoice_id>")
@login_required
def admin_view_invoice(invoice_id):
    """View a single invoice"""
    import json
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found", "error")
            return redirect(url_for('admin_invoices'))

        line_items = json.loads(invoice.line_items) if invoice.line_items else []
        # IR 19 — surface any manually-overridden fields from the audit log.
        overridden_fields = []
        try:
            last_override = s.scalars(
                select(AuditLog)
                .where(AuditLog.event_type == "override")
                .where(AuditLog.resource_type == "invoice")
                .where(AuditLog.resource_id == invoice_id)
                .order_by(AuditLog.id.desc())
            ).first()
            if last_override and last_override.details:
                overridden_fields = json.loads(last_override.details).get("fields", [])
        except Exception:
            overridden_fields = []
        return render_template("admin_invoice_view.html", invoice=invoice,
                               line_items=line_items, overridden_fields=overridden_fields)

@app.route("/admin/invoices/<int:invoice_id>/edit", methods=["GET", "POST"])
@login_required
def admin_edit_invoice(invoice_id):
    """Edit an invoice"""
    import json
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found", "error")
            return redirect(url_for('admin_invoices'))

        # IR 31 — a Sent (or otherwise finalised) invoice is locked. It can
        # only be edited after an admin explicitly re-opens it back to Draft.
        if (invoice.status or "").lower() != "draft":
            flash(
                f"Invoice {invoice.invoice_number} is {invoice.status} and locked. "
                f"Use Re-open to return it to Draft before editing.",
                "warning",
            )
            return redirect(url_for("admin_view_invoice", invoice_id=invoice_id))

        if request.method == "POST":
            # IR 19/41 — snapshot the pre-edit values so each manual override
            # can be logged as (field, original, new).
            _before = {
                "client_name": invoice.client_name,
                "engagement_name": invoice.engagement_name,
                "notes": invoice.notes,
                "payment_terms": invoice.payment_terms,
                "due_date": invoice.due_date.strftime("%Y-%m-%d") if invoice.due_date else "",
                "line_items": invoice.line_items or "[]",
                "vat_rate": invoice.vat_rate,
                "subtotal": invoice.subtotal,
                "vat_amount": invoice.vat_amount,
                "total_amount": invoice.total_amount,
            }

            # Update invoice fields
            invoice.client_name = request.form.get("client_name", invoice.client_name)
            invoice.engagement_name = request.form.get("engagement_name", invoice.engagement_name)
            invoice.notes = request.form.get("notes", "")
            invoice.payment_terms = request.form.get("payment_terms", "Net 30")

            # Parse due date
            due_date_str = request.form.get("due_date", "")
            if due_date_str:
                try:
                    invoice.due_date = datetime.datetime.strptime(due_date_str, "%Y-%m-%d")
                except:
                    pass

            # Get line items
            line_items = []
            descriptions = request.form.getlist("item_description[]")
            quantities = request.form.getlist("item_quantity[]")
            rates = request.form.getlist("item_rate[]")

            subtotal = 0
            for i, desc in enumerate(descriptions):
                if desc.strip():
                    qty = float(quantities[i]) if i < len(quantities) and quantities[i] else 1
                    rate = float(rates[i]) if i < len(rates) and rates[i] else 0
                    amount = qty * rate
                    subtotal += amount
                    line_items.append({
                        "description": desc.strip(),
                        "quantity": qty,
                        "rate": rate,
                        "amount": amount
                    })

            # IR 11/20 — totals are recomputed server-side, never taken from
            # the form, so any line-item override rolls through automatically.
            invoice.line_items = json.dumps(line_items)
            invoice.subtotal = subtotal
            invoice.vat_rate = float(request.form.get("vat_rate", 20))
            invoice.vat_amount = subtotal * (invoice.vat_rate / 100)
            invoice.total_amount = subtotal + invoice.vat_amount

            # IR 19/41 — diff against the snapshot; record each changed field.
            _after = {
                "client_name": invoice.client_name,
                "engagement_name": invoice.engagement_name,
                "notes": invoice.notes,
                "payment_terms": invoice.payment_terms,
                "due_date": invoice.due_date.strftime("%Y-%m-%d") if invoice.due_date else "",
                "line_items": invoice.line_items or "[]",
                "vat_rate": invoice.vat_rate,
                "subtotal": invoice.subtotal,
                "vat_amount": invoice.vat_amount,
                "total_amount": invoice.total_amount,
            }
            overrides = [
                {"field": k, "original": _before[k], "new": _after[k]}
                for k in _after if _before.get(k) != _after.get(k)
            ]

            s.commit()

            if overrides:
                changed = ", ".join(o["field"] for o in overrides)
                log_audit_event(
                    "override", "billing",
                    f"Manually overrode invoice {invoice.invoice_number}: {changed}",
                    "invoice", invoice.id,
                    {"fields": overrides},
                )
            else:
                log_audit_event("update", "billing",
                                f"Edited invoice {invoice.invoice_number} (no field changes)",
                                "invoice", invoice.id)

            flash(
                f"✅ Invoice updated — {len(overrides)} field(s) overridden."
                if overrides else "✅ Invoice saved (no changes).",
                "success",
            )
            return redirect(url_for('admin_view_invoice', invoice_id=invoice.id))
        
        # GET - show edit form
        line_items = json.loads(invoice.line_items) if invoice.line_items else []
        engagements = s.scalars(select(Engagement).order_by(Engagement.name)).all()
        return render_template("admin_invoice_edit.html", invoice=invoice,
                             line_items=line_items, engagements=engagements)


@app.route("/admin/invoices/<int:invoice_id>/reopen", methods=["POST"])
@login_required
def admin_reopen_invoice(invoice_id: int):
    """IR 31 — admin re-opens a Sent/Overdue invoice back to Draft so it can
    be edited. Void and Paid invoices are not re-openable. Audit-logged."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_invoices"))
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found.", "warning")
            return redirect(url_for("admin_invoices"))
        old_status = (invoice.status or "")
        if old_status.lower() not in ("sent", "overdue"):
            flash(
                f"Only Sent or Overdue invoices can be re-opened "
                f"(this one is {old_status or 'Draft'}).",
                "warning",
            )
            return redirect(url_for("admin_view_invoice", invoice_id=invoice_id))
        invoice.status = "Draft"
        s.commit()
        try:
            log_audit_event("reopen", "billing",
                            f"Invoice {invoice.invoice_number} re-opened for editing (was {old_status})",
                            "invoice", invoice.id, {"old_status": old_status})
        except Exception:
            pass
    flash(f"Invoice {invoice.invoice_number} re-opened — it is now Draft and editable.", "success")
    return redirect(url_for("admin_edit_invoice", invoice_id=invoice_id))


@app.route("/admin/invoices/<int:invoice_id>/status", methods=["POST"])
@login_required
def admin_update_invoice_status(invoice_id):
    """Update invoice status"""
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found", "error")
            return redirect(url_for('admin_invoices'))
        
        new_status = request.form.get("status", invoice.status)
        old_status = invoice.status
        invoice.status = new_status
        
        if new_status == "Paid" and not invoice.paid_date:
            invoice.paid_date = datetime.datetime.utcnow()
        elif new_status == "Pending" and not invoice.sent_at:
            invoice.sent_at = datetime.datetime.utcnow()
        
        s.commit()
        
        log_audit_event('update', 'billing', f'Invoice {invoice.invoice_number} status: {old_status} → {new_status}',
                      'invoice', invoice.id)
        
        flash(f"✅ Invoice status updated to {new_status}", "success")
    
    return redirect(url_for('admin_invoices'))

@app.route("/admin/invoices/<int:invoice_id>/mark-paid", methods=["POST"])
@login_required
def admin_mark_invoice_paid(invoice_id: int):
    """Phase 8 / IR 35 — admin marks an invoice as Paid, capturing
    payment_date and payment_reference. Audit-logged."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_invoices"))
    payment_date_raw = (request.form.get("payment_date") or "").strip()
    payment_reference = (request.form.get("payment_reference") or "").strip()
    payment_date = None
    if payment_date_raw:
        try:
            payment_date = datetime.datetime.strptime(payment_date_raw, "%Y-%m-%d").date()
        except ValueError:
            pass
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found.", "warning")
            return redirect(url_for("admin_invoices"))
        old_status = invoice.status
        invoice.status = "Paid"
        invoice.paid_date = datetime.datetime.combine(payment_date, datetime.time()) if payment_date else datetime.datetime.utcnow()
        if hasattr(invoice, "payment_date"):
            invoice.payment_date = payment_date or date.today()
        if hasattr(invoice, "payment_reference"):
            invoice.payment_reference = payment_reference or None
        s.commit()
        try:
            log_audit_event("paid", "billing",
                            f"Invoice {invoice.invoice_number} marked as Paid (ref: {payment_reference or '-'})",
                            "invoice", invoice.id,
                            {"payment_date": payment_date_raw, "payment_reference": payment_reference,
                             "old_status": old_status})
        except Exception:
            pass
    flash(f"Invoice {invoice.invoice_number} marked Paid.", "success")
    return redirect(url_for("admin_view_invoice", invoice_id=invoice_id))


@app.route("/admin/invoices/<int:invoice_id>/void", methods=["POST"])
@login_required
def admin_void_invoice(invoice_id: int):
    """Phase 8 / IR 36 — admin voids an invoice. Preserves the row but
    marks it Void and excludes it from all financial summaries. Reason is
    mandatory."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_invoices"))
    reason = (request.form.get("void_reason") or "").strip()
    if not reason:
        flash("A reason is required to void an invoice.", "danger")
        return redirect(url_for("admin_view_invoice", invoice_id=invoice_id))
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found.", "warning")
            return redirect(url_for("admin_invoices"))
        old_status = invoice.status
        invoice.status = "Void"
        if hasattr(invoice, "void_reason"):
            invoice.void_reason = reason
        if hasattr(invoice, "voided_by"):
            invoice.voided_by = current_user.id
        if hasattr(invoice, "voided_at"):
            invoice.voided_at = datetime.datetime.utcnow()
        s.commit()
        try:
            log_audit_event("void", "billing",
                            f"Invoice {invoice.invoice_number} voided (was {old_status}): {reason}",
                            "invoice", invoice.id, {"old_status": old_status, "reason": reason})
        except Exception:
            pass
    flash(
        f"Invoice {invoice.invoice_number} voided." + (
            " You can issue a replacement or notify the client from the invoice view."
            if (old_status or "").lower() == "sent" else ""
        ),
        "success"
    )
    return redirect(url_for("admin_view_invoice", invoice_id=invoice_id))


@app.route("/admin/invoices/<int:invoice_id>/delete", methods=["POST"])
@login_required
def admin_delete_invoice(invoice_id):
    """Delete an invoice"""
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found", "error")
            return redirect(url_for('admin_invoices'))
        
        invoice_number = invoice.invoice_number
        s.delete(invoice)
        s.commit()
        
        log_audit_event('delete', 'billing', f'Deleted invoice {invoice_number}',
                      'invoice', invoice_id)
        
        flash(f"✅ Invoice {invoice_number} deleted", "success")
    
    return redirect(url_for('admin_invoices'))

def _generate_invoice_pdf(invoice, line_items):
    """Generate an invoice PDF using fpdf2. Returns bytes."""
    from fpdf import FPDF

    def _safe(text):
        """Replace unicode chars that latin-1 can't handle."""
        return (text or "").replace("\u2014", "-").replace("\u2013", "-").replace("\u2018", "'").replace("\u2019", "'").replace("\u201c", '"').replace("\u201d", '"').replace("\u2026", "...").replace("\u00a3", "GBP ")

    pdf = FPDF()
    pdf.add_page()
    pdf.set_auto_page_break(auto=True, margin=20)

    # Phase 11 / IR 30 — Optimus brand header. Logo image at top-left
    # (uses the existing static asset). The brand navy is #030a1d / RGB
    # (3, 10, 29); the secondary navy is #1e3a8a / RGB (30, 58, 138).
    try:
        _logo_path = os.path.join(os.path.dirname(__file__), "static", "images", "optimus-logo-header-new.png")
        if os.path.exists(_logo_path):
            pdf.image(_logo_path, x=10, y=10, h=14)
    except Exception:
        pass

    # Header text — block aligned to the right of the logo.
    pdf.set_xy(60, 10)
    pdf.set_font("Helvetica", "B", 24)
    pdf.set_text_color(30, 58, 138)
    pdf.cell(80, 12, "INVOICE", new_x="RIGHT")
    pdf.set_font("Helvetica", "B", 14)
    pdf.set_text_color(31, 41, 55)
    pdf.cell(0, 12, invoice.invoice_number or "", align="R", new_x="LMARGIN", new_y="NEXT")
    pdf.set_x(60)
    pdf.set_font("Helvetica", "", 10)
    pdf.set_text_color(107, 114, 128)
    pdf.cell(80, 6, "Optimus Operations Limited", new_x="RIGHT")
    date_str = invoice.invoice_date.strftime("%d %B %Y") if invoice.invoice_date else "N/A"
    pdf.cell(0, 6, f"Date: {date_str}", align="R", new_x="LMARGIN", new_y="NEXT")
    if invoice.due_date:
        pdf.cell(100, 6, "", new_x="RIGHT")
        pdf.cell(0, 6, f"Due: {invoice.due_date.strftime('%d %B %Y')}", align="R", new_x="LMARGIN", new_y="NEXT")
    pdf.cell(100, 6, "", new_x="RIGHT")
    pdf.cell(0, 6, f"Status: {invoice.status}", align="R", new_x="LMARGIN", new_y="NEXT")

    # Divider
    pdf.set_draw_color(30, 58, 138)
    pdf.set_line_width(0.8)
    pdf.line(10, pdf.get_y() + 4, 200, pdf.get_y() + 4)
    pdf.ln(12)

    # Bill To / Payment Terms — IR 10 — full client billing block sourced
    # from the engagement record (address, postcode, company reg, VAT,
    # purchase-order). Falls back to the legacy single-line client_name
    # when the engagement isn't reachable (e.g. orphaned legacy invoice).
    bb = _engagement_billing_block(getattr(invoice, "engagement", None))
    pdf.set_font("Helvetica", "", 8)
    pdf.set_text_color(107, 114, 128)
    pdf.cell(95, 5, "BILL TO", new_x="RIGHT")
    pdf.cell(0, 5, "PAYMENT TERMS", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "B", 12)
    pdf.set_text_color(31, 41, 55)
    pdf.cell(95, 7, _safe(bb["company_name"] or invoice.client_name or ""), new_x="RIGHT")
    pdf.cell(0, 7, _safe(invoice.payment_terms or "Net 30"), new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "", 10)
    pdf.set_text_color(107, 114, 128)
    if invoice.engagement_name:
        pdf.cell(0, 6, _safe(invoice.engagement_name), new_x="LMARGIN", new_y="NEXT")
    for line in (bb["addr1"], bb["addr2"]):
        if line:
            pdf.cell(0, 6, _safe(line), new_x="LMARGIN", new_y="NEXT")
    city_postcode = " ".join(p for p in (bb["city"], bb["postcode"]) if p).strip()
    if city_postcode:
        pdf.cell(0, 6, _safe(city_postcode), new_x="LMARGIN", new_y="NEXT")
    if bb["company_reg"]:
        pdf.cell(0, 6, _safe(f"Company Reg: {bb['company_reg']}"), new_x="LMARGIN", new_y="NEXT")
    if bb["vat_number"]:
        pdf.cell(0, 6, _safe(f"VAT Number: {bb['vat_number']}"), new_x="LMARGIN", new_y="NEXT")
    if bb["po"]:
        pdf.cell(0, 6, _safe(f"PO Number: {bb['po']}"), new_x="LMARGIN", new_y="NEXT")
    pdf.ln(10)

    # Line items table header
    pdf.set_fill_color(248, 250, 252)
    pdf.set_font("Helvetica", "B", 9)
    pdf.set_text_color(55, 65, 81)
    pdf.cell(95, 8, "  Description", border="B", fill=True, new_x="RIGHT")
    pdf.cell(25, 8, "Qty", border="B", fill=True, align="C", new_x="RIGHT")
    pdf.cell(35, 8, "Rate", border="B", fill=True, align="R", new_x="RIGHT")
    pdf.cell(35, 8, "Amount", border="B", fill=True, align="R", new_x="LMARGIN", new_y="NEXT")

    # Line items
    pdf.set_font("Helvetica", "", 10)
    pdf.set_text_color(31, 41, 55)
    for item in line_items:
        desc = _safe((item.get("description") or "")[:60])
        qty = str(item.get("quantity", ""))
        rate = f"£{item['rate']:,.2f}" if item.get("rate") else ""
        amount = f"£{(item.get('amount') or 0):,.2f}"
        pdf.cell(95, 8, f"  {desc}", border="B", new_x="RIGHT")
        pdf.cell(25, 8, qty, border="B", align="C", new_x="RIGHT")
        pdf.cell(35, 8, rate, border="B", align="R", new_x="RIGHT")
        pdf.cell(35, 8, amount, border="B", align="R", new_x="LMARGIN", new_y="NEXT")

    if not line_items:
        pdf.set_text_color(156, 163, 175)
        pdf.cell(190, 10, "No line items", align="C", new_x="LMARGIN", new_y="NEXT")
        pdf.set_text_color(31, 41, 55)

    pdf.ln(6)

    # Totals — right aligned
    x_label = 130
    x_val = 165
    pdf.set_font("Helvetica", "", 10)
    pdf.set_text_color(107, 114, 128)
    pdf.set_x(x_label)
    pdf.cell(35, 7, "Subtotal", new_x="RIGHT")
    pdf.cell(35, 7, f"£{(invoice.subtotal or 0):,.2f}", align="R", new_x="LMARGIN", new_y="NEXT")
    pdf.set_x(x_label)
    pdf.cell(35, 7, f"VAT ({invoice.vat_rate or 0:.1f}%)", new_x="RIGHT")
    pdf.cell(35, 7, f"£{(invoice.vat_amount or 0):,.2f}", align="R", new_x="LMARGIN", new_y="NEXT")

    # Total line
    pdf.set_draw_color(30, 58, 138)
    pdf.line(x_label, pdf.get_y() + 2, 200, pdf.get_y() + 2)
    pdf.ln(6)
    pdf.set_font("Helvetica", "B", 14)
    pdf.set_text_color(31, 41, 55)
    pdf.set_x(x_label)
    pdf.cell(35, 9, "Total", new_x="RIGHT")
    pdf.cell(35, 9, f"£{(invoice.total_amount or 0):,.2f}", align="R", new_x="LMARGIN", new_y="NEXT")

    # Notes
    if invoice.notes:
        pdf.ln(12)
        pdf.set_draw_color(229, 231, 235)
        pdf.line(10, pdf.get_y(), 200, pdf.get_y())
        pdf.ln(6)
        pdf.set_font("Helvetica", "B", 10)
        pdf.set_text_color(55, 65, 81)
        pdf.cell(0, 6, "Notes", new_x="LMARGIN", new_y="NEXT")
        pdf.set_font("Helvetica", "", 9)
        pdf.set_text_color(107, 114, 128)
        pdf.multi_cell(0, 5, _safe(invoice.notes))

    # IR 12 — mandated payment instruction.
    pdf.ln(12)
    pdf.set_draw_color(229, 231, 235)
    pdf.line(10, pdf.get_y(), 200, pdf.get_y())
    pdf.ln(6)
    pdf.set_font("Helvetica", "B", 10)
    pdf.set_text_color(55, 65, 81)
    pdf.cell(0, 6, "Payment Instructions", new_x="LMARGIN", new_y="NEXT")
    pdf.set_font("Helvetica", "", 9)
    pdf.set_text_color(107, 114, 128)
    pdf.multi_cell(0, 5, _safe(
        "Payment to be made within 30 days of invoice date. Please reference "
        "the invoice number when making payment. For queries contact "
        "finance@optimussolutions.co.uk."
    ))

    # Footer
    pdf.ln(16)
    pdf.set_font("Helvetica", "", 8)
    pdf.set_text_color(156, 163, 175)
    pdf.cell(0, 5, "Optimus - Financial Services Resourcing Specialists", align="C")

    # =====================================================================
    # Phase 9 / IR 16 — Billing Detail Schedule pages (page 2+).
    # Renders two sections matching the Example invoice.pdf:
    #   1. Days Billed (W/C, Associate, Role, Day Rate, Days Billed, Net)
    #   2. Expenses Breakdown (W/C, Associate, Category, Date, Net, VAT%, VAT)
    # Data is rebuilt from the invoice's engagement + period via
    # _generate_invoice_payload so the schedule always reconciles to page 1.
    # =====================================================================
    try:
        if invoice.engagement_id and invoice.period_start and invoice.period_end:
            with Session(engine) as _s:
                # Re-derive the schedule data (cheap — same query the
                # auto-generator used).
                _year = invoice.period_start.year if hasattr(invoice.period_start, 'year') else None
                _month = invoice.period_start.month if hasattr(invoice.period_start, 'month') else None
                if _year and _month:
                    sched = _generate_invoice_payload(_s, invoice.engagement_id, _year, _month)
                    pdf.add_page()
                    # Logo + title at top-right.
                    try:
                        _logo_path = os.path.join(os.path.dirname(__file__), "static", "images", "optimus-logo-header-new.png")
                        if os.path.exists(_logo_path):
                            pdf.image(_logo_path, x=10, y=10, h=14)
                    except Exception:
                        pass
                    pdf.set_xy(60, 10)
                    pdf.set_font("Helvetica", "B", 18)
                    pdf.set_text_color(30, 58, 138)
                    pdf.cell(0, 12, "BILLING DETAIL SCHEDULE", align="R", new_x="LMARGIN", new_y="NEXT")
                    pdf.set_xy(60, 24)
                    pdf.set_font("Helvetica", "", 9)
                    pdf.set_text_color(107, 114, 128)
                    pdf.cell(0, 5, f"Invoice {invoice.invoice_number} | Period {sched['period_start']} to {sched['period_end']}",
                             align="R", new_x="LMARGIN", new_y="NEXT")
                    pdf.ln(10)

                    # ----- Days Billed table -----
                    pdf.set_font("Helvetica", "B", 11)
                    pdf.set_text_color(31, 41, 55)
                    pdf.cell(0, 7, "DAYS BILLED", new_x="LMARGIN", new_y="NEXT")
                    pdf.ln(2)
                    pdf.set_fill_color(248, 250, 252)
                    pdf.set_font("Helvetica", "B", 8)
                    pdf.set_text_color(55, 65, 81)
                    pdf.cell(28, 7, "W/C", border="B", fill=True, new_x="RIGHT")
                    pdf.cell(55, 7, "Associate", border="B", fill=True, new_x="RIGHT")
                    pdf.cell(35, 7, "Role", border="B", fill=True, new_x="RIGHT")
                    pdf.cell(22, 7, "Day Rate", border="B", fill=True, align="R", new_x="RIGHT")
                    pdf.cell(20, 7, "Days", border="B", fill=True, align="R", new_x="RIGHT")
                    pdf.cell(30, 7, "Net", border="B", fill=True, align="R", new_x="LMARGIN", new_y="NEXT")
                    pdf.set_font("Helvetica", "", 8)
                    pdf.set_text_color(31, 41, 55)
                    for row in sched["schedule_days_billed"]:
                        wc = row["wc"].strftime("%d %b %Y") if row["wc"] else "—"
                        pdf.cell(28, 6, _safe(wc), border="B", new_x="RIGHT")
                        pdf.cell(55, 6, _safe(row["associate"][:30]), border="B", new_x="RIGHT")
                        pdf.cell(35, 6, _safe(row["role"][:20]), border="B", new_x="RIGHT")
                        pdf.cell(22, 6, f"£{row['day_rate']:,.2f}", border="B", align="R", new_x="RIGHT")
                        pdf.cell(20, 6, f"{row['days_billed']:.2f}", border="B", align="R", new_x="RIGHT")
                        pdf.cell(30, 6, f"£{row['net_amount']:,.2f}", border="B", align="R", new_x="LMARGIN", new_y="NEXT")
                    if not sched["schedule_days_billed"]:
                        pdf.set_text_color(156, 163, 175)
                        pdf.set_font("Helvetica", "I", 8)
                        pdf.cell(0, 6, "  (no approved timesheets in period)", border="B", new_x="LMARGIN", new_y="NEXT")

                    pdf.ln(8)
                    # ----- Expenses Breakdown table -----
                    pdf.set_font("Helvetica", "B", 11)
                    pdf.set_text_color(31, 41, 55)
                    pdf.cell(0, 7, "EXPENSES BREAKDOWN", new_x="LMARGIN", new_y="NEXT")
                    pdf.ln(2)
                    pdf.set_fill_color(248, 250, 252)
                    pdf.set_font("Helvetica", "B", 8)
                    pdf.set_text_color(55, 65, 81)
                    pdf.cell(25, 7, "W/C", border="B", fill=True, new_x="RIGHT")
                    pdf.cell(40, 7, "Associate", border="B", fill=True, new_x="RIGHT")
                    pdf.cell(35, 7, "Category", border="B", fill=True, new_x="RIGHT")
                    pdf.cell(25, 7, "Date", border="B", fill=True, new_x="RIGHT")
                    pdf.cell(25, 7, "Net", border="B", fill=True, align="R", new_x="RIGHT")
                    pdf.cell(15, 7, "VAT %", border="B", fill=True, align="R", new_x="RIGHT")
                    pdf.cell(25, 7, "VAT", border="B", fill=True, align="R", new_x="LMARGIN", new_y="NEXT")
                    pdf.set_font("Helvetica", "", 8)
                    pdf.set_text_color(31, 41, 55)
                    for row in sched["schedule_expenses"]:
                        wc = row["wc"].strftime("%d %b %Y") if row["wc"] else "—"
                        date_str = row["date"].strftime("%d %b %Y") if row.get("date") else "—"
                        pdf.cell(25, 6, _safe(wc), border="B", new_x="RIGHT")
                        pdf.cell(40, 6, _safe(row["associate"][:25]), border="B", new_x="RIGHT")
                        pdf.cell(35, 6, _safe((row["category"] or "")[:20]), border="B", new_x="RIGHT")
                        pdf.cell(25, 6, _safe(date_str), border="B", new_x="RIGHT")
                        pdf.cell(25, 6, f"£{row['net']:,.2f}", border="B", align="R", new_x="RIGHT")
                        pdf.cell(15, 6, f"{row['vat_pct']:.0f}%", border="B", align="R", new_x="RIGHT")
                        pdf.cell(25, 6, f"£{row['vat_amount']:,.2f}", border="B", align="R", new_x="LMARGIN", new_y="NEXT")
                    if not sched["schedule_expenses"]:
                        pdf.set_text_color(156, 163, 175)
                        pdf.set_font("Helvetica", "I", 8)
                        pdf.cell(0, 6, "  (no expenses in period)", border="B", new_x="LMARGIN", new_y="NEXT")

                    pdf.ln(10)
                    pdf.set_font("Helvetica", "", 7)
                    pdf.set_text_color(156, 163, 175)
                    pdf.cell(0, 5,
                        _safe("(c) Optimus Operations Limited  |  finance@optimussolutions.co.uk"),
                        align="C")
    except Exception:
        # Schedule pages are a bonus — if they fail, the page-1 invoice
        # still renders correctly. Don't kill the whole PDF.
        current_app.logger.exception("Billing detail schedule render failed")

    return pdf.output()


@app.route("/admin/invoices/<int:invoice_id>/pdf")
@login_required
def admin_invoice_pdf(invoice_id):
    """Generate and download invoice as PDF."""
    import json
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found", "error")
            return redirect(url_for('admin_invoices'))
        line_items = json.loads(invoice.line_items) if invoice.line_items else []
        # Sanitise line item values — ensure rate/amount are numeric
        for item in line_items:
            for key in ('rate', 'amount', 'quantity'):
                val = item.get(key)
                if val is not None and not isinstance(val, (int, float)):
                    try:
                        item[key] = float(str(val).replace(',', '').replace('£', ''))
                    except (ValueError, TypeError):
                        item[key] = 0
        try:
            pdf_bytes = _generate_invoice_pdf(invoice, line_items)
        except Exception as e:
            flash(f"PDF generation failed: {e}", "danger")
            return redirect(url_for('admin_invoices'))

    return Response(
        pdf_bytes,
        mimetype="application/pdf",
        headers={"Content-Disposition": f"attachment; filename={invoice.invoice_number or 'invoice'}.pdf"}
    )


@app.route("/admin/invoices/<int:invoice_id>/send", methods=["POST"])
@login_required
def admin_send_invoice(invoice_id):
    """Generate PDF and email the invoice to the client."""
    import json
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found", "error")
            return redirect(url_for('admin_invoices'))

        line_items = json.loads(invoice.line_items) if invoice.line_items else []

        # Generate PDF
        try:
            pdf_bytes = _generate_invoice_pdf(invoice, line_items)
        except Exception as e:
            flash(f"PDF generation failed: {e}", "danger")
            return redirect(url_for('admin_view_invoice', invoice_id=invoice_id))

        # Build email
        email_html = f"""
        <div style="font-family:'Inter',Arial,sans-serif;max-width:600px;margin:0 auto;">
            <div style="background:#0a1628;padding:24px;text-align:center;border-radius:8px 8px 0 0;">
                <h1 style="color:#00d4ff;margin:0;font-size:20px;">Optimus</h1>
            </div>
            <div style="background:#fff;padding:30px;border:1px solid #e5e7eb;border-radius:0 0 8px 8px;">
                <h2 style="color:#1f2937;margin:0 0 16px;">Invoice {invoice.invoice_number}</h2>
                <p style="color:#4b5563;">Please find attached invoice <strong>{invoice.invoice_number}</strong>
                for <strong>£{invoice.total_amount or 0:,.2f}</strong>.</p>
                <table style="width:100%;border-collapse:collapse;margin:16px 0;">
                    <tr><td style="padding:6px 0;color:#6b7280;">Client:</td><td style="padding:6px 0;font-weight:600;">{invoice.client_name}</td></tr>
                    <tr><td style="padding:6px 0;color:#6b7280;">Engagement:</td><td style="padding:6px 0;">{invoice.engagement_name or 'N/A'}</td></tr>
                    <tr><td style="padding:6px 0;color:#6b7280;">Due Date:</td><td style="padding:6px 0;font-weight:600;">{invoice.due_date.strftime('%d %B %Y') if invoice.due_date else 'N/A'}</td></tr>
                    <tr><td style="padding:6px 0;color:#6b7280;">Terms:</td><td style="padding:6px 0;">{invoice.payment_terms or 'Net 30'}</td></tr>
                </table>
                <p style="color:#6b7280;font-size:14px;">If you have any queries regarding this invoice, please contact your account manager.</p>
            </div>
        </div>
        """

        # Phase 7 / IR 28-29 — multi-recipient + editable subject/body.
        recipients_raw = (request.form.get("recipient_emails") or request.form.get("email") or "").strip()
        recipients = [e.strip() for e in re.split(r"[,;\s]+", recipients_raw) if e.strip() and "@" in e]
        if not recipients:
            # Fallback to engagement.invoice_recipient_emails if set.
            try:
                eng_row = s.get(Engagement, invoice.engagement_id) if invoice.engagement_id else None
                if eng_row and eng_row.invoice_recipient_emails:
                    recipients = json.loads(eng_row.invoice_recipient_emails) or []
            except Exception:
                pass
        if not recipients:
            flash("No client email found. Please enter at least one recipient.", "warning")
            return redirect(url_for('admin_view_invoice', invoice_id=invoice_id))

        subject = (request.form.get("email_subject") or f"Invoice {invoice.invoice_number} — Optimus").strip()
        body = (request.form.get("email_body") or "").strip()
        # Use editable body if provided, otherwise the default templated HTML.
        final_html = body or email_html

        try:
            # Req 53 / IR 27 — invoice emails come from finance@.
            for addr in recipients:
                send_email(
                    to_email=addr,
                    subject=subject,
                    html_body=final_html,
                    attachments=[(f"{invoice.invoice_number}.pdf", pdf_bytes, "application/pdf")],
                    from_email=FINANCE_FROM,
                )
            # Phase 7 / IR 31 — status flips to Sent (not Pending — that's
            # legacy naming; the boot-time migration also renames any
            # historical 'Pending' rows). sent_by + sent_recipients stamped.
            invoice.status = "Sent"
            if not invoice.sent_at:
                invoice.sent_at = datetime.datetime.utcnow()
            invoice.sent_by = current_user.id
            invoice.sent_recipients = json.dumps(recipients)
            # Phase 9 / IR 42 — second 'sent' copy of the PDF for audit.
            try:
                _persist_invoice_pdf(s, invoice, pdf_bytes, subtype="sent")
            except Exception:
                current_app.logger.exception("Send-time PDF persist failed")
            s.commit()
            try:
                log_audit_event("send", "billing",
                                f"Invoice {invoice.invoice_number} sent to {len(recipients)} recipient(s)",
                                "invoice", invoice.id,
                                {"recipients": recipients, "subject": subject})
            except Exception:
                pass
            flash(f"Invoice {invoice.invoice_number} sent to {', '.join(recipients)}", "success")
        except Exception as e:
            flash(f"Failed to send: {e}", "danger")

    return redirect(url_for('admin_view_invoice', invoice_id=invoice_id))


@app.route("/admin/invoices/<int:invoice_id>/resend", methods=["POST"])
@login_required
def admin_resend_invoice(invoice_id: int):
    """Phase 7 / IR 32 — resend an already-Sent invoice. Re-uses the
    existing PDF (no regeneration), keeps the same invoice number, logs
    as a 'resend' event in the audit log (NOT a new invoice)."""
    if (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_invoices"))
    import json as _json
    with Session(engine) as s:
        invoice = s.get(Invoice, invoice_id)
        if not invoice:
            flash("Invoice not found.", "warning")
            return redirect(url_for("admin_invoices"))
        if (invoice.status or "").lower() != "sent":
            flash(f"Resend only allowed for Sent invoices (this one is {invoice.status}).", "warning")
            return redirect(url_for("admin_view_invoice", invoice_id=invoice_id))
        recipients_raw = (request.form.get("recipient_emails") or "").strip()
        recipients = [e.strip() for e in re.split(r"[,;\s]+", recipients_raw) if e.strip() and "@" in e]
        if not recipients and invoice.sent_recipients:
            try:
                recipients = _json.loads(invoice.sent_recipients) or []
            except Exception:
                recipients = []
        if not recipients:
            flash("No recipients — pick at least one address before resending.", "warning")
            return redirect(url_for("admin_view_invoice", invoice_id=invoice_id))
        line_items = _json.loads(invoice.line_items) if invoice.line_items else []
        try:
            pdf_bytes = _generate_invoice_pdf(invoice, line_items)
        except Exception as e:
            flash(f"PDF re-render failed: {e}", "danger")
            return redirect(url_for("admin_view_invoice", invoice_id=invoice_id))
        subject = f"Reminder: Invoice {invoice.invoice_number} — Optimus"
        body = f"<p>This is a follow-up copy of invoice <strong>{invoice.invoice_number}</strong> for £{invoice.total_amount or 0:,.2f}.</p>"
        try:
            for addr in recipients:
                send_email(addr, subject, body,
                           attachments=[(f"{invoice.invoice_number}.pdf", pdf_bytes, "application/pdf")],
                           from_email=FINANCE_FROM)
            try:
                log_audit_event("resend", "billing",
                                f"Invoice {invoice.invoice_number} resent to {len(recipients)} recipient(s)",
                                "invoice", invoice.id, {"recipients": recipients})
            except Exception:
                pass
            flash(f"Invoice {invoice.invoice_number} re-sent.", "success")
        except Exception as e:
            flash(f"Resend failed: {e}", "danger")
    return redirect(url_for("admin_view_invoice", invoice_id=invoice_id))


@app.route("/admin/invoices/export")
@login_required
def admin_export_invoices():
    """Export invoices to CSV"""
    import csv
    import io
    
    with Session(engine) as s:
        invoices = s.scalars(select(Invoice).order_by(Invoice.invoice_date.desc())).all()
        
        output = io.StringIO()
        writer = csv.writer(output)
        
        # Header row
        writer.writerow([
            "Invoice Number", "Client", "Engagement", "Invoice Date", "Due Date",
            "Subtotal", "VAT Rate", "VAT Amount", "Total", "Status", "Paid Date"
        ])
        
        # Data rows
        for inv in invoices:
            writer.writerow([
                inv.invoice_number,
                inv.client_name,
                inv.engagement_name or "",
                inv.invoice_date.strftime("%Y-%m-%d") if inv.invoice_date else "",
                inv.due_date.strftime("%Y-%m-%d") if inv.due_date else "",
                f"{inv.subtotal:.2f}",
                f"{inv.vat_rate:.1f}%",
                f"{inv.vat_amount:.2f}",
                f"{inv.total_amount:.2f}",
                inv.status,
                inv.paid_date.strftime("%Y-%m-%d") if inv.paid_date else ""
            ])
        
        output.seek(0)
        
        log_audit_event('export', 'billing', f'Exported {len(invoices)} invoices to CSV')
        
        return Response(
            output.getvalue(),
            mimetype="text/csv",
            headers={"Content-Disposition": f"attachment;filename=invoices_export_{datetime.datetime.utcnow().strftime('%Y%m%d')}.csv"}
        )

@app.route("/admin/invoices/settings", methods=["GET", "POST"])
@login_required
def admin_invoice_settings():
    """Invoice settings page — editable for admin users."""
    settings = {}
    try:
        with Session(engine) as s:
            row = s.execute(text("SELECT config FROM invoice_settings LIMIT 1")).first()
            if row and row[0]:
                settings = json.loads(row[0])
    except Exception:
        pass

    if request.method == "POST":
        settings = {
            "company_name": request.form.get("company_name", "").strip(),
            "company_reg": request.form.get("company_reg", "").strip(),
            "vat_number": request.form.get("vat_number", "").strip(),
            "default_vat_rate": request.form.get("default_vat_rate", "20").strip(),
            "company_address": request.form.get("company_address", "").strip(),
            "payment_terms": request.form.get("payment_terms", "Net 30").strip(),
            "invoice_prefix": request.form.get("invoice_prefix", "INV").strip(),
            "default_notes": request.form.get("default_notes", "").strip(),
            "bank_name": request.form.get("bank_name", "").strip(),
            "account_name": request.form.get("account_name", "").strip(),
            "sort_code": request.form.get("sort_code", "").strip(),
            "account_number": request.form.get("account_number", "").strip(),
        }
        try:
            with engine.connect().execution_options(isolation_level="AUTOCOMMIT") as c:
                try:
                    c.execute(text("CREATE TABLE IF NOT EXISTS invoice_settings (id SERIAL PRIMARY KEY, config TEXT DEFAULT '{}')"))
                except Exception:
                    pass
                existing = c.execute(text("SELECT id FROM invoice_settings LIMIT 1")).first()
                if existing:
                    c.execute(text("UPDATE invoice_settings SET config = :cfg WHERE id = :id").bindparams(cfg=json.dumps(settings), id=existing[0]))
                else:
                    c.execute(text("INSERT INTO invoice_settings (config) VALUES (:cfg)").bindparams(cfg=json.dumps(settings)))
            flash("Invoice settings saved.", "success")
        except Exception as e:
            flash(f"Failed to save settings: {e}", "danger")
        return redirect(url_for("admin_invoice_settings"))

    return render_template("admin_invoice_settings.html", settings=settings)

# ============================================================================
# Phase 0 — Admin CRUD: clients, expense categories, company settings
# ============================================================================
#
# Three new admin-only pages plumb the Phase 0 foundations into the UI. The
# role gate mirrors admin_workflow_stages below: only users whose role is
# 'admin' (case-insensitive) can reach them. Every CRUD path writes through
# log_audit_event (app.py:1547) so changes are traceable.

def _company_settings() -> dict:
    """Return the central company_settings JSON as a Python dict.
    Used by invoice numbering, mileage calc, PDF retention etc. Falls back
    to a safe default if the row hasn't been seeded yet."""
    try:
        with engine.connect() as c:
            row = c.execute(text("SELECT config FROM company_settings ORDER BY id LIMIT 1")).first()
            if row and row[0]:
                return json.loads(row[0])
    except Exception:
        pass
    return {"hmrc_mileage_rate": 0.45, "pdf_retention_days": 2555, "default_vat_rate": 20}


def _require_admin():
    """Shared helper for the three Phase 0 admin pages. Mirrors the
    admin_workflow_stages role gate (app.py:2597-2600)."""
    if not current_user.is_authenticated or (current_user.role or "").lower() != "admin":
        flash("Admin access required.", "danger")
        return redirect(url_for("index"))
    return None


def _associate_ts_permissions(session_obj, user_id: int, engagement_id: int, week_start) -> dict:
    """Look up whether an Associate is allowed to claim Overtime and/or
    Expenses on a given week (week_start is the Monday of the WC).
    Default state with no matching row = both OFF.

    Returns {"overtime_enabled": bool, "expense_enabled": bool}.

    Multiple overlapping permission rows union together — any row with
    overtime_enabled=TRUE that covers the WC turns it on; same for
    expenses. This makes "Bulk apply" behave as expected: layering
    a project-duration permit over a one-week permit can't accidentally
    revoke the broader grant.
    """
    if not user_id or not engagement_id or not week_start:
        return {"overtime_enabled": False, "expense_enabled": False}
    try:
        wc = week_start.date() if hasattr(week_start, "date") else week_start
    except Exception:
        wc = week_start
    try:
        row = session_obj.execute(text(
            "SELECT "
            "  BOOL_OR(COALESCE(overtime_enabled, FALSE)) AS ot, "
            "  BOOL_OR(COALESCE(expense_enabled,  FALSE)) AS ex "
            "FROM associate_ts_permissions "
            "WHERE user_id = :uid AND engagement_id = :eid "
            "  AND effective_from <= :wc "
            "  AND (effective_to IS NULL OR effective_to >= :wc)"
        ).bindparams(uid=user_id, eid=engagement_id, wc=wc)).first()
        if row:
            return {"overtime_enabled": bool(row.ot), "expense_enabled": bool(row.ex)}
    except Exception:
        # SQLite lacks BOOL_OR — fall back to MAX(...) over INTEGER cast.
        try:
            row = session_obj.execute(text(
                "SELECT "
                "  MAX(CASE WHEN overtime_enabled THEN 1 ELSE 0 END) AS ot, "
                "  MAX(CASE WHEN expense_enabled  THEN 1 ELSE 0 END) AS ex "
                "FROM associate_ts_permissions "
                "WHERE user_id = :uid AND engagement_id = :eid "
                "  AND effective_from <= :wc "
                "  AND (effective_to IS NULL OR effective_to >= :wc)"
            ).bindparams(uid=user_id, eid=engagement_id, wc=wc)).first()
            if row:
                return {"overtime_enabled": bool(row[0]), "expense_enabled": bool(row[1])}
        except Exception:
            pass
    return {"overtime_enabled": False, "expense_enabled": False}


# ---- Clients ----

# ============================================================================
# Approver Portal Administration (/admin/approver-portal)
# ============================================================================
# Central place for an Admin to:
#   - See every approver allocation across every engagement
#   - Create / invite a new approver user (magic-link onboarding)
#   - Reset a forgotten password (fresh magic link)
#   - Deactivate / reactivate an approver
#   - Click straight through to the live approver portal at /approver
# Reuses the same magic-link pattern as admin_create_user (app.py:1027).

@app.route("/admin/approver-portal", methods=["GET"])
@login_required
def admin_approver_portal():
    if (current_user.role or "").lower() not in ("admin", "super_admin"):
        flash("Admin access required.", "danger")
        return redirect(url_for("index"))
    with Session(engine) as s:
        # Single combined view: one row per (approver-user × engagement-allocation).
        # A user appears here when ANY of these are true:
        #   1. Their primary role is 'approver' (dedicated approver-only login)
        #   2. They are flagged is_approver = TRUE (any role; capability is
        #      additive so e.g. an Admin or Associate can also approve)
        #   3. They have an engagement_approvers allocation
        # Users matching (1) or (2) but with no allocation still appear once
        # with NULL engagement columns, so admins can allocate / reset /
        # deactivate them.
        rows = s.execute(text("""
            SELECT u.id AS user_id, u.name AS user_name, u.email AS user_email,
                   u.role AS user_role, u.is_active, u.last_login,
                   ea.id AS alloc_id, ea.role AS alloc_role,
                   ea.created_at AS allocated_at,
                   e.id AS eng_id, e.ref AS eng_ref, e.name AS eng_name,
                   e.client AS client_name
            FROM users u
            LEFT JOIN engagement_approvers ea ON ea.user_id = u.id
            LEFT JOIN engagements e ON e.id = ea.engagement_id
            WHERE LOWER(u.role) = 'approver'
               OR u.is_approver = TRUE
               OR ea.id IS NOT NULL
            ORDER BY u.name, e.client, e.name
        """)).all()
        engagements = s.execute(text(
            "SELECT id, ref, name, client FROM engagements ORDER BY client, name"
        )).all()
    return render_template(
        "admin_approver_portal.html",
        rows=rows,
        engagements=engagements,
    )


@app.route("/admin/approver-portal/create", methods=["POST"])
@login_required
def admin_approver_portal_create():
    """Create a new approver user with a magic-link onboarding email."""
    if (current_user.role or "").lower() not in ("admin", "super_admin"):
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_approver_portal"))
    import secrets
    name = (request.form.get("name") or "").strip()
    email = (request.form.get("email") or "").strip().lower()
    send_magic_link = request.form.get("send_magic_link") == "1"
    allocate_engagement_id = request.form.get("allocate_engagement_id") or ""
    if not name or not email:
        flash("Name and email are required.", "warning")
        return redirect(url_for("admin_approver_portal"))
    with Session(engine) as s:
        existing = s.scalar(select(User).where(User.email == email))
        if existing:
            # Existing user — flag them as an approver (additive capability;
            # original role preserved) so they appear in the listing whether
            # or not an engagement was picked. If an engagement was picked,
            # also create the engagement_approvers allocation in the same
            # request so the admin can complete both steps in one click.
            existing_role = (existing.role or "user")
            already_flagged = bool(existing.is_approver)
            existing.is_approver = True
            alloc_msg = ""
            if allocate_engagement_id:
                try:
                    eng_id = int(allocate_engagement_id)
                except ValueError:
                    eng_id = 0
                if eng_id:
                    already = s.execute(text(
                        "SELECT id FROM engagement_approvers WHERE engagement_id = :eid AND user_id = :uid LIMIT 1"
                    ).bindparams(eid=eng_id, uid=existing.id)).first()
                    if already:
                        alloc_msg = " They were already allocated to the selected engagement."
                    else:
                        s.add(EngagementApprover(engagement_id=eng_id, user_id=existing.id, role='primary'))
                        alloc_msg = " Also allocated to the selected engagement."
            s.commit()
            try:
                log_audit_event(
                    "update", "user_mgmt",
                    f"Existing {existing_role} user {email} flagged as approver"
                    + (f" + allocated to engagement {allocate_engagement_id}" if allocate_engagement_id else ""),
                    "user", existing.id,
                    {"existing_role": existing_role, "was_already_flagged": already_flagged,
                     "engagement_id": allocate_engagement_id or None},
                )
            except Exception:
                pass
            flash(
                f"✅ {existing.name or email} (existing {existing_role} user) is now listed "
                f"as an approver. Their existing login is unchanged.{alloc_msg}",
                "success",
            )
            return redirect(url_for("admin_approver_portal"))
        magic_token = secrets.token_urlsafe(32)
        magic_expires = datetime.datetime.utcnow() + datetime.timedelta(hours=48)
        # Approver-only account: credentials live on the approver_*
        # columns. password_hash is set to a throwaway random so the
        # NOT-NULL DB constraint is satisfied — the main OS1 login is
        # NOT meant to be used for this account; only /approver/login.
        new_user = User(
            name=name,
            email=email,
            password_hash=generate_password_hash(secrets.token_urlsafe(32), method='pbkdf2:sha256'),
            role='approver',
            is_active=True,
            is_approver=True,
            created_at=datetime.datetime.utcnow(),
            approver_magic_token=magic_token,
            approver_magic_token_expires=magic_expires,
        )
        s.add(new_user)
        s.flush()
        new_user_id = new_user.id
        # Optionally allocate immediately to an engagement.
        if allocate_engagement_id:
            try:
                eng_id = int(allocate_engagement_id)
                if not s.execute(text(
                    "SELECT id FROM engagement_approvers WHERE engagement_id = :eid AND user_id = :uid LIMIT 1"
                ).bindparams(eid=eng_id, uid=new_user_id)).first():
                    s.add(EngagementApprover(engagement_id=eng_id, user_id=new_user_id, role='primary'))
            except ValueError:
                pass
        s.commit()
        try:
            log_audit_event("create", "user_mgmt", f"Approver user created: {email}",
                            "user", new_user_id, {"role": "approver", "allocated_to": allocate_engagement_id or None})
        except Exception:
            pass
        magic_link_url = request.url_root.rstrip('/') + url_for('approver.onboard', token=magic_token)
        if send_magic_link:
            try:
                html_body = f"""
                <html><body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
                    <div style="max-width: 600px; margin: 0 auto; padding: 20px;">
                        <h2 style="color: #1e3a8a;">Welcome to the Optimus Approver Portal</h2>
                        <p>Hi {name},</p>
                        <p>You've been added as an approver. Click below to set your password and sign in:</p>
                        <div style="text-align: center; margin: 30px 0;">
                            <a href="{magic_link_url}" style="background: #1e3a8a; color: white; padding: 15px 30px; text-decoration: none; border-radius: 8px; display: inline-block; font-weight: bold; font-size: 16px;">
                                Set Your Password
                            </a>
                        </div>
                        <p style="color: #666; font-size: 14px;"><i>This link expires in 48 hours.</i></p>
                        <hr><p style="color: #999; font-size: 12px;">Automated message from Optimus OS1.</p>
                    </div>
                </body></html>
                """
                send_email(email, "Welcome to the Optimus Approver Portal", html_body)
                flash(f"✅ Approver {name} created — magic link sent to {email}.", "success")
            except Exception as e:
                flash(f"⚠️ Approver created but email failed: {e}. Share this link instead: {magic_link_url}", "warning")
        else:
            flash(f"✅ Approver {name} created. Share this magic link with them:", "success")
            flash(f"🔗 {magic_link_url}", "info")
    return redirect(url_for("admin_approver_portal"))


@app.route("/admin/approver-portal/<int:user_id>/reset-password", methods=["POST"])
@login_required
def admin_approver_portal_reset(user_id: int):
    """Generate a fresh magic link for an existing approver (password reset)."""
    if (current_user.role or "").lower() not in ("admin", "super_admin"):
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_approver_portal"))
    import secrets
    send_email_flag = request.form.get("send_email") == "1"
    with Session(engine) as s:
        u = s.get(User, user_id)
        if not u:
            flash("User not found.", "warning")
            return redirect(url_for("admin_approver_portal"))
        # Reset the APPROVER-side token only; the user's main OS1
        # magic_token / password remain untouched so a user with both
        # logins keeps their primary access while setting up approver.
        u.approver_magic_token = secrets.token_urlsafe(32)
        u.approver_magic_token_expires = datetime.datetime.utcnow() + datetime.timedelta(hours=48)
        s.commit()
        link = request.url_root.rstrip('/') + url_for('approver.onboard', token=u.approver_magic_token)
        try:
            log_audit_event("update", "user_mgmt", f"Password reset link generated for approver {u.email}",
                            "user", user_id, {})
        except Exception:
            pass
        if send_email_flag:
            try:
                html = f"""
                <html><body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
                <h2 style="color:#1e3a8a;">Password reset — Optimus Approver Portal</h2>
                <p>Hi {u.name},</p>
                <p>A password reset has been requested for your approver account. Click the button below to set a new password:</p>
                <p style="text-align:center;margin:24px 0;">
                  <a href="{link}" style="background:#1e3a8a;color:#fff;padding:14px 28px;border-radius:8px;text-decoration:none;font-weight:bold;">Reset password</a>
                </p>
                <p style="color:#666;font-size:13px;">Link valid for 48 hours. If you didn't request this, contact Optimus support.</p>
                </body></html>
                """
                send_email(u.email, "Password reset — Optimus Approver Portal", html)
                flash(f"✅ Reset link emailed to {u.email}.", "success")
            except Exception as e:
                flash(f"⚠️ Reset link generated but email failed: {e}. Share manually: {link}", "warning")
        else:
            flash(f"✅ Reset link for {u.email}:", "success")
            flash(f"🔗 {link}", "info")
    return redirect(url_for("admin_approver_portal"))


@app.route("/admin/approver-portal/<int:user_id>/reset-2fa", methods=["POST"])
@login_required
def admin_approver_portal_reset_2fa(user_id: int):
    """Reset the APPROVER-side 2FA only — clears approver_totp_secret
    and disables approver_totp_enabled. The user's main OS1 2FA (if
    any) is intentionally untouched: these are two independent
    enrolments. Audit-logged so we know who cleared whose."""
    if (current_user.role or "").lower() not in ("admin", "super_admin"):
        flash("Admin access required.", "danger")
        return redirect(url_for("admin_approver_portal"))
    with Session(engine) as s:
        u = s.get(User, user_id)
        if not u:
            flash("User not found.", "warning")
            return redirect(url_for("admin_approver_portal"))
        had_2fa = bool(getattr(u, "approver_totp_enabled", False)
                       and getattr(u, "approver_totp_secret", None))
        u.approver_totp_secret = None
        u.approver_totp_enabled = False
        s.commit()
        try:
            log_audit_event(
                "update", "user_mgmt",
                f"Approver 2FA reset for {u.email} (was_enabled={had_2fa})",
                "user", user_id, {"approver_totp_enabled_before": had_2fa},
            )
        except Exception:
            pass
    if had_2fa:
        flash(f"Approver 2FA cleared for {u.email}. They will not be prompted for "
              f"a code on next sign-in until they re-enrol.", "success")
    else:
        flash(f"{u.email} had no approver 2FA configured — nothing to clear.", "info")
    return redirect(url_for("admin_approver_portal"))


