@app.route("/action/umbrella-assignment-signed/<int:cand_id>", methods=["POST"])
@login_required
def mark_umbrella_assignment_signed(cand_id: int):
    """Follow-up to mark_umbrella_assignment_sent: staff confirm that
    the signed document has come back from the umbrella / Ltd Co."""
    choice = (request.form.get("signed") or "").strip().lower()
    if choice not in ("yes", "no"):
        flash("Pick Yes or No.", "warning")
        return redirect(url_for("candidate_profile", cand_id=cand_id))
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)
        was = getattr(cand, "umbrella_assignment_signed", None)

        if choice == "yes":
            # Req 18 — staff must upload the signed contract PDF before
            # progression. If a signed-contract Document is already on
            # file we accept that; otherwise an upload is mandatory.
            uploaded = request.files.get("signed_contract")
            has_existing = _has_signed_contract_doc(s, cand_id)
            if not has_existing and (not uploaded or not uploaded.filename):
                flash(
                    "Please attach the signed contract PDF before confirming.",
                    "danger",
                )
                return redirect(url_for("candidate_profile", cand_id=cand_id))
            if uploaded and uploaded.filename:
                try:
                    _save_signed_contract_doc(s, uploaded, candidate_id=cand_id)
                except ValueError as exc:
                    flash(f"Signed contract upload rejected: {exc}", "danger")
                    return redirect(url_for("candidate_profile", cand_id=cand_id))

            # Req 17 — Profile "Confirm signed" tick now routes through
            # the same helper as the kanban "Confirm Contract Signed"
            # tick so the kanban card moves to Placed, the candidate
            # status becomes "On Assignment", the ESigRequest is flipped
            # to "signed", and the audit log + CandidateNote both fire
            # consistently.
            try:
                _apply_contract_signed(s, cand, source="profile_confirm_signed")
                s.commit()
            except Exception as exc:
                # Req 18 — convert unexpected helper failures to a flash
                # error rather than a raw 500.
                s.rollback()
                current_app.logger.exception(
                    "mark_umbrella_assignment_signed (yes) failed for cand %s", cand_id,
                )
                flash(f"Could not confirm contract signed: {exc}", "danger")
                return redirect(url_for("candidate_profile", cand_id=cand_id))
        else:
            cand.umbrella_assignment_signed = False
            cand.umbrella_assignment_signed_at = datetime.datetime.utcnow()
            user_email = getattr(current_user, "email", "staff") or "staff"
            s.add(CandidateNote(
                candidate_id=cand_id,
                user_email=user_email,
                note_type="activity",
                content=(
                    f"Umbrella Assignment Schedule marked as NOT signed yet "
                    f"(was {'signed' if was else 'not signed' if was is False else 'not recorded'})."
                ),
                created_at=datetime.datetime.utcnow(),
            ))
            s.commit()
    flash(
        f"Assignment Schedule recorded as {'signed' if choice == 'yes' else 'not signed yet'}.",
        "success",
    )
    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/candidate/<int:cand_id>/assign-owner", methods=["POST"])
@login_required
def assign_candidate_owner(cand_id: int):
    owner_id = request.form.get("owner_id", type=int)
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)
        if owner_id:
            user_row = s.execute(text("SELECT name FROM users WHERE id = :uid").bindparams(uid=owner_id)).first()
            cand.owner_id = owner_id
            cand.owner_name = user_row[0] if user_row else ""
            # Also assign this owner to all unassigned vetting checks
            s.execute(text("""
                UPDATE vetting_check SET assigned_to = :uid
                WHERE candidate_id = :cid AND (assigned_to IS NULL OR assigned_to = 0)
            """).bindparams(uid=owner_id, cid=cand_id))
        else:
            cand.owner_id = None
            cand.owner_name = ""
        _owner_display = cand.owner_name or "Unassigned"
        s.commit()
    flash(f"Owner updated to {_owner_display}.", "success")
    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/candidate/<int:cand_id>/schedule-interview", methods=["POST"])
@login_required
def schedule_interview(cand_id: int):
    date_str = request.form.get("interview_date", "")
    time_str = request.form.get("interview_time", "")
    if not date_str or not time_str:
        flash("Date and time are required.", "warning")
        return redirect(url_for("candidate_profile", cand_id=cand_id))
    try:
        scheduled_dt = datetime.datetime.strptime(f"{date_str} {time_str}", "%Y-%m-%d %H:%M")
    except ValueError:
        flash("Invalid date/time format.", "danger")
        return redirect(url_for("candidate_profile", cand_id=cand_id))
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)
        # Prefer the newest non-placed application for interview scheduling
        # (a new Pipeline app is the one being interviewed, not an existing Placed one)
        latest_app = s.scalar(
            select(Application).where(
                Application.candidate_id == cand_id,
                Application.status.notin_(["Placed", "Contract Signed", "Contracted", "Active", "Hired"])
            ).order_by(Application.created_at.desc())
        )
        if not latest_app:
            latest_app = s.scalar(
                select(Application).where(Application.candidate_id == cand_id)
                .order_by(Application.created_at.desc())
            )
        if not latest_app:
            flash("No application found for this candidate.", "warning")
            return redirect(url_for("candidate_profile", cand_id=cand_id))
        latest_app.interview_scheduled_at = scheduled_dt
        # Req 9 — scheduling an interview always advances the kanban to
        # I&A unless the application is already PAST that stage (e.g. it
        # has come back round to be re-interviewed after Client Review).
        # Compares case-insensitively so "Shortlist" / "shortlist" both
        # match. Past-I&A stages keep their existing column.
        _past_ia = {
            "client review", "interview completed", "offered", "accepted",
            "ready to contract", "contract issued", "contract sent",
            "contract signed", "placed", "on contract", "rejected",
            "withdrawn", "closed", "ended", "hired",
        }
        if (latest_app.status or "").strip().lower() not in _past_ia:
            latest_app.status = "I&A"

        s.add(CandidateNote(
            candidate_id=cand_id,
            user_email=getattr(current_user, "email", "staff") or "staff",
            note_type="activity",
            content=f"Interview scheduled for {scheduled_dt.strftime('%d %b %Y at %H:%M')}.",
            created_at=datetime.datetime.utcnow(),
        ))
        s.commit()
    flash(f"Interview scheduled for {scheduled_dt.strftime('%d %b %Y at %H:%M')}.", "success")
    return redirect(url_for("candidate_profile", cand_id=cand_id) + "?action=send_interview_email")


@app.route("/api/interview/email-preview/<int:cand_id>")
@login_required
def api_interview_email_preview(cand_id):
    """Return the interview invitation email template pre-filled for this candidate."""
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            return jsonify({"subject": "", "body": ""}), 404
        latest_app = s.scalar(
            select(Application).where(Application.candidate_id == cand_id)
            .order_by(Application.created_at.desc())
        )
        job = s.get(Job, latest_app.job_id) if latest_app and latest_app.job_id else None
        eng = s.get(Engagement, job.engagement_id) if job and job.engagement_id else None
        scheduled_dt = latest_app.interview_scheduled_at if latest_app else None

        tpl = s.scalar(select(EmailTemplate).where(EmailTemplate.name == "interview_invitation"))
        subject = (tpl.subject if tpl else "Interview Confirmation") or "Interview Confirmation"
        body = (tpl.body if tpl else "") or ""

        # Req 8 — {teams_link} resolves to the Microsoft Graph Teams meeting
        # join URL that action_schedule_interview captured on the Application
        # (interview_teams_join_url). Falls back to a placeholder when M365
        # Graph hasn't generated a meeting yet (e.g. M365_GRAPH_ENABLED=0 or
        # admin consent for Calendars/OnlineMeetings not granted).
        _teams_url = (getattr(latest_app, "interview_teams_join_url", "") or "") if latest_app else ""
        placeholders = {
            "associate_name": cand.name or "Associate",
            "client_name": (eng.client if eng else "") or "",
            "role": (job.title if job else "") or "",
            "date": scheduled_dt.strftime("%d %B %Y") if scheduled_dt else "",
            "time": scheduled_dt.strftime("%H:%M") if scheduled_dt else "",
            "client_contact_name": (getattr(eng, "client_contact_name", "") or "") if eng else "",
            "client_role": (getattr(eng, "client_contact_role", "") or "") if eng else "",
            "company_name": (eng.client if eng else "") or "",
            "teams_link": _teams_url or "(link to follow)",
        }
        for key, val in placeholders.items():
            subject = subject.replace("{" + key + "}", val)
            body = body.replace("{" + key + "}", val)

    return jsonify({
        "subject": subject,
        "body": body,
        "to_email": cand.email or "",
        "teams_link": _teams_url or "",
    })


@app.route("/candidate/<int:cand_id>/send-interview-email", methods=["POST"])
@login_required
def send_interview_email(cand_id: int):
    """Send interview invitation email after staff review.

    Req 8 fixes:
    - Always attach an .ics calendar invite so the email lands as a
      proper meeting in Outlook / Google Calendar instead of a plain
      message that says "click this link".
    - Pass through every file in request.files.getlist("attachments")
      so multiple uploads (signed contract + briefing pack) all go,
      not just the first.
    - Optional Location field on the modal (defaults to a sensible
      placeholder) so the ICS LOCATION value can be Teams URL or in-
      person address.
    """
    to_email = (request.form.get("to_email") or "").strip()
    email_subject = (request.form.get("email_subject") or "").strip()
    email_body = (request.form.get("email_body") or "").strip()
    location = (request.form.get("location") or "Microsoft Teams (link to follow)").strip()
    if to_email and email_body:
        try:
            html_body = "<br>".join(email_body.split("\n"))
            attachments = []
            for f in request.files.getlist("attachments"):
                if f and f.filename:
                    attachments.append((
                        f.filename, f.read(),
                        f.content_type or "application/octet-stream",
                    ))

            # Build an ICS calendar invite from the candidate's scheduled
            # interview time so the email lands as a real meeting invite.
            with Session(engine) as s:
                cand = s.get(Candidate, cand_id)
                latest_app = s.scalar(
                    select(Application).where(Application.candidate_id == cand_id)
                    .order_by(Application.created_at.desc())
                )
                job_title = ""
                cand_name = (cand.name if cand else "") or "Associate"
                start_dt = latest_app.interview_scheduled_at if latest_app else None
                saved_teams_url = (getattr(latest_app, "interview_teams_join_url", "") or "").strip() if latest_app else ""
                if latest_app and latest_app.job_id:
                    job = s.get(Job, latest_app.job_id)
                    if job:
                        job_title = job.title or ""

            if start_dt:
                end_dt = start_dt + datetime.timedelta(hours=1)
                # If staff didn't paste a custom location, fall back to the
                # saved Graph Teams URL (so Outlook gets a real join link
                # rather than the "(link to follow)" placeholder).
                placeholder_locations = {
                    "",
                    "microsoft teams (link to follow)",
                    "microsoft teams / zoom (link to follow)",
                }
                effective_location = location
                if location.strip().lower() in placeholder_locations and saved_teams_url:
                    effective_location = saved_teams_url
                ics_bytes = ics_invite(
                    summary=f"Interview — {job_title or 'Optimus'}",
                    description=f"Interview for {job_title or 'this role'} with {cand_name}",
                    start_dt=start_dt,
                    end_dt=end_dt,
                    location=effective_location,
                    organizer_email=SMTP_FROM,
                    attendee_email=to_email,
                    teams_url=saved_teams_url or "",
                )
                # Prepend so it's the first MIME attachment — most clients
                # surface the meeting invite UI based on the first ICS.
                attachments.insert(0, ("interview.ics", ics_bytes, "text/calendar"))

            send_email(to_email, email_subject, html_body,
                       attachments=attachments if attachments else None)
            flash(f"Interview invitation sent to {to_email}.", "success")
        except Exception as exc:
            flash(f"Email failed: {exc}", "warning")
    else:
        flash("No email sent — missing email address or body.", "warning")
    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/candidate/<int:cand_id>/test-mark-vetting-complete", methods=["POST"])
@login_required
def test_mark_vetting_complete(cand_id: int):
    """TEST ONLY — marks all vetting checks as Complete for this candidate.
    Remove before production use."""
    with Session(engine) as s:
        checks = s.scalars(
            select(VettingCheck).where(VettingCheck.candidate_id == cand_id)
        ).all()
        for vc in checks:
            if vc.status not in ("Complete", "COMPLETE"):
                vc.status = "Complete"
                vc.notes = (vc.notes or "") + " [Marked complete — test]"
                vc.completed_at = datetime.datetime.utcnow()
        s.commit()
    flash(f"All {len(checks)} vetting checks marked as Complete (test).", "success")
    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/candidate/<int:cand_id>/paystream-capture", methods=["GET", "POST"])
@login_required
def paystream_capture(cand_id: int):
    """Capture sheet for the Paystream Assignment Schedule. Opens when
    staff clicks Send Paystream Contract — pre-fills everything OS1
    already knows, leaves blank what needs human input (end date, hours
    per week, supervisor, etc.), and on submit persists the values onto
    the Application row + sends the umbrella the signing link with full
    context. When a Signable template fingerprint + field name map is
    configured, switches to pre-filled envelope creation automatically."""
    # Honour the role dropdown on the Contract tile: if the user
    # selected a specific job there, find the matching Application
    # instead of silently defaulting to the candidate's most recent one.
    selected_job_id = request.args.get("job_id", type=int)

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)

        latest_app = None
        if selected_job_id:
            latest_app = s.scalar(
                select(Application)
                .where(Application.candidate_id == cand_id)
                .where(Application.job_id == selected_job_id)
                .order_by(Application.created_at.desc())
            )
        if latest_app is None:
            # No job_id passed (or no application for that job) — fall
            # back to the most recent application.
            latest_app = s.scalar(
                select(Application).where(Application.candidate_id == cand_id)
                .order_by(Application.created_at.desc())
            )
        if not latest_app:
            flash("Candidate has no application to contract against.", "warning")
            return
        job = s.get(Job, latest_app.job_id) if latest_app.job_id else None
        engagement = s.get(Engagement, job.engagement_id) if job and job.engagement_id else None

        # Req 44 — block entry to the assignment-schedule capture sheet when
        # the candidate has other open applications. They must be withdrawn
        # first so contract status in the associate portal stays per-role.
        # Skipped after the cascade-withdraw round-trip (?cascaded=1).
        if request.method == "GET" and not request.args.get("cascaded"):
            OPEN_STATUSES_EXCLUDED = ("Rejected", "Withdrawn", "Closed", "Hired", "Contract Signed", "Contract Issued", "Contract Sent", "Placed")
            other_open_rows = s.execute(
                select(Application, Job, Engagement)
                .join(Job, Job.id == Application.job_id)
                .join(Engagement, Engagement.id == Job.engagement_id, isouter=True)
                .where(Application.candidate_id == cand_id)
                .where(Application.id != latest_app.id)
                .where(Application.status.notin_(OPEN_STATUSES_EXCLUDED))
            ).all()
            if other_open_rows:
                other_apps = [
                    {
                        "id": row[0].id,
                        "status": row[0].status or "",
                        "job_title": row[1].title if row[1] else "",
                        "engagement_name": row[2].name if row[2] else "",
                        "client": row[2].client if row[2] else "",
                    }
                    for row in other_open_rows
                ]
                log_audit_event(
                    "update", "contract",
                    f"ISSUE_CONTRACT_BLOCKED — {len(other_apps)} other open application(s)",
                    "candidate", cand_id,
                    {"other_app_ids": [a["id"] for a in other_apps], "via": "paystream_capture"},
                )
                next_url = url_for("paystream_capture", cand_id=cand_id, job_id=latest_app.job_id, cascaded=1)
                return render_template(
                    "issue_contract_confirm.html",
                    cand=cand,
                    eng=engagement or type("_E", (), {"id": 0, "name": "", "client": ""})(),
                    appn=latest_app,
                    other_apps=other_apps,
                    form_values={},
                    action_url=url_for("issue_contract_precheck_withdraw", cand_id=cand_id),
                    next_url=next_url,
                )

        # Umbrella details (raw SQL — tolerant of partial ORM init)
        cd_row = s.execute(text(
            "SELECT contracting_type, umbrella_company_name, contact_email "
            "FROM company_details WHERE candidate_id = :cid"
        ).bindparams(cid=cand_id)).first()
        umbrella_name = (getattr(cd_row, "umbrella_company_name", "") or "") if cd_row else ""
        umbrella_email = (getattr(cd_row, "contact_email", "") or "") if cd_row else ""

        if request.method == "POST":
            # Persist the captured values onto the Application, then send.
            def _parse_date(v):
                if not v: return None
                try:
                    return datetime.datetime.strptime(v, "%Y-%m-%d").date()
                except Exception:
                    return None

            # Auto-populated fields (overrides — only persisted when
            # the staff amend the value; empty strings are stored as ""
            # so the render layer can fall back to the sourced value).
            latest_app.assignment_worker_name = (request.form.get("worker_name") or "").strip()
            latest_app.assignment_hirer_name = (request.form.get("hirer_name") or "").strip()
            latest_app.assignment_role_title = (request.form.get("role_title") or "").strip()
            latest_app.assignment_start_date = _parse_date(request.form.get("start_date"))
            latest_app.assignment_fee = (request.form.get("fee_display") or "").strip()
            # Staff-input fields
            latest_app.assignment_nature_of_work = (request.form.get("nature_of_work") or "").strip()
            latest_app.assignment_end_date = _parse_date(request.form.get("end_date"))
            latest_app.assignment_hours_of_work = (request.form.get("hours_of_work") or "").strip()
            latest_app.assignment_work_location = (request.form.get("work_location") or "").strip()
            latest_app.assignment_expenses_payable = (request.form.get("expenses_payable") or "").strip()
            latest_app.assignment_expenses_detail = (request.form.get("expenses_detail") or "").strip()
            latest_app.assignment_health_safety_risks = (request.form.get("health_safety_risks") or "").strip()
            latest_app.assignment_health_safety_detail = (request.form.get("health_safety_detail") or "").strip()
            latest_app.assignment_vulnerable_person = (request.form.get("vulnerable_person") or "").strip()
            latest_app.assignment_notice_agency = (request.form.get("notice_agency") or "").strip()
            latest_app.assignment_notice_paystream = (request.form.get("notice_paystream") or "").strip()
            latest_app.assignment_invoice_frequency = (request.form.get("invoice_frequency") or "").strip()
            latest_app.assignment_captured_at = datetime.datetime.utcnow()

            # Preview branch — the "Preview attachment" button in the
            # Send Contract modal posts here with ?preview=1. Persist the
            # field edits (so the preview reflects them and the next real
            # submit doesn't lose them), then short-circuit to the DOCX
            # download in preview mode. NO status change, NO email send,
            # NO audit log, NO ESigRequest creation.
            if (request.args.get("preview") or "") == "1":
                s.commit()
                return redirect(url_for(
                    "download_filled_assignment",
                    cand_id=cand_id, ext="docx", preview=1,
                ))

            # Move the candidate forward — saving the assignment
            # capture sheet (and downloading the filled DOCX) is the
            # explicit Issue Contract action, so the application status
            # transitions to "Contract Issued" (renders in the
            # Contract Sent column on the kanban) and the candidate is
            # marked as in vetting / awaiting signature on the profile.
            old_app_status = latest_app.status
            latest_app.status = "Contract Issued"

            # Track the contract via ESigRequest so retract / signed /
            # ended states all flow through the same record. Mirrors
            # action_contract_issue's behaviour.
            esig = _get_or_create_active_esig(
                s,
                candidate_id=cand_id,
                application_id=latest_app.id,
                engagement_id=engagement.id if engagement else None,
                provider="signable",
                status="pending",
                end_date=(
                    datetime.datetime.combine(latest_app.assignment_end_date, datetime.time())
                    if latest_app.assignment_end_date else None
                ),
            )
            esig.sent_at = datetime.datetime.utcnow()

            # Flip the umbrella_assignment_sent flag so the Contract
            # card on the candidate profile shows the "Awaiting
            # Signature" panel, prompting the staff to upload the
            # signed PDF when it comes back.
            if hasattr(cand, "umbrella_assignment_sent"):
                cand.umbrella_assignment_sent = True
            if hasattr(cand, "umbrella_assignment_sent_at"):
                cand.umbrella_assignment_sent_at = datetime.datetime.utcnow()

            cand.status = "In Vetting"
            cand.last_activity_at = datetime.datetime.utcnow()

            user_email = getattr(current_user, "email", "staff") or "staff"
            s.add(CandidateNote(
                candidate_id=cand_id,
                user_email=user_email,
                note_type="activity",
                content=(
                    f"Assignment Schedule issued: {old_app_status} → Contract Issued. "
                    f"end_date={latest_app.assignment_end_date}, "
                    f"hours={latest_app.assignment_hours_of_work!r}, "
                    f"notice_agency={latest_app.assignment_notice_agency!r}, "
                    f"notice_paystream={latest_app.assignment_notice_paystream!r}, "
                    f"invoice_freq={latest_app.assignment_invoice_frequency!r}"
                ),
                created_at=datetime.datetime.utcnow(),
            ))
            s.commit()

            try:
                log_audit_event(
                    "create", "contract",
                    f"Contract issued via assignment schedule capture for {cand.name}",
                    "candidate", cand_id,
                    {
                        "application_id": latest_app.id,
                        "engagement_id": engagement.id if engagement else None,
                        "esig_id": esig.id,
                        "old_app_status": old_app_status,
                        "new_app_status": "Contract Issued",
                    },
                )
            except Exception:
                current_app.logger.exception("paystream_capture audit log failed")

            # Stash the recruiter-editable email To/Subject from the
            # preview modal so download_filled_assignment can pick them
            # up after the redirect. Empty values fall back to the
            # candidate's email + the default subject.
            _email_to_override = (request.form.get("email_to") or "").strip()
            _email_subject_override = (request.form.get("email_subject") or "").strip()
            if _email_to_override or _email_subject_override:
                session[f"contract_email_overrides:{cand_id}"] = {
                    "to": _email_to_override,
                    "subject": _email_subject_override,
                }

            # Check if a DOCX assignment template exists for this
            # umbrella — if so, redirect to the candidate profile with
            # a flag that triggers a hidden-iframe download. Keeps the
            # user on the profile page after the file is delivered
            # (rather than parking them on the raw download URL).
            tpl_exists = s.scalar(
                select(AssignmentTemplate.id)
                .where(AssignmentTemplate.umbrella_company == umbrella_name)
            )
            if tpl_exists:
                flash("Contract issued. Your filled template is downloading.", "success")
                return redirect(url_for(
                    "candidate_profile",
                    cand_id=cand_id,
                    download_assignment=1,
                ))
            else:
                flash("Contract issued. No template found for this umbrella — upload one in Admin → Assignment Templates.", "warning")
                return redirect(url_for("candidate_profile", cand_id=cand_id))

        # GET — Conduct Regs status (already captured on candidate)
        if getattr(cand, "conduct_regs_opted_in", None) is True:
            conduct_regs = "Opt In"
        elif getattr(cand, "conduct_regs_opted_in", None) is False:
            conduct_regs = "Opt Out"
        else:
            conduct_regs = ""

        # JD-locked fallbacks: when the offer or assignment fields are
        # blank, fall back to the parent Engagement and the
        # EngagementPlan row that matches the Job's role_type. Mirrors
        # the source-of-truth chain on the Offer of Engagement form
        # (Req 13) so the assignment schedule never renders blank dates
        # / day rate when the engagement actually has them.
        jd_day_rate = None
        if engagement and job and job.role_type:
            _plan = s.scalar(
                select(EngagementPlan)
                .where(EngagementPlan.engagement_id == engagement.id)
                .where(EngagementPlan.role_type == job.role_type)
                .order_by(EngagementPlan.version_int.desc())
            )
            if _plan and _plan.pay_rate:
                jd_day_rate = float(_plan.pay_rate)
        jd_start_date = engagement.start_date.date() if engagement and engagement.start_date else None
        jd_end_date   = engagement.end_date.date()   if engagement and engagement.end_date   else None

        # Day rate label: "£XXX / day" or "£XXX / hr"
        if latest_app.offer_day_rate:
            rate_unit = (latest_app.offer_rate_type or "day").lower()
            sourced_fee = f"£{latest_app.offer_day_rate:.2f} / {rate_unit}"
        elif jd_day_rate is not None:
            sourced_fee = f"£{jd_day_rate:.2f} / day"
        else:
            sourced_fee = ""

        # For auto-populated fields, prefer the staff-amended override
        # on the Application row when one has been saved.
        def _or(override, source):
            return override if (override or "").strip() else source

        # Contracting label for Ltd Co / no-umbrella display
        contracting_type = (getattr(cd_row, "contracting_type", "") or "") if cd_row else ""
        if contracting_type == "limited":
            contracting_label = "Limited Company"
        elif contracting_type == "umbrella" and not umbrella_name:
            contracting_label = "Umbrella (not yet selected)"
        else:
            contracting_label = contracting_type.title() if contracting_type else "Not set"

        # Check if a DOCX template exists for this umbrella
        matching_template = None
        if umbrella_name:
            matching_template = s.scalar(
                select(AssignmentTemplate)
                .where(AssignmentTemplate.umbrella_company == umbrella_name)
                .order_by(AssignmentTemplate.uploaded_at.desc())
            )

        return render_template(
            "paystream_capture.html",
            cand=cand,
            appn=latest_app,
            job=job,
            engagement=engagement,
            umbrella_name=umbrella_name,
            umbrella_email=umbrella_email,
            contracting_label=contracting_label,
            matching_template=matching_template,
            captured={
                # --- Auto-populated (editable — override persists) ---
                "worker_name": _or(latest_app.assignment_worker_name, cand.name or ""),
                "hirer_name": _or(latest_app.assignment_hirer_name, engagement.name if engagement else ""),
                # Start date: assignment override → offer → engagement.
                "start_date": (
                    latest_app.assignment_start_date.isoformat()
                    if latest_app.assignment_start_date
                    else (
                        latest_app.offer_start_date.isoformat()
                        if latest_app.offer_start_date
                        else (jd_start_date.isoformat() if jd_start_date else "")
                    )
                ),
                "role_title": _or(
                    latest_app.assignment_role_title,
                    latest_app.offer_role_title or (job.title if job else ""),
                ),
                "fee_display": _or(latest_app.assignment_fee, sourced_fee),
                "conduct_regs": conduct_regs,
                # --- Needs staff input (yellow) ---
                "nature_of_work": latest_app.assignment_nature_of_work or "",
                # End date: assignment override → offer → engagement.
                "end_date": (
                    latest_app.assignment_end_date.isoformat()
                    if latest_app.assignment_end_date
                    else (
                        latest_app.offer_end_date.isoformat()
                        if getattr(latest_app, "offer_end_date", None)
                        else (jd_end_date.isoformat() if jd_end_date else "")
                    )
                ),
                "hours_of_work": latest_app.assignment_hours_of_work or "7.5 hours per day, 37.5 hours per week. UK business hours (9am-5pm)",
                "work_location": latest_app.assignment_work_location or (latest_app.offer_location or (job.location if job else "")),
                "expenses_payable": latest_app.assignment_expenses_payable or "",
                "expenses_detail": latest_app.assignment_expenses_detail or "",
                "health_safety_risks": latest_app.assignment_health_safety_risks or "",
                "health_safety_detail": latest_app.assignment_health_safety_detail or "",
                "vulnerable_person": latest_app.assignment_vulnerable_person or "",
                "notice_agency": latest_app.assignment_notice_agency or "",
                "notice_paystream": latest_app.assignment_notice_paystream or "",
                "invoice_frequency": latest_app.assignment_invoice_frequency or "",
            },
        )


# ---------------------------------------------------------------------------
# Offer of Engagement — Capture Sheet
# ---------------------------------------------------------------------------
@app.route("/candidate/<int:cand_id>/offer-capture", methods=["GET", "POST"])
@login_required
def offer_capture(cand_id: int):
    """Capture sheet for the Offer of Engagement. Pre-fills fields from
    the candidate's latest application / job / engagement. On submit,
    persists values onto the Application row, creates an ESigRequest with
    status='offered', sets the application status to 'Offered', and if an
    OfferTemplate exists, fills and downloads the DOCX.

    Req 13 — day_rate, start_date, end_date and engagement_type are
    locked to the parent Engagement / EngagementPlan / Job for non-admin
    users. Admins ('admin' or 'super_admin' role) can override these
    fields; any deviation from the JD value writes an
    OFFER_FIELDS_OVERRIDDEN audit entry.
    """
    user_role = (getattr(current_user, "role", "") or "").lower()
    is_admin = user_role in ("admin", "super_admin")

    # Honour the role dropdown on the Contract tile: when the user
    # selected a specific job there, the offer must be for THAT role —
    # even if the candidate hasn't formally applied for it yet (the
    # dropdown shows every open role on the engagement). Previously we
    # only narrowed `latest_app` by job_id and fell back to the most
    # recent application when no match was found, which produced the
    # "Collections Agent" mix-up. Now the selected Job is the source
    # of truth for display, and on POST we auto-create an Application
    # for that role so the offer details have a row to persist on.
    selected_job_id = request.args.get("job_id", type=int)

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)

        target_job = s.get(Job, selected_job_id) if selected_job_id else None

        # Find the Application matching the selected job (or most recent
        # if no job_id supplied). On POST, create one when no match
        # exists so the recruiter's offer for a not-yet-applied role
        # gets persisted properly.
        latest_app = None
        if target_job:
            latest_app = s.scalar(
                select(Application)
                .where(Application.candidate_id == cand_id)
                .where(Application.job_id == target_job.id)
                .order_by(Application.created_at.desc())
            )
            if latest_app is None and request.method == "POST":
                latest_app = Application(
                    candidate_id=cand_id,
                    job_id=target_job.id,
                    status="Pipeline",  # POST handler below transitions to "Offered"
                    created_at=datetime.datetime.utcnow(),
                )
                s.add(latest_app)
                s.flush()
        else:
            latest_app = s.scalar(
                select(Application).where(Application.candidate_id == cand_id)
                .order_by(Application.created_at.desc())
            )

        # Source of truth for display: the selected Job (if any) wins
        # over the latest Application's job, so the form renders the
        # role the recruiter actually picked.
        if target_job:
            job = target_job
        elif latest_app and latest_app.job_id:
            job = s.get(Job, latest_app.job_id)
        else:
            job = None
        engagement = s.get(Engagement, job.engagement_id) if job and job.engagement_id else None

        # If we have neither a target job nor a latest_app, there's
        # nothing to offer against — fall back to the historical
        # "no application" message.
        if not target_job and not latest_app:
            flash("Candidate has no application to make an offer against.", "warning")
            return redirect(url_for("candidate_profile", cand_id=cand_id))

        # When we're displaying for a different role than latest_app
        # (selected from the dropdown but no matching Application), we
        # don't want to carry the old offer's overrides forward — the
        # captured-fields dict should source purely from the selected
        # job / engagement. `latest_app` may still be None here on GET.
        _carry_offer_overrides = (
            latest_app is not None
            and (target_job is None or latest_app.job_id == target_job.id)
        )

        # Req 13 — JD-locked source values. day_rate comes from the
        # EngagementPlan row matching the Job.role_type; dates come from
        # the parent Engagement; engagement_type comes from the Job row.
        jd_day_rate = None
        if engagement and job and job.role_type:
            plan = s.scalar(
                select(EngagementPlan)
                .where(EngagementPlan.engagement_id == engagement.id)
                .where(EngagementPlan.role_type == job.role_type)
                .order_by(EngagementPlan.version_int.desc())
            )
            if plan and plan.pay_rate:
                jd_day_rate = float(plan.pay_rate)
        jd_start_date = engagement.start_date.date() if engagement and engagement.start_date else None
        jd_end_date = engagement.end_date.date() if engagement and engagement.end_date else None
        jd_engagement_type = (job.engagement_type if job and getattr(job, "engagement_type", None) else "Contract")

        # Check for an uploaded offer template
        offer_tpl = s.scalar(
            select(OfferTemplate).order_by(OfferTemplate.uploaded_at.desc())
        )

        if request.method == "POST":
            def _parse_date(v):
                if not v:
                    return None
                try:
                    return datetime.datetime.strptime(v, "%Y-%m-%d").date()
                except Exception:
                    return None

            latest_app.offer_role_title = (request.form.get("job_title") or "").strip()
            latest_app.offer_location = (request.form.get("location") or "").strip()

            # Req 13 — read submitted values, but fall back to JD values
            # for the four locked fields when the user is NOT an admin.
            submitted_start = _parse_date(request.form.get("start_date"))
            submitted_end = _parse_date(request.form.get("end_date"))
            submitted_engagement_type = (request.form.get("engagement_type") or "").strip()
            day_rate_raw = (request.form.get("day_rate") or "").strip().replace(",", "")
            try:
                submitted_day_rate = float(day_rate_raw) if day_rate_raw else None
            except ValueError:
                submitted_day_rate = None

            if is_admin:
                final_start = submitted_start or jd_start_date
                final_end = submitted_end or jd_end_date
                final_engagement_type = submitted_engagement_type or jd_engagement_type
                final_day_rate = submitted_day_rate if submitted_day_rate is not None else jd_day_rate
                # Audit any admin override away from the JD value.
                overrides = []
                if jd_start_date and submitted_start and submitted_start != jd_start_date:
                    overrides.append(f"start_date {jd_start_date}→{submitted_start}")
                if jd_end_date and submitted_end and submitted_end != jd_end_date:
                    overrides.append(f"end_date {jd_end_date}→{submitted_end}")
                if jd_engagement_type and submitted_engagement_type and submitted_engagement_type != jd_engagement_type:
                    overrides.append(f"engagement_type {jd_engagement_type}→{submitted_engagement_type}")
                if jd_day_rate is not None and submitted_day_rate is not None and submitted_day_rate != jd_day_rate:
                    overrides.append(f"day_rate {jd_day_rate}→{submitted_day_rate}")
                if overrides:
                    try:
                        log_audit_event(
                            "update", "offer",
                            f"OFFER_FIELDS_OVERRIDDEN by admin: {'; '.join(overrides)}",
                            "candidate", cand_id,
                            {"overrides": overrides, "application_id": latest_app.id},
                        )
                    except Exception:
                        current_app.logger.exception("offer override audit failed")
            else:
                # Locked: ignore tampered submissions, always re-derive.
                final_start = jd_start_date
                final_end = jd_end_date
                final_engagement_type = jd_engagement_type
                final_day_rate = jd_day_rate

            latest_app.offer_start_date = final_start
            latest_app.offer_end_date = final_end
            latest_app.offer_engagement_type = final_engagement_type
            latest_app.offer_day_rate = final_day_rate
            # Expected duration is auto-derived from start→end so the
            # docx merge gets a sensible string. Falls back to whatever
            # the form supplied for backwards compatibility.
            if final_start and final_end:
                _days = max(0, (final_end - final_start).days)
                latest_app.offer_expected_duration = f"{_days} days ({final_start.strftime('%d %b %Y')} – {final_end.strftime('%d %b %Y')})"
            else:
                latest_app.offer_expected_duration = (request.form.get("expected_duration") or "").strip()

            latest_app.offer_made_at = datetime.datetime.utcnow()
            latest_app.status = "Offered"

            # Activity note
            user_email = getattr(current_user, "email", "staff") or "staff"
            project_name = (request.form.get("project_name") or "").strip()
            s.add(CandidateNote(
                candidate_id=cand_id,
                user_email=user_email,
                note_type="activity",
                content=(
                    f"Offer of Engagement captured: "
                    f"project={project_name!r}, "
                    f"role={latest_app.offer_role_title!r}, "
                    f"rate={latest_app.offer_day_rate}, "
                    f"start={latest_app.offer_start_date}, "
                    f"type={latest_app.offer_engagement_type!r}, "
                    f"duration={latest_app.offer_expected_duration!r}"
                ),
                created_at=datetime.datetime.utcnow(),
            ))
            s.commit()

            # If an offer template exists, fill and download the DOCX
            if offer_tpl and offer_tpl.file_content:
                try:
                    from docx import Document as DocxDocument
                    import io, re

                    _cand_name = cand.name or ""
                    _first_name = _cand_name.split()[0] if _cand_name.strip() else ""
                    vals = {
                        "project_name": project_name,
                        "candidate_name": _cand_name,
                        "first_name": _first_name,
                        "job_title": latest_app.offer_role_title or "",
                        "location": latest_app.offer_location or "",
                        "day_rate": f"£{latest_app.offer_day_rate:,.2f}" if latest_app.offer_day_rate else "",
                        "engagement_type": latest_app.offer_engagement_type or "",
                        "start_date": latest_app.offer_start_date.strftime("%d %b %Y") if latest_app.offer_start_date else "",
                        "expected_duration": latest_app.offer_expected_duration or "",
                    }

                    LABEL_TO_FIELD = {
                        "project name": "project_name",
                        "candidate name": "candidate_name",
                        "first name": "first_name",
                        "job title": "job_title",
                        "location": "location",
                        "day rate": "day_rate",
                        "engagement type": "engagement_type",
                        "start date": "start_date",
                        "expected duration": "expected_duration",
                    }

                    def _norm(t):
                        return re.sub(r"\s+", " ", (t or "")).strip().lower().rstrip("?:.")

                    def _set_cell_text(cell, value):
                        from docx.shared import Pt
                        ref_font = None
                        for para in cell.paragraphs:
                            for run in para.runs:
                                if run.font:
                                    ref_font = run.font
                                    break
                            if ref_font:
                                break
                        for i, para in enumerate(cell.paragraphs):
                            if i == 0:
                                if para.runs:
                                    para.runs[0].text = value or ""
                                    for r in para.runs[1:]:
                                        r.text = ""
                                else:
                                    run = para.add_run(value or "")
                                    if ref_font:
                                        if ref_font.name:
                                            run.font.name = ref_font.name
                                        if ref_font.size:
                                            run.font.size = ref_font.size
                                        run.font.bold = ref_font.bold
                                        run.font.italic = ref_font.italic
                            else:
                                for r in para.runs:
                                    r.text = ""

                    tpl_stream = io.BytesIO(offer_tpl.file_content)
                    doc = DocxDocument(tpl_stream)

                    filled_keys = set()
                    for table in doc.tables:
                        for row in table.rows:
                            cells = row.cells
                            if len(cells) < 2:
                                continue
                            label = _norm(cells[0].text)
                            field_key = LABEL_TO_FIELD.get(label)
                            if not field_key and label:
                                for lbl, fk in LABEL_TO_FIELD.items():
                                    if lbl in label or label in lbl:
                                        field_key = fk
                                        break
                            if field_key and field_key in vals:
                                _set_cell_text(cells[-1], vals[field_key])
                                filled_keys.add(field_key)

                    # Fallback: {placeholder} token replacement
                    remaining = {k: v for k, v in vals.items() if k not in filled_keys}
                    if remaining:
                        def _replace_in_para(para, placeholder, value):
                            full = para.text
                            if placeholder not in full:
                                return
                            for run in para.runs:
                                if placeholder in run.text:
                                    run.text = run.text.replace(placeholder, value or "")
                                    return
                            if para.runs:
                                para.runs[0].text = full.replace(placeholder, value or "")
                                for r in para.runs[1:]:
                                    r.text = ""

                        for para in doc.paragraphs:
                            for key, value in remaining.items():
                                _replace_in_para(para, "{" + key + "}", value)
                        for table in doc.tables:
                            for row in table.rows:
                                for cell in row.cells:
                                    for para in cell.paragraphs:
                                        for key, value in remaining.items():
                                            _replace_in_para(para, "{" + key + "}", value)

                    # Second pass: [Square Bracket] replacements (e.g. [First Name])
                    _bracket_map = {
                        "[First Name]": vals.get("first_name", ""),
                        "[Candidate Name]": vals.get("candidate_name", ""),
                        "[Project Name]": vals.get("project_name", ""),
                        "[Job Title]": vals.get("job_title", ""),
                        "[Location]": vals.get("location", ""),
                        "[Day Rate]": vals.get("day_rate", ""),
                        "[Engagement Type]": vals.get("engagement_type", ""),
                        "[Start Date]": vals.get("start_date", ""),
                        "[Expected Duration]": vals.get("expected_duration", ""),
                    }
                    for para in doc.paragraphs:
                        for bracket_key, bracket_val in _bracket_map.items():
                            if bracket_key in para.text:
                                _replace_in_para(para, bracket_key, bracket_val)
                    for table in doc.tables:
                        for row in table.rows:
                            for cell in row.cells:
                                for para in cell.paragraphs:
                                    for bracket_key, bracket_val in _bracket_map.items():
                                        if bracket_key in para.text:
                                            _replace_in_para(para, bracket_key, bracket_val)

                    current_app.logger.info(
                        "Offer template filled: %d/%d fields matched (%s)",
                        len(filled_keys), len(vals),
                        ", ".join(sorted(filled_keys)) or "none",
                    )

                    out = io.BytesIO()
                    doc.save(out)
                    docx_bytes = out.getvalue()
                    out.seek(0)
                    safe_name = re.sub(r"[^a-zA-Z0-9_\-]", "_", cand.name or "candidate")
                    download_name = f"Offer_{safe_name}.docx"

                    # Auto-email the candidate the filled offer with the DOCX
                    # attached. Best-effort: a failure flashes a warning but the
                    # download still streams so the recruiter has the artefact.
                    email_status = "skipped"
                    if cand.email:
                        try:
                            html_body = render_template(
                                "offer_engagement_email.html",
                                first_name=_first_name,
                                candidate_name=_cand_name,
                                role_title=vals["job_title"],
                                project_name=vals["project_name"],
                                engagement_type=vals["engagement_type"],
                                location=vals["location"],
                                day_rate=vals["day_rate"],
                                start_date=vals["start_date"],
                                end_date=(
                                    latest_app.offer_end_date.strftime("%d %b %Y")
                                    if latest_app.offer_end_date else ""
                                ),
                                expected_duration=vals["expected_duration"],
                            )
                            sent_ok = send_email(
                                to_email=cand.email,
                                subject="Offer of Engagement",
                                html_body=html_body,
                                attachments=[(
                                    download_name,
                                    docx_bytes,
                                    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                                )],
                            )
                            email_status = "sent" if sent_ok else "failed"
                        except Exception:
                            current_app.logger.exception(
                                "Offer email send failed for cand=%s app=%s",
                                cand_id, latest_app.id,
                            )
                            email_status = "failed"

                    if email_status == "sent":
                        flash(
                            f"Offer saved. Email sent to {cand.email} with the filled template attached, and your copy is downloading.",
                            "success",
                        )
                    elif email_status == "failed":
                        flash(
                            "Offer saved and downloading, but the email to the candidate could not be sent — please follow up manually.",
                            "warning",
                        )
                    elif not cand.email:
                        flash(
                            "Offer saved and downloading. No email on file for the candidate, so nothing was sent.",
                            "warning",
                        )
                    else:
                        flash("Offer details saved. Your filled template is downloading.", "success")

                    # Activity note for the email send so the audit trail captures it
                    try:
                        s.add(CandidateNote(
                            candidate_id=cand_id,
                            user_email=user_email,
                            note_type="activity",
                            content=(
                                f"Offer of Engagement email — {email_status} "
                                f"(to={cand.email or '—'})"
                            ),
                            created_at=datetime.datetime.utcnow(),
                        ))
                        s.commit()
                    except Exception:
                        current_app.logger.exception("Failed to log offer-email activity note")

                    return send_file(
                        out,
                        mimetype="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                        as_attachment=True,
                        download_name=download_name,
                    )
                except Exception:
                    current_app.logger.exception("Failed to fill offer template")
                    flash("Offer details saved but template fill failed — check logs.", "warning")
                    return redirect(url_for("candidate_profile", cand_id=cand_id))
            else:
                flash("Offer details saved. No offer template uploaded — upload one in Configuration.", "warning")
                return redirect(url_for("candidate_profile", cand_id=cand_id))

        # GET — pre-populate fields
        def _or(override, source):
            return override if (override or "").strip() else source

        # Helper that only reads previously-saved offer_* overrides off
        # latest_app when it actually belongs to the role we're now
        # offering (see _carry_offer_overrides above). Otherwise we
        # source from the selected Job / Engagement so the offer page
        # never bleeds the previous role's values through.
        def _carried(attr, default=None):
            if not _carry_offer_overrides or not latest_app:
                return default
            return getattr(latest_app, attr, default)

        # Req 13 — for non-admins the form is locked to JD values,
        # so the prefilled values are JD-derived. Admins see the
        # same defaults but can edit.
        _carried_start = _carried("offer_start_date")
        prefilled_start = (
            _carried_start.isoformat() if _carried_start
            else (jd_start_date.isoformat() if jd_start_date else "")
        )
        _carried_end = _carried("offer_end_date")
        prefilled_end = (
            _carried_end.isoformat() if _carried_end
            else (jd_end_date.isoformat() if jd_end_date else "")
        )
        prefilled_engagement_type = (
            (_carried("offer_engagement_type") or "") or jd_engagement_type
        )
        _carried_day_rate = _carried("offer_day_rate")
        if _carried_day_rate:
            prefilled_day_rate = str(_carried_day_rate)
        elif jd_day_rate is not None:
            prefilled_day_rate = f"{jd_day_rate:.2f}"
        else:
            prefilled_day_rate = ""

        return render_template(
            "offer_capture.html",
            cand=cand,
            appn=latest_app,
            job=job,
            engagement=engagement,
            offer_tpl=offer_tpl,
            is_admin=is_admin,
            captured={
                "project_name": engagement.name if engagement else "",
                "job_title": _or(_carried("offer_role_title") or "", job.title if job else ""),
                "location": _or(_carried("offer_location") or "", job.location if job else ""),
                "day_rate": prefilled_day_rate,
                "engagement_type": prefilled_engagement_type,
                "start_date": prefilled_start,
                "end_date": prefilled_end,
                "expected_duration": _carried("offer_expected_duration") or "",
            },
        )


# ---------------------------------------------------------------------------
# Signable API helpers — used by the Paystream auto-populated envelope flow.
# ---------------------------------------------------------------------------
SIGNABLE_API_BASE = os.getenv("SIGNABLE_API_BASE", "https://api.signable.co.uk/v1").strip().rstrip("/")
SIGNABLE_PAYSTREAM_FINGERPRINT = os.getenv(
    "SIGNABLE_PAYSTREAM_FINGERPRINT", "d06f94de5d7de36db806bc65fd5d7016"
).strip()


def _signable_api_call(method: str, path: str, json_body: dict | None = None) -> dict | None:
    """Call Signable REST API with HTTP Basic auth (API key as username,
    empty password). Returns parsed JSON on success, None on failure —
    caller logs and surfaces the error to the user."""
    api_key = os.getenv("SIGNABLE_API_KEY", "").strip()
    if not api_key:
        current_app.logger.warning("SIGNABLE_API_KEY not configured — cannot call %s %s", method, path)
        return None
    url = f"{SIGNABLE_API_BASE}{path}"
    try:
        import requests
        resp = requests.request(
            method.upper(),
            url,
            auth=(api_key, ""),
            json=json_body if json_body is not None else None,
            timeout=20,
        )
        if resp.status_code >= 400:
            current_app.logger.error(
                "Signable %s %s returned %s: %s",
                method, path, resp.status_code, resp.text[:500],
            )
            return None
        return resp.json() if resp.content else {}
    except Exception as exc:
        current_app.logger.exception("Signable %s %s failed: %s", method, path, exc)
        return None


def _signable_paystream_merge_map() -> dict[str, str]:
    """Return {field_merge_name: field_id} for the Paystream template.
    Empty dict means the template has no merge fields yet, or the API
    call failed — caller falls back to the widget-link flow."""
    data = _signable_api_call(
        "GET", f"/templates/{SIGNABLE_PAYSTREAM_FINGERPRINT}"
    )
    if not data:
        return {}
    merge_map = {}
    for party in (data.get("template_parties") or []):
        for f in (party.get("party_merge_fields") or []):
            name = (f.get("field_merge") or "").strip()
            fid = str(f.get("field_id") or "").strip()
            if name and fid:
                merge_map[name] = fid
    return merge_map


def _build_paystream_field_values(cand, latest_app, job, engagement, conduct_regs: str) -> dict[str, str]:
    """Assemble the 15 Paystream merge-field values from the Application
    + sourced data. Override columns on Application take precedence.
    Keys match the field_merge names the user has tagged on the
    Paystream template in Signable."""
    def _or(override, source):
        return (override or "").strip() or (source or "")

    def _yn_detail(yn: str, detail: str) -> str:
        """Paystream rows like 'expenses' / 'health_safety' collapse to
        a single line: 'Yes — <detail>' or 'No' or '' when unset."""
        yn = (yn or "").strip()
        detail = (detail or "").strip()
        if yn.lower() == "yes":
            return f"Yes — {detail}" if detail else "Yes"
        if yn.lower() == "no":
            return "No"
        return ""

    worker_name = _or(latest_app.assignment_worker_name, cand.name or "")
    hirer_name = _or(latest_app.assignment_hirer_name, engagement.name if engagement else "")
    role_title = _or(
        latest_app.assignment_role_title,
        latest_app.offer_role_title or (job.title if job else ""),
    )
    nature = (latest_app.assignment_nature_of_work or "").strip()
    position = f"{role_title} — {nature}" if (role_title and nature) else (role_title or nature)

    start_date = latest_app.assignment_start_date or latest_app.offer_start_date
    start_date_s = start_date.strftime("%d %b %Y") if start_date else ""
    end_date_s = (
        latest_app.assignment_end_date.strftime("%d %b %Y")
        if latest_app.assignment_end_date else ""
    )

    # Fee — use override if set, else compute from offer_day_rate
    if (latest_app.assignment_fee or "").strip():
        fee = latest_app.assignment_fee
    elif latest_app.offer_day_rate:
        rate_unit = (latest_app.offer_rate_type or "day").lower()
        fee = f"£{latest_app.offer_day_rate:.2f} / {rate_unit}"
    else:
        fee = ""

    return {
        "worker_name": worker_name,
        "position": position,
        "hirer_name": hirer_name,
        "start_date": start_date_s,
        "end_date": end_date_s,
        "hours_of_work": latest_app.assignment_hours_of_work or "",
        "work_location": latest_app.assignment_work_location or (latest_app.offer_location or ""),
        "expenses": _yn_detail(
            latest_app.assignment_expenses_payable,
            latest_app.assignment_expenses_detail,
        ),
        "health_safety": _yn_detail(
            latest_app.assignment_health_safety_risks,
            latest_app.assignment_health_safety_detail,
        ),
        "vulnerable_person": latest_app.assignment_vulnerable_person or "",
        "conduct_regs": conduct_regs,
        "notice_agency": latest_app.assignment_notice_agency or "",
        "notice_paystream": latest_app.assignment_notice_paystream or "",
        "fee": fee,
        "invoice_frequency": latest_app.assignment_invoice_frequency or "",
    }


def _create_paystream_envelope(
    s,
    cand_id: int,
    cand,
    latest_app,
    job,
    engagement,
    umbrella_name: str,
    umbrella_email: str,
    conduct_regs: str,
) -> tuple[bool, str]:
    """Create a pre-populated Paystream envelope via the Signable API.
    Returns (ok, message). On success the message is a brief
    confirmation; on failure it's a user-facing error reason."""
    merge_map = _signable_paystream_merge_map()
    if not merge_map:
        return False, (
            "Signable template has no merge fields defined yet — add text "
            "merge fields to the Paystream template (see OS1 docs) before "
            "using API-based envelope creation."
        )

    values = _build_paystream_field_values(cand, latest_app, job, engagement, conduct_regs)
    document_fields = []
    missing_fields = []
    for merge_name, field_value in values.items():
        fid = merge_map.get(merge_name)
        if not fid:
            missing_fields.append(merge_name)
            continue
        document_fields.append({
            "field_id": fid,
            "field_value": field_value or "",
        })
    if missing_fields:
        current_app.logger.warning(
            "Paystream template missing merge fields: %s (present: %s)",
            missing_fields, list(merge_map.keys()),
        )

    # Resolve party_id and party_name (just the first party on the template)
    template_data = _signable_api_call(
        "GET", f"/templates/{SIGNABLE_PAYSTREAM_FINGERPRINT}"
    )
    if not template_data or not template_data.get("template_parties"):
        return False, "Couldn't resolve Paystream template parties."
    first_party = template_data["template_parties"][0]
    party_id = str(first_party.get("party_id") or "")
    party_name = (first_party.get("party_name") or "Signer 1").strip() or "Signer 1"
    if not party_id:
        return False, "Paystream template has no signer party."

    eng_name = (engagement.name if engagement else "Optimus assignment")
    envelope_title = f"Optimus Assignment Schedule — {cand.name or 'candidate'} ({eng_name})"
    # Signable expects envelope fields at the top level — not wrapped —
    # and uses the envelope_ prefix on the list keys too.
    payload = {
        "envelope_title": envelope_title,
        "envelope_subject": envelope_title,
        "envelope_message": (
            f"Please sign the Paystream Assignment Schedule for "
            f"{cand.name or 'candidate'} — all details have been "
            f"pre-populated by Optimus Solutions."
        ),
        "envelope_showTitle": "1",
        "envelope_language": "en",
        "envelope_documents": [
            {
                "document_title": "Optimus - Paystream Assignment",
                "document_template_fingerprint": SIGNABLE_PAYSTREAM_FINGERPRINT,
                "document_fields": document_fields,
            }
        ],
        "envelope_parties": [
            {
                "party_id": party_id,
                "party_name": party_name,
                "party_email": umbrella_email,
                "contact_email": umbrella_email,
                "contact_name": umbrella_name or "Umbrella Company",
                "party_title": umbrella_name or "Umbrella Company",
            }
        ],
    }

    resp = _signable_api_call("POST", "/envelopes", json_body=payload)
    if not resp:
        return False, "Signable API rejected the envelope creation — see server logs for details."

    env_id = resp.get("envelope_id") or (resp.get("envelope") or {}).get("envelope_id")
    return True, f"Envelope #{env_id} created and sent to {umbrella_email}."


def _send_umbrella_assignment_email(cand_id: int) -> None:
    """Email the umbrella company the Assignment Schedule. When the
    umbrella is Paystream AND the Signable API + merge fields are
    configured, creates a pre-populated envelope via the API. Otherwise
    falls back to emailing the template widget URL directly.

    Flashes user-facing messages (success or warning/error) and
    records the activity note. Does not return anything — caller is
    responsible for the final redirect."""
    umbrella_templates = {
        "paystream": os.getenv(
            "SIGNABLE_PAYSTREAM_WIDGET_URL",
            "https://sign.signable.app/#/widget/dfSRsWJ5DF",
        ),
    }

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)

        # Resolve umbrella name + contact email via raw SQL (tolerant of
        # partial ORM init state).
        row = s.execute(text(
            "SELECT contracting_type, umbrella_company_name, contact_email "
            "FROM company_details WHERE candidate_id = :cid"
        ).bindparams(cid=cand_id)).first()
        if row is None:
            flash("This candidate has no contracting entity details yet.", "warning")
            return
        if (row.contracting_type or "").lower() != "umbrella":
            flash("Candidate's contracting type is not umbrella — no umbrella contract to send.", "warning")
            return
        umbrella_name = (row.umbrella_company_name or "").strip()
        umbrella_email = (row.contact_email or "").strip()
        if not umbrella_name:
            flash("Umbrella company not selected on the Associate Portal.", "warning")
            return
        if not umbrella_email:
            flash("Umbrella contact email is missing — set it on the Umbrella / Company Details tile first.", "warning")
            return

        umbrella_key = None
        for key in umbrella_templates:
            if key in umbrella_name.lower():
                umbrella_key = key
                break
        if umbrella_key is None:
            flash(
                f"No Signable template is configured for the umbrella '{umbrella_name}'. "
                "Only Paystream is wired up today.",
                "warning",
            )
            return

        widget_url = umbrella_templates[umbrella_key]

        # Pull the latest application context — needed both for the
        # email body (widget fallback) and for the API envelope path.
        latest_app = s.scalar(
            select(Application).where(Application.candidate_id == cand_id)
            .order_by(Application.created_at.desc())
        )
        job = s.get(Job, latest_app.job_id) if latest_app and latest_app.job_id else None
        role_label = (getattr(job, "title", "") or "").strip() or "Optimus assignment"
        eng = s.get(Engagement, job.engagement_id) if job and job.engagement_id else None
        eng_name = (getattr(eng, "name", "") or "").strip() or "the engagement"

        # Candidate's Conduct Regs preference — fed into the Paystream
        # envelope as a pre-populated field.
        if getattr(cand, "conduct_regs_opted_in", None) is True:
            conduct_regs_label = "Opt In"
        elif getattr(cand, "conduct_regs_opted_in", None) is False:
            conduct_regs_label = "Opt Out"
        else:
            conduct_regs_label = ""

        # Paystream path — try API-based envelope first (gets all fields
        # pre-populated). If the API key isn't set, the template has no
        # merge fields, or the call fails, fall back to emailing the
        # widget link (old behaviour). Non-Paystream umbrellas always
        # use the widget fallback.
        used_api_envelope = False
        if (
            umbrella_key == "paystream"
            and os.getenv("SIGNABLE_API_KEY")
            and latest_app
        ):
            ok, msg = _create_paystream_envelope(
                s=s, cand_id=cand_id, cand=cand, latest_app=latest_app,
                job=job, engagement=eng,
                umbrella_name=umbrella_name, umbrella_email=umbrella_email,
                conduct_regs=conduct_regs_label,
            )
            if ok:
                used_api_envelope = True
                flash(
                    f"Paystream envelope created and sent to {umbrella_email} "
                    f"— all fields pre-populated.",
                    "success",
                )
            else:
                current_app.logger.warning(
                    "Paystream API envelope failed, falling back to widget: %s", msg
                )
                flash(
                    f"API envelope path unavailable ({msg}) — falling back to "
                    f"widget link. The umbrella will need to fill in fields manually.",
                    "warning",
                )

        if not used_api_envelope:
            start_date_str = ""
            if latest_app and getattr(latest_app, "offer_start_date", None):
                try:
                    start_date_str = latest_app.offer_start_date.strftime("%d %b %Y")
                except Exception:
                    start_date_str = ""

            subject = f"Assignment Schedule for {cand.name or 'candidate'} — signature required"
            html_body = f"""
            <p>Hello,</p>
            <p>Please use the link below to sign the Assignment Schedule for the following Optimus Solutions associate:</p>
            <ul>
              <li><strong>Associate:</strong> {cand.name or ''}</li>
              <li><strong>Role:</strong> {role_label}</li>
              <li><strong>Engagement:</strong> {eng_name}</li>
              {f'<li><strong>Start date:</strong> {start_date_str}</li>' if start_date_str else ''}
            </ul>
            <p>
              <a href="{widget_url}" style="display:inline-block;padding:10px 20px;background:#1e3a8a;color:#fff;border-radius:6px;text-decoration:none;">
                Open Assignment Schedule
              </a>
            </p>
            <p>If the button doesn't render, paste the URL below into your browser:<br>
              <a href="{widget_url}">{widget_url}</a></p>
            <p>Optimus Solutions will be notified automatically once the document is signed.</p>
            <p>Thank you,<br>Optimus Solutions</p>
            """

            try:
                send_email(umbrella_email, subject, html_body)
            except Exception as mail_exc:
                current_app.logger.exception("umbrella contract email failed: %s", mail_exc)
                flash(f"Couldn't send the email: {mail_exc}", "danger")
                return

        # Mark "sent" on the Candidate so the profile tile can track
        # progression (Paystream: signed-state from webhook, others:
        # staff-updated). Only set if not already True to avoid
        # overwriting an earlier timestamp.
        if not getattr(cand, "umbrella_assignment_sent", False):
            cand.umbrella_assignment_sent = True
            cand.umbrella_assignment_sent_at = datetime.datetime.utcnow()

        user_email = getattr(current_user, "email", "staff") or "staff"
        activity_suffix = "pre-populated API envelope" if used_api_envelope else "widget link"
        s.add(CandidateNote(
            candidate_id=cand_id,
            user_email=user_email,
            note_type="activity",
            content=(
                f"Umbrella contract sent to {umbrella_name} ({umbrella_email}) — "
                f"Signable {umbrella_key.title()} template ({activity_suffix})."
            ),
            created_at=datetime.datetime.utcnow(),
        ))
        s.commit()
        # Only flash the generic "link emailed" message for the widget
        # fallback — the API path already flashed its own success message
        # with more detail.
        if not used_api_envelope:
            flash(f"Assignment Schedule link emailed to {umbrella_email}.", "success")


@app.route("/action/umbrella-contract/<int:cand_id>", methods=["POST"])
@login_required
def send_umbrella_contract(cand_id: int):
    """Thin route wrapper that sends the umbrella Assignment Schedule
    and redirects back to the candidate profile."""
    _send_umbrella_assignment_email(cand_id)
    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/action/company-details/email/<int:cand_id>", methods=["POST"])
@login_required
def staff_set_company_email(cand_id: int):
    """Staff-editable contracting entity contact email. Stored on the same
    CompanyDetails row the associate portal writes to (contact_email col).
    Creates the row if the candidate hasn't filled out the portal form yet
    so the email can be captured independently."""
    email_raw = (request.form.get("contact_email") or "").strip()
    email_lower = email_raw.lower()
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)
        try:
            from associate_portal import _portal_model as _pm
            CompanyDetailsCls = _pm("CompanyDetails")
            if CompanyDetailsCls is not None:
                comp = s.query(CompanyDetailsCls).filter_by(candidate_id=cand_id).first()
                if comp is None:
                    comp = CompanyDetailsCls(candidate_id=cand_id)
                    s.add(comp)
                comp.contact_email = email_lower
            else:
                # Partial-init fallback: class not registered on this
                # worker. UPSERT directly against company_details.
                existing = s.execute(
                    text("SELECT id FROM company_details WHERE candidate_id = :cid"),
                    {"cid": cand_id},
                ).first()
                if existing:
                    s.execute(text(
                        "UPDATE company_details SET contact_email = :email, "
                        "updated_at = CURRENT_TIMESTAMP WHERE candidate_id = :cid"
                    ), {"email": email_lower, "cid": cand_id})
                else:
                    s.execute(text(
                        "INSERT INTO company_details (candidate_id, contact_email, "
                        "created_at, updated_at) VALUES "
                        "(:cid, :email, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)"
                    ), {"cid": cand_id, "email": email_lower})
            user_email = getattr(current_user, "email", "staff") or "staff"
            s.add(CandidateNote(
                candidate_id=cand_id,
                user_email=user_email,
                note_type="activity",
                content=f"Contracting contact email set to '{email_raw}'.",
                created_at=datetime.datetime.utcnow(),
            ))
            s.commit()
            flash("Contact email saved.", "success")
        except Exception:
            current_app.logger.exception("staff_set_company_email failed")
            flash("Could not save contact email.", "danger")
    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/admin/reset-signing/<int:cand_id>/<string:form_key>", methods=["POST"])
@login_required
def admin_reset_signing(cand_id: int, form_key: str):
    """Developer/test action — wipe a candidate's Signable signing for a
    given form so the portal re-presents the iframe and can be tested
    end-to-end. Logs what was cleared via CandidateNote for audit."""
    form_key = (form_key or "").lower().strip()
    allowed = {"consent", "declaration", "secondary_job", "employment_ref"}
    if form_key not in allowed:
        flash("Unknown form key.", "danger")
        return redirect(url_for("candidate_profile", cand_id=cand_id))

    cleared = []
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)

        try:
            from associate_portal import _portal_model as _pm

            if form_key == "consent":
                ConsentRecordCls = _pm("ConsentRecord")
                if ConsentRecordCls is not None:
                    rows = s.query(ConsentRecordCls).filter_by(candidate_id=cand_id).all()
                    for r in rows:
                        s.delete(r)
                    cleared.append(f"{len(rows)} ConsentRecord row(s)")

            elif form_key == "declaration":
                DeclarationRecordCls = _pm("DeclarationRecord")
                if DeclarationRecordCls is not None:
                    rows = s.query(DeclarationRecordCls).filter_by(candidate_id=cand_id).all()
                    for r in rows:
                        s.delete(r)
                    cleared.append(f"{len(rows)} DeclarationRecord row(s)")

            elif form_key == "secondary_job":
                if hasattr(cand, "secondary_job_declaration_signed"):
                    cand.secondary_job_declaration_signed = False
                if hasattr(cand, "secondary_job_declaration_signed_at"):
                    cand.secondary_job_declaration_signed_at = None
                if hasattr(cand, "secondary_job_has_secondary"):
                    cand.secondary_job_has_secondary = False
                if hasattr(cand, "secondary_job_title"):
                    cand.secondary_job_title = ""
                if hasattr(cand, "secondary_job_signed_name"):
                    cand.secondary_job_signed_name = ""
                cleared.append("secondary_job_declaration flags + captured fields")

            elif form_key == "employment_ref":
                if hasattr(cand, "employment_ref_declaration_signed"):
                    cand.employment_ref_declaration_signed = False
                if hasattr(cand, "employment_ref_declaration_signed_at"):
                    cand.employment_ref_declaration_signed_at = None
                cleared.append("employment_ref_declaration flags")
        except Exception:
            current_app.logger.exception("reset-signing failed")
            flash("Reset failed — see server logs.", "danger")
            return

        # Audit note (note_type='activity' so it shows in the staff feed)
        user_email = getattr(current_user, "email", "staff") or "staff"
        s.add(CandidateNote(
            candidate_id=cand_id,
            user_email=user_email,
            note_type="activity",
            content=f"[TEST] Reset {form_key} signing — cleared: {', '.join(cleared) if cleared else 'nothing'}.",
            created_at=datetime.datetime.utcnow(),
        ))
        s.commit()

    flash(f"{form_key.replace('_', ' ').title()} signing reset for this candidate.", "success")
    return redirect(url_for("candidate_profile", cand_id=cand_id))


def _apply_widget_signing(s, cand, doc_label: str, signer_name: str,
                          envelope_fp: str, ip_address: str = "",
                          envelope_fields: list = None) -> str:
    """Shared widget-signing upsert, used by both the webhook auto-match path
    and the staff manual-link admin action. Returns a short description of
    what was persisted for audit / breadcrumb purposes.

    envelope_fields: the already-parsed list of Signable field dicts. Passing
    it in makes the Declaration Yes/No mapping work regardless of whether
    the original request was form-encoded or JSON (Replay uses JSON)."""
    if not cand:
        return "no candidate"
    is_emp_ref = doc_label == "Employment Reference Declaration"
    if is_emp_ref and hasattr(cand, "employment_ref_declaration_signed"):
        cand.employment_ref_declaration_signed = True
        cand.employment_ref_declaration_signed_at = datetime.datetime.utcnow()
    if doc_label == "Umbrella Assignment (Paystream)":
        if hasattr(cand, "umbrella_assignment_signed"):
            cand.umbrella_assignment_signed = True
        if hasattr(cand, "umbrella_assignment_signed_at"):
            cand.umbrella_assignment_signed_at = datetime.datetime.utcnow()
        return "Candidate.umbrella_assignment_signed flipped (Paystream auto)"
    if doc_label == "Secondary Job Declaration":
        # Parse incoming fields (same approach as Declaration Form) so we
        # can capture the Yes/No, free-text job title, and signed name.
        _fields_sj = envelope_fields
        if _fields_sj is None:
            try:
                from flask import request as _req
                _raw_sj = (_req.form.get("envelope_fields") or "").strip()
                if not _raw_sj:
                    _body_sj = _req.get_json(silent=True)
                    if isinstance(_body_sj, dict):
                        _raw_sj = (_body_sj.get("envelope_fields") or "").strip()
                if _raw_sj.startswith("["):
                    _fields_sj = json.loads(_raw_sj)
            except Exception:
                _fields_sj = None

        has_secondary = False
        title_value = ""
        signed_name = ""
        if isinstance(_fields_sj, list):
            # Yes/No can arrive as a dropdown ("Yes"/"No") OR as two
            # adjacent checkboxes (one for Yes, one for No; the ticked one
            # has field_value "1", the unticked one is ""). Handle both.
            dropdown_found = False
            for f in _fields_sj:
                if not isinstance(f, dict):
                    continue
                if (f.get("field_type") or "").lower() == "dropdown":
                    has_secondary = (f.get("field_value") or "").strip().lower() == "yes"
                    dropdown_found = True
                    break
            if not dropdown_found:
                # Checkbox pair: assume Yes checkbox precedes No checkbox
                # (as the form text is "☐ Yes, ... ☐ No, ..."). has_secondary
                # is True iff the FIRST checkbox is ticked.
                checkboxes = [
                    (f.get("field_value") or "").strip()
                    for f in _fields_sj
                    if isinstance(f, dict)
                    and (f.get("field_type") or "").lower() == "checkbox"
                ]
                if checkboxes:
                    has_secondary = checkboxes[0] not in ("", "0", "false", "no")

            # Text fields: first non-name → job title, last name-pattern → legal name.
            import re as _re_sj
            _name_re_sj = _re_sj.compile(
                r"^[A-Za-z][A-Za-z\-']*( [A-Za-z][A-Za-z\-']*)+$"
            )
            for f in _fields_sj:
                if not isinstance(f, dict):
                    continue
                if (f.get("field_type") or "").lower() != "text":
                    continue
                v = (f.get("field_value") or "").strip()
                if not v:
                    continue
                if _name_re_sj.match(v):
                    signed_name = v  # last-matching wins since we keep iterating
                elif not title_value:
                    title_value = v

        if hasattr(cand, "secondary_job_declaration_signed"):
            cand.secondary_job_declaration_signed = True
        if hasattr(cand, "secondary_job_declaration_signed_at"):
            cand.secondary_job_declaration_signed_at = datetime.datetime.utcnow()
        if hasattr(cand, "secondary_job_has_secondary"):
            cand.secondary_job_has_secondary = has_secondary
        if hasattr(cand, "secondary_job_title"):
            # Store blank if the answer was No — don't retain stale title
            # from a previous "Yes" signing.
            cand.secondary_job_title = title_value if has_secondary else ""
        if hasattr(cand, "secondary_job_signed_name") and signed_name:
            cand.secondary_job_signed_name = signed_name
        return (
            "Secondary Job flipped: "
            f"has_secondary={'Yes' if has_secondary else 'No'}, "
            f"title={title_value!r}, signed_name={signed_name!r}"
        )

    try:
        from associate_portal import _portal_model as _pm
        if doc_label == "Consent Form":
            Cls = _pm("ConsentRecord")
            if Cls is None:
                return "ConsentRecord class not resolvable"
            rec = s.query(Cls).filter_by(candidate_id=cand.id).first()
            is_new = rec is None
            if rec is None:
                rec = Cls(candidate_id=cand.id)
                s.add(rec)
            rec.consent_given = True
            rec.signed_date = datetime.datetime.utcnow()
            if not (rec.legal_name or "").strip():
                rec.legal_name = signer_name or cand.name or ""
            if hasattr(rec, "signable_envelope_id"):
                rec.signable_envelope_id = envelope_fp
            if hasattr(rec, "ip_address") and not (rec.ip_address or ""):
                rec.ip_address = ip_address or ""
            s.flush()
            return f"ConsentRecord {'inserted' if is_new else 'updated'} (id={rec.id})"
        if doc_label == "Declaration Form":
            # Parse incoming fields once, upfront, so both the ORM path
            # and the raw-SQL fallback can use them.
            _fields_list = envelope_fields
            if _fields_list is None:
                try:
                    from flask import request as _req
                    _raw_fields = (_req.form.get("envelope_fields") or "").strip()
                    if not _raw_fields:
                        _body = _req.get_json(silent=True)
                        if isinstance(_body, dict):
                            _raw_fields = (_body.get("envelope_fields") or "").strip()
                    if _raw_fields.startswith("["):
                        _fields_list = json.loads(_raw_fields)
                except Exception:
                    _fields_list = None
            _dropdowns = []
            _notes_value = ""
            if isinstance(_fields_list, list):
                _dropdowns = [
                    (f.get("field_value") or "").strip().lower()
                    for f in _fields_list
                    if isinstance(f, dict)
                    and (f.get("field_type") or "").lower() == "dropdown"
                ]
                import re as _re
                _name_re = _re.compile(
                    r"^[A-Za-z][A-Za-z\-']*( [A-Za-z][A-Za-z\-']*)+$"
                )
                for f in _fields_list:
                    if not isinstance(f, dict):
                        continue
                    if (f.get("field_type") or "").lower() != "text":
                        continue
                    v = (f.get("field_value") or "").strip()
                    if v and not _name_re.match(v):
                        _notes_value = v
                        break
            _model_order = [
                "work_restrictions", "criminal_convictions", "ccj_debt",
                "bankruptcy", "dismissed", "referencing_issues",
            ]
            _bool_values = [
                (_dropdowns[i].lower() == "yes") if i < len(_dropdowns) else False
                for i in range(len(_model_order))
            ]

            Cls = _pm("DeclarationRecord")
            if Cls is None:
                # ORM path unavailable (partial model init on this worker).
                # Fall back to raw SQL so the signing still persists.
                try:
                    existing = s.execute(
                        text("SELECT id FROM declaration_records WHERE candidate_id = :cid"),
                        {"cid": cand.id},
                    ).first()
                    params = {
                        "cid": cand.id,
                        "notes": _notes_value,
                        "name": signer_name or cand.name or "",
                        "fp": envelope_fp or "",
                        "ip": ip_address or "",
                    }
                    for i, attr in enumerate(_model_order):
                        params[attr] = _bool_values[i]
                    if existing:
                        s.execute(text("""
                            UPDATE declaration_records SET
                              work_restrictions = :work_restrictions,
                              criminal_convictions = :criminal_convictions,
                              ccj_debt = :ccj_debt,
                              bankruptcy = :bankruptcy,
                              dismissed = :dismissed,
                              referencing_issues = :referencing_issues,
                              disclosure_text = :notes,
                              legal_name = CASE WHEN COALESCE(legal_name,'') = '' THEN :name ELSE legal_name END,
                              signed_date = CURRENT_TIMESTAMP,
                              signable_envelope_id = :fp
                            WHERE candidate_id = :cid
                        """), params)
                        return f"DeclarationRecord updated via raw SQL (id={existing.id})"
                    else:
                        s.execute(text("""
                            INSERT INTO declaration_records (
                              candidate_id, work_restrictions, criminal_convictions,
                              ccj_debt, bankruptcy, dismissed, referencing_issues,
                              disclosure_text, legal_name, signed_date,
                              signable_envelope_id, ip_address, created_at
                            ) VALUES (
                              :cid, :work_restrictions, :criminal_convictions,
                              :ccj_debt, :bankruptcy, :dismissed, :referencing_issues,
                              :notes, :name, CURRENT_TIMESTAMP,
                              :fp, :ip, CURRENT_TIMESTAMP
                            )
                        """), params)
                        return "DeclarationRecord inserted via raw SQL"
                except Exception as raw_exc:
                    return f"raw SQL Declaration upsert failed: {raw_exc}"

            rec = s.query(Cls).filter_by(candidate_id=cand.id).first()
            is_new = rec is None
            if rec is None:
                rec = Cls(candidate_id=cand.id)
                s.add(rec)
            if hasattr(rec, "signed_date"):
                rec.signed_date = datetime.datetime.utcnow()
            if hasattr(rec, "legal_name") and not (rec.legal_name or "").strip():
                rec.legal_name = signer_name or cand.name or ""
            if hasattr(rec, "signable_envelope_id"):
                rec.signable_envelope_id = envelope_fp
            # Apply booleans + disclosure_text from the values we parsed above.
            for i, attr in enumerate(_model_order):
                if hasattr(rec, attr):
                    setattr(rec, attr, _bool_values[i])
            if hasattr(rec, "disclosure_text"):
                rec.disclosure_text = _notes_value
            try:
                current_app.logger.info(
                    "Declaration mapping cand=%s: %s",
                    cand.id,
                    ", ".join(
                        f"{attr}={('Yes' if _bool_values[i] else 'No')}"
                        for i, attr in enumerate(_model_order)
                    ),
                )
            except Exception:
                pass
            s.flush()
            return f"DeclarationRecord {'inserted' if is_new else 'updated'} (id={rec.id})"

    except Exception as exc:
        return f"exception: {exc}"
    if is_emp_ref:
        return "Candidate.employment_ref_declaration_signed flipped"
    return f"no-op (unhandled doc_label={doc_label!r})"


@app.route("/admin/webhook-events/<int:event_id>/replay", methods=["POST"])
@login_required
def admin_webhook_replay(event_id: int):
    """Re-submit a stored webhook payload through the current /webhook/esign
    handler. Useful when an early delivery was processed by old handler
    code (e.g. before positional boolean mapping for the Declaration Form)
    — replaying applies the latest logic without needing the candidate to
    re-sign. Stored payload is unwrapped from our diagnostic envelope
    before being POSTed back to our own endpoint."""
    with Session(engine) as s:
        evt = s.get(WebhookEvent, event_id)
        if not evt:
            flash("Webhook event not found.", "danger")
            return redirect(url_for("admin_webhook_events"))
        try:
            raw = json.loads(evt.payload or "{}")
        except Exception:
            raw = {}

    # Unwrap the diagnostic envelope webhook_esign writes on inbound:
    #   {"_meta": {...}, "payload": {<original signable payload>}}
    inner = raw
    if isinstance(raw, dict) and "_meta" in raw and isinstance(raw.get("payload"), dict):
        inner = raw["payload"]
    if not isinstance(inner, dict) or not inner:
        flash("Event payload cannot be replayed (not a JSON object).", "warning")
        return redirect(url_for("admin_webhook_events"))

    target = url_for("webhook_esign", _external=True)
    if target.startswith("http://"):
        target = "https://" + target[len("http://"):]

    try:
        import requests as _rq
        import hmac, hashlib
        body = json.dumps(inner).encode()
        headers = {"Content-Type": "application/json"}
        # Compute the signature the handler expects if the secret is set
        # so the replay passes the same verification a real webhook would.
        if SIGNABLE_WEBHOOK_SECRET:
            sig = hmac.new(
                SIGNABLE_WEBHOOK_SECRET.encode(), body, hashlib.sha256
            ).hexdigest()
            headers["X-Signable-Signature"] = sig
        resp = _rq.post(target, data=body, headers=headers, timeout=15, allow_redirects=False)
        if 200 <= resp.status_code < 300:
            flash(
                f"Replayed event #{event_id} — status {resp.status_code}. "
                "Refresh to see the new matched/unmatched entry.",
                "success",
            )
        else:
            flash(
                f"Replay returned status {resp.status_code}: {(resp.text or '')[:200]}",
                "warning",
            )
    except Exception as exc:
        current_app.logger.exception("replay failed for event %s", event_id)
        flash(f"Replay failed: {exc}", "danger")
    return redirect(url_for("admin_webhook_events"))


@app.route("/admin/webhook-events/<int:event_id>/link-candidate", methods=["POST"])
@login_required
def admin_webhook_link_candidate(event_id: int):
    """Staff manual-resolution for ambiguous/unmatched widget signings.
    Reads the cand_id the staff selected, re-runs the upsert against that
    candidate, logs the resolution on both the audit trail and the
    original WebhookEvent row."""
    try:
        cand_id = int(request.form.get("cand_id") or 0)
    except Exception:
        cand_id = 0
    if cand_id <= 0:
        flash("A valid candidate id is required.", "danger")
        return redirect(url_for("admin_webhook_events"))

    with Session(engine) as s:
        evt = s.get(WebhookEvent, event_id)
        if not evt:
            flash("Webhook event not found.", "danger")
            return redirect(url_for("admin_webhook_events"))
        try:
            raw = json.loads(evt.payload or "{}")
        except Exception:
            raw = {}
        # Unwrap the diagnostic envelope used on inbound payloads.
        inner = raw.get("payload") if isinstance(raw, dict) else {}
        meta_payload = raw if raw.get("doc_label") else (inner if isinstance(inner, dict) else raw)
        doc_label = (meta_payload.get("doc_label") or "").strip() or "Signable Document"
        envelope_fp = (meta_payload.get("envelope_fingerprint") or "").strip()
        signer_name = (meta_payload.get("signer_name") or "").strip()

        cand = s.get(Candidate, cand_id)
        if not cand:
            flash(f"Candidate {cand_id} not found.", "danger")
            return redirect(url_for("admin_webhook_events"))

        outcome = _apply_widget_signing(s, cand, doc_label, signer_name, envelope_fp)
        user_email = getattr(current_user, "email", "staff") or "staff"
        s.add(CandidateNote(
            candidate_id=cand_id,
            user_email=user_email,
            note_type="activity",
            content=(
                f"Manually linked Signable {doc_label} envelope "
                f"{envelope_fp or '(no fingerprint)'} to this candidate. "
                f"Upsert: {outcome}."
            ),
            created_at=datetime.datetime.utcnow(),
        ))
        # Mark the source event as resolved so the admin page shows it visually.
        if evt.event_type and not evt.event_type.endswith("-resolved"):
            evt.event_type = f"{evt.event_type}-resolved"
        s.commit()

    flash(f"Linked webhook event {event_id} to candidate {cand_id}: {outcome}", "success")
    return redirect(url_for("admin_webhook_events"))


@app.route("/admin/webhook-events/test", methods=["POST"])
@login_required
def admin_webhook_events_test():
    """Fire a simulated Signable 'Envelope Signed & Completed' payload at
    our own /webhook/esign endpoint. If the test appears in the events
    list afterwards, the receive pipeline is fine and the real issue is
    that Signable is not delivering."""
    import uuid as _uuid
    import requests as _rq
    fake_fp = f"test-{_uuid.uuid4().hex[:12]}"
    payload = {
        "event": "envelope.completed",
        "envelope_fingerprint": fake_fp,
        "envelope_status": "completed",
        "envelope_title": "Consent Form (test)",
        "envelope_parties": [
            {"party_email": "test-webhook@example.com", "party_name": "Test Signer"}
        ],
    }
    # Railway terminates TLS at the edge and 301s http -> https. requests
    # follows that redirect with a GET, which hits our GET verification
    # path ({"ok": True}) and never reaches the POST handler. Force https
    # and disable redirect-follow so we surface the real response.
    target = url_for("webhook_esign", _external=True)
    if target.startswith("http://"):
        target = "https://" + target[len("http://"):]
    try:
        resp = _rq.post(target, json=payload, timeout=10, allow_redirects=False)
        snippet = (resp.text or "")[:300]
        if resp.status_code in (301, 302, 303, 307, 308):
            flash(
                f"Test POST was redirected to {resp.headers.get('Location', '(no Location)')}"
                f" (status {resp.status_code}). Handler never ran. Tell support.",
                "warning",
            )
        elif 200 <= resp.status_code < 300:
            flash(
                f"Test payload POSTed to {target} — status {resp.status_code}. "
                "Refresh this page, a new entry should appear.",
                "success",
            )
        else:
            flash(
                f"Test POST returned status {resp.status_code}. "
                f"Response body: {snippet}",
                "warning",
            )
    except Exception as exc:
        current_app.logger.exception("test webhook POST failed")
        flash(f"Could not POST test payload: {exc}", "danger")
    return redirect(url_for("admin_webhook_events"))


@app.route("/admin/webhook-events")
@login_required
def admin_webhook_events():
    """Inbound webhook inspection — shows what Signable / Verifile have
    actually POSTed to us. Essential for diagnosing sync gaps without
    chasing Railway logs or provider UIs."""
    source_filter = (request.args.get("source") or "").strip().lower()
    with Session(engine) as s:
        q = select(WebhookEvent).order_by(WebhookEvent.received_at.desc()).limit(100)
        if source_filter in ("esign", "verifile"):
            q = select(WebhookEvent).where(WebhookEvent.source == source_filter).order_by(WebhookEvent.received_at.desc()).limit(100)
        rows = s.scalars(q).all()
        events = []
        for r in rows:
            try:
                raw_dict = json.loads(r.payload or "{}")
            except Exception:
                raw_dict = {}
            try:
                pretty = json.dumps(raw_dict or {}, indent=2)
            except Exception:
                pretty = r.payload or ""

            # Enrich ambiguous/unmatched events so staff can pick a candidate
            # to link against without leaving the page.
            candidates = []
            is_ambiguous = r.event_type == "ambiguous-widget-signing"
            is_unmatched = r.event_type == "unmatched-widget-signing"
            inner = raw_dict.get("payload") if isinstance(raw_dict, dict) else None
            meta = raw_dict if raw_dict.get("doc_label") else (inner if isinstance(inner, dict) else {})
            if is_ambiguous:
                for cid in (meta.get("ambiguous_candidate_ids") or []):
                    try:
                        cobj = s.get(Candidate, int(cid))
                        if cobj:
                            candidates.append({
                                "id": cobj.id,
                                "name": cobj.name,
                                "email": cobj.email,
                            })
                    except Exception:
                        pass

            # A "real" inbound event has our diagnostic envelope containing
            # an original Signable payload. Breadcrumbs we write ourselves
            # (matched-widget-signing / unmatched-widget-signing / etc.)
            # don't have that shape and aren't useful to replay.
            inbound_payload = raw_dict.get("payload") if isinstance(raw_dict, dict) else None
            is_replayable = (
                isinstance(inbound_payload, dict)
                and bool(inbound_payload.get("envelope_fingerprint"))
                and r.event_type not in (
                    "matched-widget-signing",
                    "unmatched-widget-signing",
                    "ambiguous-widget-signing",
                    "unmatched-widget-signing-resolved",
                    "ambiguous-widget-signing-resolved",
                )
            )

            events.append({
                "id": r.id,
                "source": r.source,
                "event_type": r.event_type,
                "received_at": r.received_at,
                "payload": pretty,
                "is_ambiguous": is_ambiguous,
                "is_unmatched": is_unmatched,
                "is_resolvable": (is_ambiguous or is_unmatched) and not (r.event_type or "").endswith("-resolved"),
                "is_replayable": is_replayable,
                "candidates": candidates,
                "signer_name": meta.get("signer_name") or "",
                "doc_label": meta.get("doc_label") or "",
            })
    return render_template(
        "admin_webhook_events.html",
        events=events,
        source_filter=source_filter,
    )

# ========== Timesheet Configuration ==========

@app.route("/admin/timesheet-config/<int:engagement_id>", methods=["GET", "POST"])
@login_required
def admin_timesheet_config(engagement_id):
    """Configure timesheet settings for an engagement."""
    import json as _json
    TimesheetConfig = _get_ts_config_model()
    with Session(engine) as s:
        eng = s.get(Engagement, engagement_id)
        if not eng:
            flash("Engagement not found.", "danger")
            return redirect(url_for("engagements"))

        config = s.query(TimesheetConfig).filter_by(engagement_id=engagement_id).first() if TimesheetConfig else None

        if request.method == "GET":
            time_types = _json.loads(config.time_types) if config and config.time_types else ["Standard Time", "Overtime", "Holiday", "Sickness", "Unplanned Absence"]
            expense_types = _json.loads(config.expense_types) if config and config.expense_types else ["Travel", "Accommodation", "Meals", "Equipment", "Other"]
            expense_limits = _json.loads(config.expense_limits) if config and config.expense_limits else {}
            return render_template("admin_timesheet_config.html",
                engagement=eng,
                config=config,
                time_types=time_types,
                expense_types=expense_types,
                expense_limits=expense_limits,
            )

        # POST - save config
        if not TimesheetConfig:
            flash("TimesheetConfig model not available.", "danger")
            return redirect(url_for("engagement_dashboard", eng_id=engagement_id))

        if not config:
            config = TimesheetConfig(engagement_id=engagement_id)
            s.add(config)

        # Time types from checkboxes
        selected_types = request.form.getlist("time_types")
        config.time_types = _json.dumps(selected_types)

        # Overtime
        config.overtime_enabled = request.form.get("overtime_enabled") == "1"
        config.overtime_multiplier = float(request.form.get("overtime_multiplier", 1.5) or 1.5)
        config.overtime_rate_type = request.form.get("overtime_rate_type", "hourly")

        # Expenses
        config.expense_enabled = request.form.get("expense_enabled") == "1"
        exp_types = request.form.getlist("expense_types")
        config.expense_types = _json.dumps(exp_types)
        # Expense limits
        limits = {}
        for et in exp_types:
            limit_val = request.form.get(f"expense_limit_{et}", "")
            if limit_val:
                try:
                    limits[et] = float(limit_val)
                except ValueError:
                    pass
        config.expense_limits = _json.dumps(limits)

        # Rates
        config.day_rate = float(request.form.get("day_rate", 0) or 0)
        config.overtime_rate = float(request.form.get("overtime_rate", 0) or 0)

        s.commit()
        flash("Timesheet configuration saved.", "success")
        return redirect(url_for("admin_timesheet_config", engagement_id=engagement_id))

# ========== Portal User Management (Public Portal User Management) ==========

@app.route("/admin/portal-users")
@login_required
def admin_portal_users():
    """Admin page for managing public portal users (candidates who signed up via the portal)."""
    search = request.args.get("search", "").strip()
    status_filter = request.args.get("status", "")  # all, verified, unverified
    source_filter = request.args.get("source", "")  # all, portal, manual, import
    page = int(request.args.get("page", 1))
    per_page = 25
    
    with Session(engine) as s:
        query = select(Candidate).order_by(Candidate.created_at.desc())
        
        # Apply search filter
        if search:
            search_term = f"%{search}%"
            query = query.where(
                or_(
                    Candidate.name.ilike(search_term),
                    Candidate.email.ilike(search_term),
                    Candidate.phone.ilike(search_term),
                    Candidate.skills.ilike(search_term)
                )
            )
        
        # Apply status filter
        if status_filter == "verified":
            query = query.where(Candidate.email_verified == True)
        elif status_filter == "unverified":
            query = query.where(or_(Candidate.email_verified == False, Candidate.email_verified == None))
        
        # Apply source filter
        if source_filter and source_filter != "all":
            query = query.where(Candidate.source == source_filter)
        
        # Get total count
        count_query = select(func.count()).select_from(query.subquery())
        total = s.scalar(count_query) or 0
        
        # Paginate
        offset = (page - 1) * per_page
        query = query.offset(offset).limit(per_page)
        
        candidates = s.scalars(query).all()
        
        # Get stats
        total_candidates = s.scalar(select(func.count(Candidate.id))) or 0
        verified_count = s.scalar(select(func.count(Candidate.id)).where(Candidate.email_verified == True)) or 0
        portal_signups = s.scalar(select(func.count(Candidate.id)).where(Candidate.source == "portal")) or 0
        recent_signups = s.scalar(
            select(func.count(Candidate.id)).where(
                Candidate.created_at >= datetime.datetime.utcnow() - datetime.timedelta(days=7)
            )
        ) or 0
    
    total_pages = (total + per_page - 1) // per_page
    
    return render_template(
        "admin_portal_users.html",
        candidates=candidates,
        search=search,
        status_filter=status_filter,
        source_filter=source_filter,
        page=page,
        total_pages=total_pages,
        total=total,
        total_candidates=total_candidates,
        verified_count=verified_count,
        portal_signups=portal_signups,
        recent_signups=recent_signups
    )

@app.route("/admin/portal-users/<int:cand_id>")
@login_required
def admin_portal_user_detail(cand_id: int):
    """View/edit a portal user's details."""
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            flash("Associate not found", "danger")
            return redirect(url_for("admin_portal_users"))

        # Get associate profile (detailed personal info from portal)
        profile = None
        try:
            from associate_portal import _ensure_models, _portal_model
            _ensure_models()
            AssociateProfile = _portal_model("AssociateProfile")
            if AssociateProfile:
                profile = s.scalars(
                    select(AssociateProfile).where(AssociateProfile.candidate_id == cand_id)
                ).first()
                if profile:
                    # Force load all profile attributes
                    _ = (profile.title, profile.first_name, profile.surname,
                         profile.dob, profile.address_line1, profile.address_line2,
                         profile.city, profile.postcode, profile.country,
                         profile.contact_number, profile.national_insurance_number,
                         profile.gender, profile.emergency_contact_name,
                         profile.emergency_contact_phone, profile.emergency_contact_relationship,
                         profile.aliases, profile.previous_names,
                         profile.current_salary, profile.expected_salary,
                         profile.available_from)
        except Exception:
            pass

        # Get applications for this candidate (eagerly load job relationship)
        applications = s.scalars(
            select(Application)
            .options(selectinload(Application.job))
            .where(Application.candidate_id == cand_id)
            .order_by(Application.created_at.desc())
        ).all()

        # Get documents
        documents = s.scalars(
            select(Document)
            .where(Document.candidate_id == cand_id)
            .order_by(Document.uploaded_at.desc())
        ).all()

        # Force load all attributes before session closes
        _ = cand.name, cand.email, cand.phone, cand.status, cand.source
        _ = cand.email_verified, cand.email_verified_at, cand.created_at
        _ = cand.last_login_at, cand.last_activity_at
        _ = getattr(cand, 'applications_blocked', False)
        if hasattr(cand, 'about'):
            _ = cand.about

        for app in applications:
            if app.job:
                _ = app.job.title

        for doc in documents:
            _ = doc.filename, doc.original_name, doc.doc_type, doc.uploaded_at

    return render_template(
        "admin_portal_user_detail.html",
        cand=cand,
        profile=profile,
        applications=applications,
        documents=documents
    )

