            "ALTER TABLE jobs ADD COLUMN dbs_vulnerable_adults_in_environment BOOLEAN DEFAULT FALSE",
            "ALTER TABLE jobs ADD COLUMN dbs_is_volunteer BOOLEAN DEFAULT FALSE",
