# -------------- Helpers --------------
def allowed_file(fname:str)->bool:
    return "." in fname and fname.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS

def save_upload(file_storage, subdir="cvs"):
    fname = secure_filename(file_storage.filename)
    if not allowed_file(fname):
        raise ValueError("Unsupported file type")
    new_name = f"{uuid.uuid4()}_{fname}"
    target_dir = os.path.join(app.config["UPLOAD_FOLDER"], subdir)
    os.makedirs(target_dir, exist_ok=True)
    path = os.path.join(target_dir, new_name)
    file_storage.save(path)
    return new_name, path, fname

def parse_date(s: Optional[str]):
    if not s:
        return None
    try:
        return dtparser.parse(s).replace(tzinfo=None)
    except Exception:
        return None

def parse_int(s, default=0):
    try:
        return int(str(s).replace(",", "").strip())
    except Exception:
        return default

def currency_fmt(n: int) -> str:
    try:
        return f"£{int(n):,}"
    except Exception:
        return "£0"

def _doc_file_path(doc: "Document") -> str:
    """Absolute path to a stored candidate document.

    Checks multiple storage locations in priority order:
    1. /data/uploads/ (Railway persistent volume)
    2. static/uploads/ (legacy app-relative)
    3. uploads/ (UPLOAD_FOLDER config)
    """
    filename = doc.filename or ""

    # Strip leading path prefixes to get the relative part
    rel = filename
    for prefix in ("uploads/associate_docs/", "uploads/cvs/", "uploads/"):
        if rel.startswith(prefix):
            rel = rel[len(prefix):]
            break

    # Check locations in priority order
    candidates = []

    # 1. Railway persistent volume
    if os.path.isdir("/data"):
        candidates.append(os.path.join("/data", filename))
        candidates.append(os.path.join("/data/uploads/associate_docs", rel))
        candidates.append(os.path.join("/data/uploads/cvs", rel))

    # 2. Static folder (legacy)
    app_root = os.path.dirname(__file__)
    candidates.append(os.path.join(app_root, "static", filename))
    candidates.append(os.path.join(app_root, "static", "uploads", "associate_docs", rel))
    candidates.append(os.path.join(app_root, "static", "uploads", "cvs", rel))

    # 3. UPLOAD_FOLDER config
    candidates.append(os.path.join(UPLOAD_FOLDER, "cvs", rel))
    candidates.append(os.path.join(UPLOAD_FOLDER, rel))

    for path in candidates:
        if os.path.exists(path):
            return path

    # Return first candidate path for error handling
    return candidates[0] if candidates else filename

def _truncate_for_ai(text: str, limit: int = 12000) -> str:
    """Light truncation to keep prompts reasonable."""
    if not text:
        return ""
    t = re.sub(r"\s+\n", "\n", text)
    t = re.sub(r"[ \t]+", " ", t)
    return t[:limit]

def _extract_text_from_pdf(path: str) -> str:
    # Try pdfplumber first (better layout handling)
    try:
        import pdfplumber
        text_parts = []
        with pdfplumber.open(path) as pdf:
            for page in pdf.pages:
                t = page.extract_text()
                if t:
                    text_parts.append(t)
        result = "\n".join(text_parts)
        if result.strip():
            print(f"[PDF] pdfplumber extracted {len(result)} chars from {path}")
            return result
    except Exception as e:
        print(f"[PDF] pdfplumber failed: {e}")

    # Fallback to PyPDF2
    if PdfReader is None:
        return ""
    try:
        with open(path, "rb") as f:
            reader = PdfReader(f)
            pages = [p.extract_text() or "" for p in reader.pages]
            result = "\n".join(pages)
            print(f"[PDF] PyPDF2 extracted {len(result)} chars from {path}")
            return result
    except Exception as e:
        print(f"[PDF] PyPDF2 failed: {e}")
        return ""

def _extract_text_from_docx(path: str) -> str:
    if docx is None:
        return ""
    try:
        d = docx.Document(path)
        paras = [p.text for p in d.paragraphs]
        return "\n".join(paras)
    except Exception as e:
        print("DOCX extract error:", e)
        return ""

def _extract_text_from_doc(path: str) -> str:
    """Legacy .doc via textract if available."""
    if textract is None:
        return ""
    try:
        raw = textract.process(path)
        return raw.decode("utf-8", errors="ignore")
    except Exception as e:
        print("DOC extract error:", e)
        return ""

def extract_cv_text(doc: "Document") -> str:
    """
    Extracts best-effort text from a stored CV Document.
    Supports: .pdf, .docx, .doc (optional via textract).
    """
    if not doc:
        return ""
    path = _doc_file_path(doc)
    ext = os.path.splitext(doc.original_name or doc.filename)[1].lower()

    text = ""
    if ext == ".pdf":
        text = _extract_text_from_pdf(path)
    elif ext == ".docx":
        text = _extract_text_from_docx(path)
    elif ext == ".doc":
        text = _extract_text_from_doc(path)

    # Fallback: try reading as plain text (some users upload .txt with wrong ext)
    if not text:
        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                text = f.read()
        except Exception:
            pass

    return _truncate_for_ai(text)

COMPLIANCE_FROM = os.getenv("COMPLIANCE_FROM_EMAIL", "compliance@optimussolutions.co.uk")
# Req 53 — finance@ mailbox is used for invoice emails. Mailbox is live in
# M365; if SendAs permission isn't granted yet the existing fallback in
# send_email() will retry under the default sender.
FINANCE_FROM = os.getenv("FINANCE_FROM_EMAIL", "finance@optimussolutions.co.uk")

def send_email(
    to_email,
    subject,
    html_body,
    attachments: Optional[List[Tuple[str, bytes, str]]] = None,
    from_email: Optional[str] = None,
) -> bool:
    """
    Send an email. Tries Brevo HTTP API first (works on cloud platforms where
    SMTP ports are blocked), falls back to SMTP if Brevo key not configured.
    Returns True on success, raises exception on failure.
    """
    # Append email signature with logo to all outgoing emails.
    # The contact address in the signature reflects the mailbox the email
    # is sent from (associates@ for interview/associate mail, compliance@
    # for vetting, finance@ for invoices) rather than a hardcoded address.
    _base_url = _resolve_app_base_url()
    _sig_email = (from_email or SMTP_FROM or COMPLIANCE_FROM).strip()
    _email_signature = f'''
<br><br>
<table cellpadding="0" cellspacing="0" border="0" style="font-family: Arial, sans-serif; font-size: 12px; color: #6b7280; line-height: 1.6;">
  <tr>
    <td style="padding-bottom: 10px;">
      <img src="{_base_url}/static/images/optimus-email-logo.png" alt="Optimus" style="height: 30px; width: auto;" />
    </td>
  </tr>
  <tr>
    <td style="border-top: 2px solid #2563eb; padding-top: 10px;">
      71-75 Shelton Street | London | WC2H 9JQ<br>
      <a href="mailto:{_sig_email}" style="color: #2563eb; text-decoration: none;">{_sig_email}</a><br>
      <strong style="color: #1e3a8a;">Optimus</strong> — Financial Services Resourcing Specialists
    </td>
  </tr>
</table>
'''
    if '<optimus-no-signature>' not in html_body:
        html_body = html_body + _email_signature

    # --- Microsoft 365 OAuth2 (primary — client's own mailbox) ---
    if (M365_TENANT_ID or "").strip() and (M365_CLIENT_ID or "").strip() and (M365_CLIENT_SECRET or "").strip():
        try:
            return _send_via_m365_oauth(to_email, subject, html_body, attachments, from_email=from_email)
        except Exception as e:
            err_text = str(e)
            # Fallback safety net — only triggers when the app
            # registration doesn't have permission to authenticate as
            # the requested mailbox. Now that we authenticate AS the
            # sender mailbox directly (not via cross-mailbox Send-As),
            # the typical failure surface is "auth failed" or
            # SendAsDenied for that specific mailbox. We still retry
            # via the default mailbox so the email gets out, and log
            # so the missing permission is visible in Railway logs.
            if from_email and from_email.lower() != (SMTP_FROM or "").lower() and (
                "SendAsDenied" in err_text or "5.2.252" in err_text or "not allowed to send as" in err_text
                or "AuthenticationFailed" in err_text or "authentication failed" in err_text.lower()
            ):
                print(
                    f"[M365] Could not authenticate as {from_email!r} ({err_text}); "
                    f"retrying via default mailbox {SMTP_FROM!r}. "
                    f"Confirm the OS1 app has SMTP send permission on {from_email!r} in Microsoft 365.",
                    flush=True,
                )
                try:
                    return _send_via_m365_oauth(
                        to_email, subject, html_body, attachments,
                        from_email=None,  # use SMTP_FROM
                    )
                except Exception as e2:
                    err_text = str(e2)
                    e = e2  # surface the inner error in the user-facing flash

            error_msg = f"M365 email failed for {to_email}: {e}"
            print(f"[M365] ERROR: {error_msg}")
            try:
                flash(f"Email to {to_email} failed via Microsoft 365: {e}. Please check M365 credentials.", "error")
            except RuntimeError:
                pass  # Outside request context (e.g. background task)
            raise RuntimeError(error_msg)

    # --- No M365 configured — this should not happen in production ---
    error_msg = "M365 email not configured. Set M365_TENANT_ID, M365_CLIENT_ID, and M365_CLIENT_SECRET."
    print(f"[EMAIL] ERROR: {error_msg}")
    try:
        flash(error_msg, "error")
    except RuntimeError:
        pass
    raise RuntimeError(error_msg)


def _send_via_m365_oauth(to_email, subject, html_body, attachments=None, from_email=None):
    """Send email via Microsoft 365 SMTP with OAuth2 XOAUTH2 authentication."""
    sender = from_email or SMTP_FROM
    print(f"[M365] Sending to {to_email} from {sender}: {subject}")

    # Step 1: Get OAuth2 access token
    token_url = f"https://login.microsoftonline.com/{M365_TENANT_ID}/oauth2/v2.0/token"
    token_resp = requests.post(token_url, data={
        "client_id": M365_CLIENT_ID,
        "client_secret": M365_CLIENT_SECRET,
        "scope": "https://outlook.office365.com/.default",
        "grant_type": "client_credentials",
    }, timeout=20)
    token_resp.raise_for_status()
    access_token = token_resp.json()["access_token"]

    # Step 2: Build email message
    msg = EmailMessage()
    msg["From"] = sender
    msg["To"] = to_email
    msg["Subject"] = subject
    msg.set_content("This email contains HTML content.")
    msg.add_alternative(html_body, subtype="html")

    if attachments:
        for filename, content, mime in attachments:
            maintype, subtype = mime.split("/", 1)
            msg.add_attachment(content, maintype=maintype, subtype=subtype, filename=filename)

    # Step 3: Connect to SMTP with XOAUTH2.
    # Authenticate AS the mailbox we want to send from. With the
    # client_credentials flow + the SMTP.SendAsApp Graph permission
    # granted to the OS1 app registration, the app can authenticate as
    # any mailbox in the tenant by setting `user=<mailbox>` in the
    # XOAUTH2 string. This avoids needing cross-mailbox Send-As
    # delegation (which was the previous approach: auth as associates@,
    # set From header to compliance@). Now compliance@ / finance@ each
    # authenticate as themselves and the From header lines up
    # naturally — no Send-As permission required.
    auth_string = f"user={sender}\x01auth=Bearer {access_token}\x01\x01"
    auth_b64 = base64.b64encode(auth_string.encode()).decode()

    server = smtplib.SMTP("smtp.office365.com", 587, timeout=30)
    server.ehlo()
    server.starttls()
    server.ehlo()

    code, resp_msg = server.docmd("AUTH", "XOAUTH2 " + auth_b64)
    if code != 235:
        server.quit()
        raise RuntimeError(f"M365 OAuth2 AUTH failed: {code} {resp_msg!r}")

    server.send_message(msg)
    server.quit()
    print(f"[M365] Successfully sent to {to_email}: {subject}")
    return True


# =============================================================================
# Req 8 — Microsoft Graph helpers for Teams calendar invites.
#
# Activates only when M365_GRAPH_ENABLED=1 AND the Azure AD admin has
# granted Calendars.ReadWrite + OnlineMeetings.ReadWrite.All to the OS1
# app registration. Until either is missing, the helper raises and the
# caller falls back to the legacy .ics-attachment flow.
#
# All four helpers are self-contained and use the same client credentials
# already wired up for the M365 SMTP send (M365_TENANT_ID / CLIENT_ID /
# CLIENT_SECRET). The scope changes to https://graph.microsoft.com/.default.
# =============================================================================

def _get_m365_graph_token() -> str:
    """Acquire an app-only OAuth2 access token for Microsoft Graph."""
    if not (M365_TENANT_ID and M365_CLIENT_ID and M365_CLIENT_SECRET):
        raise RuntimeError("M365_TENANT_ID / M365_CLIENT_ID / M365_CLIENT_SECRET not configured")
    token_url = f"https://login.microsoftonline.com/{M365_TENANT_ID}/oauth2/v2.0/token"
    resp = requests.post(token_url, data={
        "client_id": M365_CLIENT_ID,
        "client_secret": M365_CLIENT_SECRET,
        "scope": "https://graph.microsoft.com/.default",
        "grant_type": "client_credentials",
    }, timeout=20)
    resp.raise_for_status()
    return resp.json()["access_token"]


def _graph_event_payload(subject, body_html, start_dt, end_dt, attendees,
                         location_label, timezone, online=True):
    """Build the JSON body for POST/PATCH /events."""
    payload = {
        "subject": subject or "Interview",
        "body": {"contentType": "HTML", "content": body_html or ""},
        "start": {
            "dateTime": start_dt.strftime("%Y-%m-%dT%H:%M:%S"),
            "timeZone": timezone,
        },
        "end": {
            "dateTime": end_dt.strftime("%Y-%m-%dT%H:%M:%S"),
            "timeZone": timezone,
        },
        "attendees": [
            {
                "emailAddress": {
                    "address": (att.get("email") or "").strip(),
                    "name": (att.get("name") or "").strip() or att.get("email", ""),
                },
                "type": att.get("type", "required"),
            }
            for att in attendees if (att.get("email") or "").strip()
        ],
    }
    if online:
        payload["isOnlineMeeting"] = True
        payload["onlineMeetingProvider"] = "teamsForBusiness"
    if location_label:
        payload["location"] = {"displayName": location_label}
    return payload


def create_teams_calendar_event(*, organiser_upn, attendees, subject,
                                body_html, start_dt, end_dt,
                                location_label="", timezone=None) -> dict:
    """Req 8 — create a real Outlook calendar event in the organiser's
    mailbox with a Teams meeting auto-attached.

    Returns {"event_id": "...", "join_url": "...", "web_link": "..."}.
    Raises RuntimeError when M365_GRAPH_ENABLED is off OR when admin
    consent for Calendars.ReadWrite / OnlineMeetings.ReadWrite.All has
    not been granted (Graph returns 403). Caller is expected to catch
    and fall back to the .ics path.
    """
    if not M365_GRAPH_ENABLED:
        raise RuntimeError("M365_GRAPH_ENABLED is off")
    if not organiser_upn:
        raise RuntimeError("organiser_upn is required")

    token = _get_m365_graph_token()
    timezone = timezone or M365_GRAPH_TIMEZONE
    payload = _graph_event_payload(
        subject=subject, body_html=body_html,
        start_dt=start_dt, end_dt=end_dt,
        attendees=attendees, location_label=location_label, timezone=timezone,
    )
    from urllib.parse import quote
    url = f"https://graph.microsoft.com/v1.0/users/{quote(organiser_upn)}/events"
    resp = requests.post(url, headers={
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }, json=payload, timeout=30)
    if resp.status_code == 403:
        raise RuntimeError(
            "Graph 403 — admin consent for Calendars.ReadWrite + "
            "OnlineMeetings.ReadWrite.All has not been granted yet"
        )
    resp.raise_for_status()
    data = resp.json()
    return {
        "event_id": data.get("id", ""),
        "join_url": (data.get("onlineMeeting") or {}).get("joinUrl", ""),
        "web_link": data.get("webLink", ""),
    }


def update_teams_calendar_event(*, organiser_upn, event_id, attendees,
                                subject, body_html, start_dt, end_dt,
                                location_label="", timezone=None) -> dict:
    """Reschedule path — PATCH an existing /events/{event_id}. Microsoft
    re-sends the calendar invite to attendees automatically."""
    if not M365_GRAPH_ENABLED:
        raise RuntimeError("M365_GRAPH_ENABLED is off")
    if not (organiser_upn and event_id):
        raise RuntimeError("organiser_upn and event_id are required")

    token = _get_m365_graph_token()
    timezone = timezone or M365_GRAPH_TIMEZONE
    payload = _graph_event_payload(
        subject=subject, body_html=body_html,
        start_dt=start_dt, end_dt=end_dt,
        attendees=attendees, location_label=location_label, timezone=timezone,
    )
    from urllib.parse import quote
    url = (
        f"https://graph.microsoft.com/v1.0/users/"
        f"{quote(organiser_upn)}/events/{quote(event_id)}"
    )
    resp = requests.patch(url, headers={
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }, json=payload, timeout=30)
    resp.raise_for_status()
    data = resp.json()
    return {
        "event_id": data.get("id", event_id),
        "join_url": (data.get("onlineMeeting") or {}).get("joinUrl", ""),
        "web_link": data.get("webLink", ""),
    }


def cancel_teams_calendar_event(*, organiser_upn, event_id) -> bool:
    """Cancel-and-notify a previously-created calendar event."""
    if not (M365_GRAPH_ENABLED and organiser_upn and event_id):
        return False
    try:
        token = _get_m365_graph_token()
        from urllib.parse import quote
        url = (
            f"https://graph.microsoft.com/v1.0/users/"
            f"{quote(organiser_upn)}/events/{quote(event_id)}/cancel"
        )
        resp = requests.post(url, headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        }, json={"comment": "The interview has been cancelled."}, timeout=30)
        # Graph returns 202 on accepted-for-cancel.
        return resp.ok
    except Exception:
        current_app.logger.exception("cancel_teams_calendar_event failed")
        return False


def _send_via_brevo(to_email, subject, html_body, attachments=None):
    """Send email via Brevo transactional email API (HTTPS, port 443)."""
    print(f"[BREVO] Sending to {to_email}: {subject}")
    payload = {
        "sender": {"email": SMTP_FROM},
        "to": [{"email": to_email}],
        "subject": subject,
        "htmlContent": html_body,
    }
    if attachments:
        payload["attachment"] = []
        for filename, content, mime in attachments:
            payload["attachment"].append({
                "name": filename,
                "content": base64.b64encode(content).decode("utf-8"),
            })

    resp = requests.post(
        "https://api.brevo.com/v3/smtp/email",
        headers={
            "api-key": BREVO_API_KEY.strip(),
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        json=payload,
        timeout=30,
    )
    if resp.status_code in (200, 201):
        msg_id = resp.json().get("messageId", "unknown")
        print(f"[BREVO] Successfully sent to {to_email} (messageId: {msg_id})")
        return True
    else:
        print(f"[BREVO] Failed: {resp.status_code} {resp.text}")
        raise RuntimeError(f"Brevo API error {resp.status_code}: {resp.text}")


def _send_via_smtp(to_email, subject, html_body, attachments=None):
    """Send email via SMTP (legacy fallback)."""
    msg = EmailMessage()
    msg["From"] = SMTP_FROM
    msg["To"] = to_email
    msg["Subject"] = subject
    msg.set_content("This email contains HTML and possibly an ICS invite.")
    msg.add_alternative(html_body, subtype="html")

    if attachments:
        for filename, content, mime in attachments:
            maintype, subtype = mime.split("/", 1)
            msg.add_attachment(
                content,
                maintype=maintype,
                subtype=subtype,
                filename=filename,
            )

    context = ssl.create_default_context()
    print(f"[SMTP] Connecting to {SMTP_HOST}:{SMTP_PORT} for {to_email}...")
    try:
        with smtplib.SMTP(SMTP_HOST.strip(), SMTP_PORT, timeout=30) as server:
            server.set_debuglevel(0)
            ehlo_code, ehlo_msg = server.ehlo()
            print(f"[SMTP] EHLO response: {ehlo_code} {ehlo_msg.decode()[:100]}")
            tls_code, tls_msg = server.starttls(context=context)
            print(f"[SMTP] STARTTLS response: {tls_code} {tls_msg.decode()[:100]}")
            if SMTP_USER and SMTP_PASS:
                try:
                    login_code, login_msg = server.login(SMTP_USER, SMTP_PASS)
                    print(f"[SMTP] LOGIN response: {login_code} {login_msg.decode()[:100]}")
                except smtplib.SMTPAuthenticationError as auth_err:
                    print(f"[SMTP] AUTH FAILED: {auth_err.smtp_code} {auth_err.smtp_error}")
                    raise
            server.send_message(msg)
            print(f"[EMAIL] Successfully sent to {to_email}: {subject}")
    except smtplib.SMTPAuthenticationError as e:
        print(f"[SMTP] Authentication error: Code={e.smtp_code}, Error={e.smtp_error}")
        raise
    except smtplib.SMTPException as e:
        print(f"[SMTP] SMTP error: {type(e).__name__}: {e}")
        raise
    except Exception as e:
        print(f"[SMTP] Unexpected error: {type(e).__name__}: {e}")
        raise
    return True

# Lightweight stopword set for JD term selection
_STOP = {
    "the","and","for","with","from","into","your","our","you","are","this","that","will","have","has",
    "per","role","job","team","work","working","experience","years","year","etc","such","across","able",
    "strong","good","great","excellent","within","including","include","on","in","of","to","a","an","as",
    "by","is","be","we","they","their","them","it","its","or","not","at","over","under"
}

def _jd_top_terms(job_desc: str, n: int = 8) -> List[str]:
    tokens = _tokenize_words(job_desc)
    freq: Dict[str, int] = {}
    for t in tokens:
        if t in _STOP or len(t) < 3:
            continue
        freq[t] = freq.get(t, 0) + 1
    # rank by frequency then alphabetically for stability
    top = sorted(freq.items(), key=lambda kv: (-kv[1], kv[0]))[:n]
    return [w for w, _ in top]

def _cheap_overlap_score(jd_terms: List[str], skills: str) -> int:
    """Very cheap overlap against normalised skills text (no CV parsing)."""
    if not skills:
        return 0
    s = skills.lower()
    hits = sum(1 for t in jd_terms if t and t in s)
    # weight a tiny bit by string length to avoid ties
    return hits * 10 + min(5, len(s) // 2000)

def ics_invite(summary, description, start_dt: datetime.datetime, end_dt: datetime.datetime, location, organizer_email, attendee_email, teams_url: str = ""):
    """
    Build a standard .ics invite attachment for email.

    When ``teams_url`` is supplied (or ``location`` itself is an http(s)
    URL), emit Microsoft's Teams-specific calendar properties so Outlook
    renders the native "Join Microsoft Teams Meeting" button on the
    calendar event instead of just showing the URL as plain text.
    """
    from email.utils import parseaddr

    organizer_email = parseaddr(organizer_email)[1] or organizer_email
    uid = f"{uuid.uuid4()}@{request.host}".replace(":", "")
    dtfmt = "%Y%m%dT%H%M%SZ"

    def _fmt(dt):
        if not dt:
            return ""
        if dt.tzinfo:
            dt = dt.astimezone(datetime.timezone.utc)
        return dt.strftime(dtfmt)

    start_utc = _fmt(start_dt)
    end_utc = _fmt(end_dt)

    # If the caller didn't pass teams_url explicitly but the location is
    # itself an http(s) link, treat the location as the join URL — that's
    # what happens when staff paste a Teams link into the modal's
    # Location field manually.
    if not teams_url and isinstance(location, str) and location.strip().lower().startswith(("http://", "https://")):
        teams_url = location.strip()

    desc_with_url = description or ""
    if teams_url and teams_url not in desc_with_url:
        desc_with_url = (desc_with_url + ("\\n\\n" if desc_with_url else "") +
                         f"Join Microsoft Teams Meeting: {teams_url}")

    extra_lines = []
    if teams_url:
        extra_lines.append(f"URL:{teams_url}")
        extra_lines.append(f"X-MICROSOFT-SKYPETEAMSMEETINGURL:{teams_url}")
        extra_lines.append(f"X-MICROSOFT-ONLINEMEETINGCONFLINK:{teams_url}")
    extra_block = ("\n" + "\n".join(extra_lines)) if extra_lines else ""

    ics = f"""BEGIN:VCALENDAR
PRODID:-//ATS//Interview//EN
VERSION:2.0
CALSCALE:GREGORIAN
METHOD:REQUEST
BEGIN:VEVENT
DTSTAMP:{datetime.datetime.utcnow().strftime(dtfmt)}
DTSTART:{start_utc}
DTEND:{end_utc}
SUMMARY:{summary}
UID:{uid}
DESCRIPTION:{desc_with_url}
ORGANIZER;CN=Talent Ops:MAILTO:{organizer_email}
ATTENDEE;CN=Candidate;RSVP=TRUE:MAILTO:{attendee_email}
LOCATION:{location}{extra_block}
END:VEVENT
END:VCALENDAR
"""
    return ics.encode("utf-8")

# ---- Jinja helpers ----
@app.template_filter("slugify")
def slugify(value: str) -> str:
    s = (value or "").lower().replace(" ", "_")
    return re.sub(r"[^a-z0-9_]", "", s)

@app.template_filter("from_json_safe")
def from_json_safe(value):
    """Parse JSON string to list, returning empty list on failure."""
    if not value:
        return []
    try:
        result = json.loads(value)
        return result if isinstance(result, list) else []
    except (json.JSONDecodeError, TypeError):
        return []


@app.template_filter("md")
def render_markdown(value: str) -> str:
    """Render Markdown to bleach-sanitised HTML. Used for job descriptions
    so that bullets / headings / numbered lists carry through to the
    candidate-facing vacancy view instead of collapsing into one paragraph.
    Falls back to a paragraph-wrapped escaped version if markdown isn't
    importable (so the page never 500s)."""
    if not value:
        return ""
    try:
        import markdown as _md
        html = _md.markdown(
            value,
            extensions=["extra", "sane_lists", "nl2br"],
            output_format="html5",
        )
    except Exception:
        from markupsafe import escape as _esc
        return f"<p>{_esc(value).replace(chr(10), '<br>')}</p>"
    try:
        import bleach as _bleach
        allowed_tags = list(_bleach.sanitizer.ALLOWED_TAGS) + [
            "p", "br", "h1", "h2", "h3", "h4", "h5", "h6",
            "ul", "ol", "li", "strong", "em", "code", "pre",
            "blockquote", "hr", "table", "thead", "tbody",
            "tr", "th", "td",
        ]
        allowed_attrs = {"a": ["href", "title", "rel", "target"]}
        html = _bleach.clean(html, tags=allowed_tags, attributes=allowed_attrs, strip=True)
    except Exception:
        pass
    return html

def slugify_role(name: str) -> str:
    s = (name or "").lower().replace(" ", "_")
    return re.sub(r"[^a-z0-9_]", "", s)

