# ---- Opportunities: edit ----
@app.route("/opportunity/<int:opp_id>", methods=["GET", "POST"])
@login_required
def opportunity_edit(opp_id):
    # Track where the user came from so Save/Cancel go back there
    return_url = request.form.get("return_url") or request.referrer or url_for("pipeline")
    # Load the opportunity row
    with Session(engine) as s:
        opp = s.scalar(select(Opportunity).where(Opportunity.id == opp_id))
        if not opp:
            abort(404)

        # Load owners for dropdown
        users_rows = s.execute(
            text("SELECT id, name FROM users ORDER BY name ASC")
        ).all()
        choices = [(u[0], u[1]) for u in users_rows]

        # We'll need to map owner name -> id for initial form data
        owner_id_for_form = None
        if opp.owner:
            for uid, uname in choices:
                if (uname or "").strip() == (opp.owner or "").strip():
                    owner_id_for_form = uid
                    break

        # Prefill form
        form = OpportunityForm(
            name=opp.name,
            client=opp.client,
            stage=opp.stage,
            owner=owner_id_for_form,
            est_start=opp.est_start.strftime("%Y-%m-%d") if opp.est_start else "",
            est_value=opp.est_value or 0,
            notes="",  # Req-041: notes field is now for adding new entries, not editing old
            client_contact_name = opp.client_contact_name or "",
            client_contact_role = opp.client_contact_role or "",
            client_contact_phone = opp.client_contact_phone or "",
            client_contact_email = opp.client_contact_email or "",
        )
        form.owner.choices = choices

        if form.validate_on_submit():
            prev_stage = (opp.stage or "").strip().lower()

            # Map owner dropdown (user id) back to owner name string for storage
            new_owner_name = ""
            if form.owner.data:
                row = s.execute(
                    text("SELECT name FROM users WHERE id=:i"),
                    {"i": form.owner.data},
                ).first()
                if row:
                    new_owner_name = row[0] or ""

            opp.name = form.name.data
            opp.client = form.client.data or ""
            opp.stage = form.stage.data
            opp.owner = new_owner_name
            raw_est = (form.est_start.data or "").strip()
            if raw_est:
                try:
                    opp.est_start = datetime.datetime.strptime(raw_est, "%Y-%m-%d")
                except ValueError:
                    opp.est_start = parse_date_dmy(raw_est)  # fallback for DD-MM-YYYY
            else:
                opp.est_start = None
            opp.est_value = int(form.est_value.data or 0)

            # Set probability based on stage
            _stage_prob = {"lead": 0, "qualified lead": 10, "proposal": 30, "procurement": 50, "closed won": 100, "closed lost": 0}
            opp.probability = _stage_prob.get((opp.stage or "").strip().lower(), 0)

            # Req-041: Save notes as timestamped entries instead of overwriting
            new_note_text = (form.notes.data or "").strip()
            if new_note_text:
                opp_note = OpportunityNote(
                    opportunity_id=opp.id,
                    user_email=current_user.email if current_user.is_authenticated else "",
                    content=new_note_text,
                    note_type="note",
                )
                s.add(opp_note)

            opp.client_contact_name  = form.client_contact_name.data  or ""
            opp.client_contact_role  = form.client_contact_role.data  or ""
            opp.client_contact_phone = form.client_contact_phone.data or ""
            opp.client_contact_email = form.client_contact_email.data or ""

            # If it becomes Closed Won and no engagement linked yet, create one
            new_stage = (opp.stage or "").strip().lower()
            e = None
            if new_stage == "closed won" and not opp._engagement_id:
                e = create_engagement_for_opportunity(s, opp)

            # If renaming a Closed Won opportunity, also update the linked engagement name
            if new_stage == "closed won" and opp._engagement_id:
                linked_eng = s.get(Engagement, opp._engagement_id)
                if linked_eng:
                    linked_eng.name = opp.name or linked_eng.name
                    linked_eng.client = opp.client or linked_eng.client

            s.commit()
            flash("Opportunity updated", "success")

            if e:
                flash(f"Engagement {e.ref} created.", "success")
                return redirect(url_for("engagement_dashboard", eng_id=e.id))

            # If "Add Note" was clicked, stay on page; otherwise go back
            if request.form.get("action") == "add_note":
                return redirect(url_for("opportunity_edit", opp_id=opp_id))
            return redirect(return_url)

    # Req-041: Load timestamped notes for display
    with Session(engine) as s:
        opp_notes = s.scalars(
            select(OpportunityNote)
            .where(OpportunityNote.opportunity_id == opp_id)
            .order_by(OpportunityNote.created_at.desc())
        ).all()

    return render_template("opportunity_edit.html", form=form, opp=opp, opp_notes=opp_notes, return_url=return_url)

