@app.route("/action/contract/retract/<int:cand_id>", methods=["POST"])
@login_required
def retract_contract(cand_id):
    """Retract an issued contract — sets ESigRequest status to Retracted."""
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)

        esig = s.scalar(
            select(ESigRequest)
            .where(ESigRequest.candidate_id == cand_id)
            .where(ESigRequest.status.notin_(["Retracted", "Signed", "Completed"]))
            .order_by(ESigRequest.created_at.desc())
        )
        if not esig:
            flash("No active contract to retract.", "warning")
            return

        old_status = esig.status
        esig.status = "Retracted"

        # Update application status back to previous stage
        appn = s.scalar(
            select(Application)
            .where(Application.candidate_id == cand_id)
            .order_by(Application.created_at.desc())
        )
        if appn and appn.status in ("Contract Issued", "Contract Sent"):
            appn.status = "Accepted"

        # Clear the umbrella_assignment_* flags so the Contract card on
        # the candidate profile stops showing "Assignment Schedule Signed"
        # for a contract that has been retracted. Without this the
        # display sticks until the next end_assignment / new contract
        # creation.
        if hasattr(cand, "umbrella_assignment_sent"):
            cand.umbrella_assignment_sent = False
        if hasattr(cand, "umbrella_assignment_sent_at"):
            cand.umbrella_assignment_sent_at = None
        if hasattr(cand, "umbrella_assignment_signed"):
            cand.umbrella_assignment_signed = False
        if hasattr(cand, "umbrella_assignment_signed_at"):
            cand.umbrella_assignment_signed_at = None

        # Add note
        note = CandidateNote(
            candidate_id=cand_id,
            user_email=current_user.email if current_user.is_authenticated else "System",
            note_type="system",
            content=f"Contract retracted (was: {old_status})"
        )
        s.add(note)

        log_audit_event('update', 'workflow',
                        f'Contract retracted for candidate {cand.name}',
                        'candidate', cand_id,
                        {'old_status': old_status, 'new_status': 'Retracted'})
        s.commit()
        flash("Contract retracted.", "success")

    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/action/offer/retract/<int:cand_id>", methods=["POST"])
@login_required
def retract_offer(cand_id):
    """Retract an offer that is sitting at 'Offered' awaiting candidate response.

    Clears offer_made_at and moves the application back one stage to 'Client
    Review' so the recruiter can re-decide. The captured offer_* values are
    kept so they pre-fill again if the offer is re-issued.
    """
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)

        app_id = request.form.get("app_id", type=int)
        q = (
            select(Application)
            .where(Application.candidate_id == cand_id)
            .where(Application.status == "Offered")
        )
        if app_id:
            q = q.where(Application.id == app_id)
        q = q.order_by(Application.offer_made_at.desc().nulls_last(), Application.created_at.desc())
        appn = s.scalar(q)
        if not appn:
            flash("No offer to retract — this application is not at the Offered stage.", "warning")
            return redirect(url_for("candidate_profile", cand_id=cand_id))

        old_status = appn.status
        appn.status = "Client Review"
        appn.offer_made_at = None

        user_email = getattr(current_user, "email", "staff") or "staff"
        s.add(CandidateNote(
            candidate_id=cand_id,
            user_email=user_email,
            note_type="activity",
            content=f"Offer of Engagement retracted (was: {old_status}) for application #{appn.id}.",
            created_at=datetime.datetime.utcnow(),
        ))

        log_audit_event(
            "update", "workflow",
            f"Offer retracted for candidate {cand.name}",
            "candidate", cand_id,
            {"application_id": appn.id, "old_status": old_status, "new_status": "Client Review"},
        )
        s.commit()
        flash("Offer retracted.", "success")

    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/action/issue-contract/precheck-withdraw/<int:cand_id>", methods=["POST"])
@login_required
def issue_contract_precheck_withdraw(cand_id):
    """Req 44 — used by the paystream_capture entrypoint. Withdraws the
    candidate's other open applications selected on the confirmation page,
    then redirects back to the capture sheet via ?cascaded=1 so the guard
    doesn't fire again.
    """
    if (request.form.get("confirm_withdraw") or "") != "1":
        flash("Withdrawal confirmation missing.", "warning")
        return redirect(url_for("candidate_profile", cand_id=cand_id))

    next_url = request.form.get("next_url") or url_for("candidate_profile", cand_id=cand_id)
    # Only allow same-host relative URLs as the destination so this can't be
    # turned into an open redirect.
    if "://" in next_url or not next_url.startswith("/"):
        next_url = url_for("candidate_profile", cand_id=cand_id)

    requested_ids = request.form.getlist("withdraw_app_ids", type=int)
    OPEN_STATUSES_EXCLUDED = ("Rejected", "Withdrawn", "Closed", "Hired", "Contract Signed", "Contract Issued", "Contract Sent", "Placed")

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)
        user_email = getattr(current_user, "email", "staff") or "staff"
        withdrawn = 0
        for app_id_to_withdraw in requested_ids:
            other = s.get(Application, app_id_to_withdraw)
            if not other or other.candidate_id != cand_id:
                continue
            if (other.status or "") in OPEN_STATUSES_EXCLUDED:
                continue
            prev_status = other.status
            other.status = "Withdrawn"
            s.add(CandidateNote(
                candidate_id=cand_id,
                user_email=user_email,
                note_type="activity",
                content=(
                    f"Application withdrawn ({prev_status} → Withdrawn) — "
                    f"placed on another role via Issue Contract."
                ),
                created_at=datetime.datetime.utcnow(),
            ))
            withdrawn += 1
        if withdrawn:
            log_audit_event(
                "update", "contract",
                f"BULK_WITHDRAW — {withdrawn} application(s) withdrawn before contract issue",
                "candidate", cand_id,
                {"withdrawn_application_ids": requested_ids, "via": "paystream_capture"},
            )
        s.commit()

    if withdrawn:
        flash(f"Withdrew {withdrawn} other open application(s). Continuing to the assignment sheet.", "success")
    return redirect(next_url)


@app.route("/action/contract/issue/<int:cand_id>/<int:eng_id>", methods=["POST"])
@login_required
def action_contract_issue(cand_id, eng_id):
    """Issue contract for this candidate and engagement — sends via Signable if configured."""
    role_title = request.form.get("role_title", "").strip()
    contract_type = request.form.get("contract_type", "Fixed Term")
    start_date = request.form.get("start_date", "")
    expiry_date = request.form.get("expiry_date", "")
    daily_rate = request.form.get("daily_rate", "")
    notes = request.form.get("notes", "")

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        eng = s.get(Engagement, eng_id)
        if not cand or not eng:
            flash("Candidate or engagement not found.", "danger")
            return redirect(request.referrer or url_for("workflow"))

        # Find the candidate's application for this engagement
        appn = s.scalar(
            select(Application)
            .join(Job, Job.id == Application.job_id)
            .where(Application.candidate_id == cand_id)
            .where(Job.engagement_id == eng_id)
            .order_by(Application.created_at.desc())
        )

        # Req 44 — gate: if the candidate has other open applications,
        # they must be withdrawn before the contract can be issued so
        # the per-role contract status in the associate portal stays
        # accurate. The user only sees the prompt when there's actually
        # something to withdraw; otherwise the flow continues unchanged.
        OPEN_STATUSES_EXCLUDED = ("Rejected", "Withdrawn", "Closed", "Hired", "Contract Signed")
        other_open_apps_q = (
            select(Application, Job, Engagement)
            .join(Job, Job.id == Application.job_id)
            .join(Engagement, Engagement.id == Job.engagement_id, isouter=True)
            .where(Application.candidate_id == cand_id)
            .where(Application.status.notin_(OPEN_STATUSES_EXCLUDED))
        )
        if appn:
            other_open_apps_q = other_open_apps_q.where(Application.id != appn.id)
        other_open_rows = s.execute(other_open_apps_q).all()

        confirm_withdraw = (request.form.get("confirm_withdraw") or "").strip() == "1"
        if other_open_rows and not confirm_withdraw:
            # Render the confirmation page listing the other open
            # applications. Submitting that form re-POSTs here with
            # confirm_withdraw=1 + the chosen withdraw_app_ids.
            other_apps = [
                {
                    "id": row[0].id,
                    "status": row[0].status or "",
                    "job_title": row[1].title if row[1] else "",
                    "engagement_name": row[2].name if row[2] else "",
                    "client": row[2].client if row[2] else "",
                }
                for row in other_open_rows
            ]
            log_audit_event(
                "update", "contract",
                f"ISSUE_CONTRACT_BLOCKED — {len(other_apps)} other open application(s)",
                "candidate", cand_id,
                {"other_app_ids": [a["id"] for a in other_apps]},
            )
            return render_template(
                "issue_contract_confirm.html",
                cand=cand,
                eng=eng,
                appn=appn,
                other_apps=other_apps,
                form_values=request.form.to_dict(),
            )

        if confirm_withdraw:
            requested_ids = request.form.getlist("withdraw_app_ids", type=int)
            if requested_ids:
                user_email = getattr(current_user, "email", "staff") or "staff"
                withdrawn = 0
                for app_id_to_withdraw in requested_ids:
                    other = s.get(Application, app_id_to_withdraw)
                    if not other or other.candidate_id != cand_id:
                        continue
                    if appn and other.id == appn.id:
                        continue  # never withdraw the one being contracted
                    if other.status in OPEN_STATUSES_EXCLUDED:
                        continue
                    prev_status = other.status
                    other.status = "Withdrawn"
                    s.add(CandidateNote(
                        candidate_id=cand_id,
                        user_email=user_email,
                        note_type="activity",
                        content=(
                            f"Application withdrawn ({prev_status} → Withdrawn) — "
                            f"placed on engagement {eng.name!r} via another role."
                        ),
                        created_at=datetime.datetime.utcnow(),
                    ))
                    withdrawn += 1
                if withdrawn:
                    log_audit_event(
                        "update", "contract",
                        f"BULK_WITHDRAW — {withdrawn} application(s) withdrawn before contract issue",
                        "candidate", cand_id,
                        {"withdrawn_application_ids": requested_ids, "for_engagement": eng_id},
                    )
                s.flush()

        # Check vetting is complete before allowing contract issuance.
        # TEMPORARY BYPASS (2026-04-16): user needs to test the Paystream
        # Assignment Schedule capture-sheet + auto-fill flow without having
        # to complete vetting first. Flip BYPASS_VETTING_GATE back to False
        # once Paystream testing is done.
        BYPASS_VETTING_GATE = True
        if not BYPASS_VETTING_GATE:
            vetting_checks = s.scalars(
                select(VettingCheck).where(VettingCheck.candidate_id == cand_id)
            ).all()
            if vetting_checks:
                incomplete = [vc for vc in vetting_checks if vc.status not in (
                    "Complete", "COMPLETE", "N/A", "QC COMPLETE", "QC NOT REQUIRED", "REFERRAL APPROVED"
                )]
                if incomplete:
                    incomplete_names = ", ".join(vc.check_type for vc in incomplete[:3])
                    remaining = len(incomplete) - 3
                    msg = f"Cannot issue contract — vetting is not complete. Outstanding: {incomplete_names}"
                    if remaining > 0:
                        msg += f" and {remaining} more"
                    flash(msg, "danger")
                    return redirect(request.referrer or url_for("candidate_profile", cand_id=cand_id))
            else:
                # No vetting checks exist at all — vetting hasn't been started
                flash("Cannot issue contract — vetting has not been started for this candidate.", "danger")
                return redirect(request.referrer or url_for("candidate_profile", cand_id=cand_id))

        # Parse dates
        start_dt = None
        end_dt = None
        try:
            if start_date:
                start_dt = datetime.datetime.strptime(start_date, "%Y-%m-%d")
            if expiry_date:
                end_dt = datetime.datetime.strptime(expiry_date, "%Y-%m-%d")
        except ValueError:
            pass

        # Get or create ESigRequest. The placements view dedupes signed
        # rows by application_id, so we never want two non-retracted
        # ESigRequests for the same application — that would surface as
        # duplicate placement rows on /placements (Req 19).
        esig = _get_or_create_active_esig(
            s,
            candidate_id=cand_id,
            application_id=appn.id if appn else None,
            engagement_id=eng_id,
            provider="signable",
            status="pending",
            end_date=end_dt,
        )
        s.flush()

        # Update application status
        if appn:
            appn.status = "Contract Issued"

        # Update candidate status
        cand.status = "In Vetting"

        # Log activity
        activity = CandidateNote(
            candidate_id=cand_id,
            user_email=session.get("user_email", "system"),
            note_type="activity",
            content=f"Contract issued: {role_title} ({contract_type}), {eng.name} — £{daily_rate}/day",
            created_at=datetime.datetime.utcnow()
        )
        s.add(activity)

        # Send via Signable if API key is configured
        if SIGNABLE_API_KEY:
            try:
                subject = f"Contract: {role_title} - {eng.name}"
                message = f"Please review and sign your contract for the role of {role_title} with {eng.client or eng.name}."
                result = send_esign_signable(
                    appn.id if appn else esig.id,
                    cand.name, cand.email,
                    subject, message
                )
                if result:
                    esig.request_id = result["envelope_id"]
                    esig.signing_url = result.get("signing_url")
                    esig.status = "Sent"
                    esig.sent_at = datetime.datetime.utcnow()
                    flash(f"Contract sent to {cand.email} via Signable.", "success")
                else:
                    esig.status = "Error"
                    flash("Contract created but Signable send failed.", "warning")
            except Exception as e:
                current_app.logger.warning(f"Signable send failed: {e}")
                esig.status = "Error"
                flash(f"Contract created but Signable send failed: {e}", "warning")
        else:
            esig.status = "pending"
            flash("Contract issued (Signable not configured — manual signing required).", "success")

        s.commit()

        log_audit_event('create', 'contract',
                       f'Contract issued for {cand.name}: {role_title} ({contract_type})',
                       'candidate', cand_id,
                       {'engagement_id': eng_id, 'role': role_title, 'rate': daily_rate,
                        'start': start_date, 'end': expiry_date, 'signable_sent': bool(SIGNABLE_API_KEY)})

    return redirect(request.referrer or url_for("candidate_profile", cand_id=cand_id))

