def _has_signed_contract_doc(s, candidate_id: int) -> bool:
    """Req 18 — return True if the candidate already has a SIGNED_CONTRACT
    Document on file. Used to gate progression to Placed: the staff member
    must upload the signed PDF before the kanban tick / profile confirm
    button will move the candidate forward."""
    return s.scalar(
        select(Document)
        .where(Document.candidate_id == candidate_id)
        .where(Document.doc_type == "SIGNED_CONTRACT")
        .limit(1)
    ) is not None


def _save_signed_contract_doc(s, file_storage, candidate_id: int, application_id=None, engagement_id=None):
    """Req 18 — persist an uploaded signed-contract PDF to the uploads
    folder and create a Document row. Returns the Document. Raises
    ValueError on unsupported file type."""
    new_name, _path, original = save_upload(file_storage, subdir="signed_contracts")
    doc = Document(
        candidate_id=candidate_id,
        doc_type="SIGNED_CONTRACT",
        filename=os.path.join("signed_contracts", new_name),
        original_name=original,
        uploaded_at=datetime.datetime.utcnow(),
        engagement_id=engagement_id,
    )
    s.add(doc)
    return doc


def _apply_contract_signed(s, cand, *, source: str = "manual"):
    """Req 17 — canonical "contract signed" state transition. Both the
    kanban "Confirm Contract Signed" tick AND the profile Assignment
    Schedule "Confirm signed" button now go through this helper so
    they're guaranteed to update every dependent field:

      - ESigRequest.status = 'signed' (+ signed_at, application_id,
        engagement_id) via _get_or_create_active_esig.
      - Candidate.umbrella_assignment_signed = True (+ signed_at) so
        the profile's "Awaiting Signature" panel flips to "Signed".
      - Application.status = 'Placed' so the kanban card moves.
      - Candidate.status = 'On Assignment' so the resource pool +
        profile pill agree.
      - CandidateNote activity + log_audit_event entry.

    Returns the (esig, latest_app) it touched so the caller can reuse
    them for an audit log.
    """
    cand_id = cand.id
    esig = _get_or_create_active_esig(
        s,
        candidate_id=cand_id,
        status="signed",
        signed_at=datetime.datetime.utcnow(),
    )
    esig.status = "signed"
    if not esig.signed_at:
        esig.signed_at = datetime.datetime.utcnow()

    latest_app = s.scalar(
        select(Application)
        .where(Application.candidate_id == cand_id)
        .where(Application.status.notin_(["Rejected", "Withdrawn", "Closed"]))
        .order_by(Application.created_at.desc())
    )
    if latest_app:
        latest_app.status = "Placed"
        if not esig.application_id:
            esig.application_id = latest_app.id
        if latest_app.job_id and not esig.engagement_id:
            _job = s.get(Job, latest_app.job_id)
            if _job and _job.engagement_id:
                esig.engagement_id = _job.engagement_id

    # Sync the umbrella assignment-signed flags on the candidate so the
    # profile Assignment Schedule panel renders as "Signed" instead of
    # "Awaiting Signature".
    if hasattr(cand, "umbrella_assignment_signed"):
        cand.umbrella_assignment_signed = True
    if hasattr(cand, "umbrella_assignment_signed_at") and not getattr(cand, "umbrella_assignment_signed_at", None):
        cand.umbrella_assignment_signed_at = datetime.datetime.utcnow()
    # If the assignment was never marked sent (e.g. straight from kanban
    # without going through the capture sheet), set the sent flags too
    # so the panel doesn't render in an inconsistent state.
    if hasattr(cand, "umbrella_assignment_sent") and not getattr(cand, "umbrella_assignment_sent", False):
        cand.umbrella_assignment_sent = True
    if hasattr(cand, "umbrella_assignment_sent_at") and not getattr(cand, "umbrella_assignment_sent_at", None):
        cand.umbrella_assignment_sent_at = datetime.datetime.utcnow()

    cand.status = "On Assignment"
    cand.last_activity_at = datetime.datetime.utcnow()

    s.add(CandidateNote(
        candidate_id=cand_id,
        user_email=getattr(current_user, "email", "staff") or "staff",
        note_type="activity",
        content=f"Contract confirmed signed — moved to Placed (source={source}).",
        created_at=datetime.datetime.utcnow(),
    ))

    try:
        log_audit_event(
            "update", "contract",
            f"Contract confirmed signed for {cand.name} (source={source})",
            "candidate", cand_id,
            {
                "esig_id": esig.id,
                "application_id": getattr(latest_app, "id", None),
                "source": source,
            },
        )
    except Exception:
        current_app.logger.exception("contract-signed audit log failed")

    return esig, latest_app


@app.route("/candidate/<int:cand_id>/confirm-contract-signed", methods=["POST"])
@login_required
def confirm_contract_signed(cand_id: int):
    """Req 17 — kanban "Confirm Contract Signed" tick. Routes through
    the shared _apply_contract_signed helper so the same transition
    runs as when the profile Assignment Schedule "Confirm signed"
    button is clicked.

    Req 18 — gated on a SIGNED_CONTRACT Document already being on file.
    The kanban tick is a single-click action with no file picker, so the
    upload happens via the candidate profile. If no signed-contract doc
    exists yet, refuse the transition with a clear message."""
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)

        if not _has_signed_contract_doc(s, cand_id):
            flash(
                "Cannot confirm contract signed — please upload the signed "
                "contract PDF from the candidate profile first.",
                "danger",
            )
            return redirect(request.referrer or url_for("candidate_profile", cand_id=cand_id))

        try:
            _apply_contract_signed(s, cand, source="kanban_confirm_signed")
            s.commit()
        except Exception as exc:
            # Req 18 — surface the underlying failure as a flash message
            # rather than a 500. The user previously hit unhelpful Internal
            # Server Errors here; logs still capture the stack trace.
            s.rollback()
            current_app.logger.exception("confirm_contract_signed failed for cand %s", cand_id)
            flash(f"Could not confirm contract signed: {exc}", "danger")
            return redirect(request.referrer or url_for("candidate_profile", cand_id=cand_id))

    flash("Contract confirmed signed — moved to Placed.", "success")
    return redirect(request.referrer or url_for("workflow"))


def _get_or_create_active_esig(
    s,
    *,
    candidate_id,
    application_id=None,
    engagement_id=None,
    status="pending",
    provider=None,
    end_date=None,
    signed_at=None,
    sent_at=None,
    **_extra,  # tolerate legacy kwargs like signer_email; ignored silently
):
    """Req 19 — return the candidate's existing active ESigRequest, or
    create a new one if none exists. "Active" = not Retracted and not
    Ended (i.e. not yet replaced). This stops Issue Contract / Paystream
    capture / Manual Placement creating sibling ESigRequest rows that
    later both transition to 'signed' and surface as duplicate placement
    rows on /placements.

    Lookup priority:
      1. (candidate_id, application_id) when application_id given
      2. (candidate_id, engagement_id) when engagement_id given
      3. candidate_id alone
    """
    BLOCKING_STATUSES = ("retracted", "ended")
    base = (
        select(ESigRequest)
        .where(ESigRequest.candidate_id == candidate_id)
        .where(func.lower(ESigRequest.status).notin_(BLOCKING_STATUSES))
        .where(ESigRequest.ended_at.is_(None))
        .order_by(ESigRequest.created_at.desc())
    )

    existing = None
    if application_id is not None:
        existing = s.scalars(base.where(ESigRequest.application_id == application_id)).first()
    if not existing and engagement_id is not None:
        existing = s.scalars(base.where(ESigRequest.engagement_id == engagement_id)).first()
    if not existing:
        existing = s.scalars(base).first()

    if existing:
        # Refresh the in-flight fields if the caller asked for new values.
        if status:
            existing.status = status
        if provider:
            existing.provider = provider
        if application_id and not existing.application_id:
            existing.application_id = application_id
        if engagement_id and not existing.engagement_id:
            existing.engagement_id = engagement_id
        if end_date and not existing.end_date:
            existing.end_date = end_date
        if signed_at and not existing.signed_at:
            existing.signed_at = signed_at
        if sent_at and not existing.sent_at:
            existing.sent_at = sent_at
        return existing

    new_esig = ESigRequest(
        candidate_id=candidate_id,
        application_id=application_id,
        engagement_id=engagement_id,
        provider=provider or "signable",
        status=status,
        created_at=datetime.datetime.utcnow(),
        end_date=end_date,
        signed_at=signed_at,
        sent_at=sent_at,
    )
    s.add(new_esig)

    # Reset stale umbrella_assignment_* flags from any previously-ended
    # contract so the Contract card on the candidate profile renders
    # "Awaiting Signature" (or blank) for this new role rather than
    # leaking the previous contract's signed state. end_assignment
    # already clears these on a clean teardown — this catches cases
    # where end_assignment didn't run (e.g. retract_contract, manual
    # status changes) so a brand-new contract always starts fresh.
    cand_for_reset = s.get(Candidate, candidate_id)
    if cand_for_reset:
        if hasattr(cand_for_reset, "umbrella_assignment_sent"):
            cand_for_reset.umbrella_assignment_sent = False
        if hasattr(cand_for_reset, "umbrella_assignment_sent_at"):
            cand_for_reset.umbrella_assignment_sent_at = None
        if hasattr(cand_for_reset, "umbrella_assignment_signed"):
            cand_for_reset.umbrella_assignment_signed = False
        if hasattr(cand_for_reset, "umbrella_assignment_signed_at"):
            cand_for_reset.umbrella_assignment_signed_at = None

    return new_esig

