# -------- E-signature: Signable (signable.co.uk) --------
def _signable_headers():
    """Return auth headers for the Signable REST API."""
    if not SIGNABLE_API_KEY or _requests_lib is None:
        raise RuntimeError("Signable API key or requests library not configured")
    return {
        "Authorization": f"Basic {base64.b64encode((SIGNABLE_API_KEY + ':').encode()).decode()}",
        "Content-Type": "application/json",
        "Accept": "application/json",
    }

def send_esign_signable(appn_id: int, signer_name: str, signer_email: str, subject: str, message: str):
    """Send an envelope via the Signable REST API.

    Signable API docs: https://signable.co.uk/api
    POST /v1/envelopes — creates and sends an envelope with a signing party.
    Returns the envelope fingerprint (their unique ID).
    """
    headers = _signable_headers()
    payload = {
        "envelope_title": subject,
        "envelope_signing_message": message,
        "envelope_parties": [
            {
                "party_name": signer_name,
                "party_email": signer_email,
                "party_role": "signer",
            }
        ],
    }
    # Attach Signable template if configured (get fingerprint from Signable > Templates)
    if SIGNABLE_TEMPLATE_FINGERPRINT:
        payload["envelope_documents"] = [
            {"document_template_fingerprint": SIGNABLE_TEMPLATE_FINGERPRINT}
        ]
    resp = _requests_lib.post(
        f"{SIGNABLE_BASE_URL}/envelopes",
        json=payload,
        headers=headers,
        timeout=30,
    )
    resp.raise_for_status()
    data = resp.json()
    # Signable returns {"envelope_fingerprint": "...", ...}
    return {
        "envelope_id": data.get("envelope_fingerprint") or data.get("id") or str(data),
        "signing_url": data.get("signing_url") or data.get("party_url") or None,
    }

def poll_esign_signable(request_id: str):
    """Poll envelope status from the Signable REST API.

    GET /v1/envelopes/{fingerprint} — returns envelope with current status.
    Signable statuses: 'sent', 'opened', 'signed', 'cancelled', 'expired', 'declined'
    """
    headers = _signable_headers()
    resp = _requests_lib.get(
        f"{SIGNABLE_BASE_URL}/envelopes/{request_id}",
        headers=headers,
        timeout=30,
    )
    resp.raise_for_status()
    data = resp.json()
    raw_status = (data.get("envelope_status") or data.get("status") or "unknown").lower()
    status_map = {
        "sent": "Sent",
        "opened": "Sent",
        "signed": "Signed",
        "completed": "Signed",
        "cancelled": "Declined",
        "expired": "Declined",
        "declined": "Declined",
    }
    return status_map.get(raw_status, raw_status.title())

@app.route("/action/esign/<int:app_id>", methods=["POST"])
@login_required
def action_esign(app_id):
    with Session(engine) as s:
        appn = s.scalar(select(Application).where(Application.id==app_id))
        cand = s.scalar(select(Candidate).where(Candidate.id==appn.candidate_id))
        job = s.scalar(select(Job).where(Job.id==appn.job_id))

        subject = f"Contract — {job.title}"
        message = "Please review and sign your contract."
        try:
            result = send_esign_signable(appn.id, cand.name, cand.email, subject, message)
        except Exception as e:
            flash(f"E-sign send failed: {e}", "danger")
            return redirect(url_for("application_detail", app_id=app_id))

        es = s.scalar(select(ESigRequest).where(ESigRequest.application_id==appn.id))
        if not es:
            es = ESigRequest(application_id=appn.id, provider="signable", request_id=result["envelope_id"], signing_url=result.get("signing_url"), status="Sent", sent_at=datetime.datetime.utcnow())
            s.add(es)
        else:
            es.request_id = result["envelope_id"]
            es.signing_url = result.get("signing_url")
            es.provider = "signable"
            es.status = "Sent"
            es.sent_at = datetime.datetime.utcnow()
        s.commit()
    flash("Contract sent for e-signature", "success")
    return redirect(url_for("application_detail", app_id=app_id))

@app.route("/action/esign_status/<int:app_id>", methods=["POST"])
@login_required
def action_esign_status(app_id):
    with Session(engine) as s:
        es = s.scalar(select(ESigRequest).where(ESigRequest.application_id==app_id))
        if not es:
            flash("No e-sign request found", "warning")
            return redirect(url_for("application_detail", app_id=app_id))
        try:
            status = poll_esign_signable(es.request_id)
        except Exception as e:
            flash(f"E-sign status failed: {e}", "danger")
            return redirect(url_for("application_detail", app_id=app_id))

        es.status = status
        if status == "Signed":
            es.signed_at = datetime.datetime.utcnow()
        s.commit()
    flash(f"E-sign status: {status}", "info")
    return redirect(url_for("application_detail", app_id=app_id))

@csrf.exempt  # External Signable service can't provide a CSRF token
@app.route("/webhook/esign", methods=["GET", "POST"])
def webhook_esign():
    # GET request = Signable URL verification ping
    if request.method == "GET":
        return jsonify({"ok": True, "message": "Webhook endpoint active"}), 200

    # Log EVERY incoming POST before any parsing — some providers send
    # form-encoded or text bodies; we still want evidence of receipt so
    # /admin/webhook-events can show "something arrived but was malformed"
    # rather than nothing at all.
    raw_body = ""
    try:
        raw_body = request.get_data(as_text=True) or ""
    except Exception:
        raw_body = ""
    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        # Fall back to form-encoded bodies; Signable widgets sometimes
        # post that instead of JSON.
        try:
            if request.form:
                payload = request.form.to_dict(flat=True)
            else:
                payload = {}
        except Exception:
            payload = {}

    content_type = request.headers.get("Content-Type", "")
    # Signable uses `action`; JSON fallback may use `event`. Prefer whichever
    # is populated so the admin page shows something meaningful rather than
    # "unknown" for every real delivery.
    event_type_raw = "unknown"
    if isinstance(payload, dict):
        event_type_raw = (
            payload.get("action")
            or payload.get("event")
            or payload.get("envelope_status")
            or "unknown"
        )

    # Persist the diagnostic row in its OWN session so a commit here is
    # durable regardless of what downstream processing does. Without this
    # an exception later on was rolling the inserted row back.
    diag_body = {
        "_meta": {
            "method": request.method,
            "content_type": content_type,
            "remote_addr": request.remote_addr,
            "raw_body_len": len(raw_body),
            "header_count": len(list(request.headers)),
        },
        "payload": payload if isinstance(payload, dict) else {"_raw": raw_body[:4000]},
    }
    try:
        with Session(engine) as _diag_s:
            _diag_s.add(WebhookEvent(
                source="esign",
                event_type=str(event_type_raw),
                payload=json.dumps(diag_body)[:39999],
            ))
            _diag_s.commit()
    except Exception:
        current_app.logger.exception("webhook_esign: failed to persist inbound event")

    # Normalise the real Signable payload (form-encoded; uses `action` not
    # `envelope_status`; `envelope_documents` is a JSON string we must parse
    # to get the document title). Back-fill the keys the rest of the
    # handler expects so older logic keeps working unchanged.
    # fields_list is declared here so it's always in scope for the
    # downstream upsert helper, even if the normalisation branch doesn't
    # execute (e.g. a JSON payload that already has envelope_status set).
    fields_list = None
    if isinstance(payload, dict) and payload.get("action") and not payload.get("envelope_status"):
        action_raw = (payload.get("action") or "").lower()
        action_to_status = {
            "signed-envelope-complete": "completed",
            "envelope-completed": "completed",
            "signed-envelope-partial": "signed",
            "envelope-signed": "signed",
            "cancelled-envelope": "cancelled",
            "envelope-cancelled": "cancelled",
            "declined-envelope": "declined",
            "envelope-declined": "declined",
            "expired-envelope": "expired",
            "envelope-expired": "expired",
        }
        payload["envelope_status"] = action_to_status.get(action_raw, action_raw)

        # envelope_documents may be a JSON string — extract first title.
        docs_raw = payload.get("envelope_documents")
        if isinstance(docs_raw, str) and docs_raw.strip().startswith("["):
            try:
                docs_list = json.loads(docs_raw)
                if isinstance(docs_list, list) and docs_list:
                    payload["envelope_title"] = (docs_list[0].get("document_title") or "").strip()
            except Exception:
                pass
        elif isinstance(docs_raw, list) and docs_raw:
            try:
                payload["envelope_title"] = (docs_raw[0].get("document_title") or "").strip()
            except Exception:
                pass

        # envelope_fields may be a JSON string — scan for a name to use as signer.
        fields_raw = payload.get("envelope_fields")
        fields_list = None
        if isinstance(fields_raw, str) and fields_raw.strip().startswith("["):
            try:
                fields_list = json.loads(fields_raw)
            except Exception:
                fields_list = None
        elif isinstance(fields_raw, list):
            fields_list = fields_raw
        if isinstance(fields_list, list):
            # Find the signer name. Signable forms typically place the
            # Full Name field just before the Signature field, so we scan
            # text fields in REVERSE order and require the value to look
            # like a real person's name — alphabetic words (letters,
            # hyphens, apostrophes), 2+ words, no digits, no stray
            # punctuation. This stops free-text notes like "Test - Yes"
            # from being mistaken for the signer.
            import re as _re
            _name_re = _re.compile(
                r"^[A-Za-z][A-Za-z\-']*( [A-Za-z][A-Za-z\-']*)+$"
            )
            _signer = None
            for f in reversed(fields_list):
                if not isinstance(f, dict):
                    continue
                if (f.get("field_type") or "").lower() != "text":
                    continue
                v = (f.get("field_value") or "").strip()
                if v and _name_re.match(v):
                    _signer = v
                    break
            if _signer:
                payload.setdefault("signer_name", _signer)

    with Session(engine) as s:

        # --- Signable webhook auto-processing ---
        # Signable sends POST with {"envelope_fingerprint": "...", "envelope_status": "signed", ...}
        envelope_fp = payload.get("envelope_fingerprint")
        envelope_status = (payload.get("envelope_status") or "").lower()
        if envelope_fp and envelope_status:
            # Verify webhook secret if configured
            if SIGNABLE_WEBHOOK_SECRET:
                sig_header = request.headers.get("X-Signable-Signature", "")
                import hmac, hashlib
                expected = hmac.new(SIGNABLE_WEBHOOK_SECRET.encode(), request.get_data(), hashlib.sha256).hexdigest()
                if not hmac.compare_digest(sig_header, expected):
                    return jsonify({"error": "Invalid signature"}), 403

            es = s.scalar(select(ESigRequest).where(ESigRequest.request_id == envelope_fp))
            if es:
                status_map = {"sent": "Sent", "opened": "Sent", "signed": "Signed",
                              "completed": "Signed", "cancelled": "Declined",
                              "expired": "Declined", "declined": "Declined"}
                new_status = status_map.get(envelope_status, envelope_status.title())
                es.status = new_status
                if new_status == "Signed":
                    es.signed_at = datetime.datetime.utcnow()
                # Also update candidate esign_status if we can find the candidate
                if es.application_id:
                    appn = s.get(Application, es.application_id)
                    if appn and appn.candidate_id:
                        cand = s.get(Candidate, appn.candidate_id)
                        if cand:
                            cand.esign_status = new_status

                    # REQ G-5 fix: Auto-transition Contract Sent/Issued → Contract Signed when e-sign completed
                    if new_status == "Signed" and appn and appn.status in ("Contract Sent", "Contract Issued"):
                        appn.status = "Contract Signed"
                        # Also update candidate status
                        if appn.candidate_id:
                            cand = s.get(Candidate, appn.candidate_id)
                            if cand:
                                cand.status = "On Contract"
                        try:
                            log_audit_event(
                                'update', 'workflow',
                                f'E-sign webhook: contract signed, auto-moved to Contract Signed',
                                'application', appn.id,
                                {'trigger': 'esign_signed', 'old_status': 'Contract Issued', 'new_status': 'Contract Signed'}
                            )
                        except Exception:
                            pass

            else:
                # Not a known contract — declaration/form signed via Signable widget
                if envelope_status in ("signed", "completed"):
                    # Extract signer email
                    signer_email = ""
                    parties = payload.get("envelope_parties") or []
                    if isinstance(parties, list):
                        for party in parties:
                            if isinstance(party, dict):
                                signer_email = (party.get("party_email") or "").strip().lower()
                                if signer_email:
                                    break
                    if not signer_email:
                        signer_email = (payload.get("signer_email") or payload.get("email") or "").strip().lower()

                    # Identify the document type from envelope title
                    envelope_title = (payload.get("envelope_title") or payload.get("title") or "").strip()
                    title_lower = envelope_title.lower()

                    # Determine document type for activity feed.
                    # ORDER MATTERS: check for "secondary" FIRST, because a
                    # title like "Secondary Employment Declaration" would
                    # otherwise be caught by the generic employment +
                    # declaration rule and mis-labelled as Employment
                    # Reference Declaration.
                    if "paystream" in title_lower and (
                        "assignment" in title_lower or "schedule" in title_lower
                    ):
                        # Paystream umbrella assignment schedule — auto-flip
                        # the candidate's umbrella_assignment_signed flag
                        # below when we can resolve the candidate.
                        doc_label = "Umbrella Assignment (Paystream)"
                        is_emp_ref = False
                    elif "secondary" in title_lower and (
                        "job" in title_lower or "employment" in title_lower
                    ):
                        doc_label = "Secondary Job Declaration"
                        is_emp_ref = False
                    elif (
                        ("employment" in title_lower and (
                            "reference" in title_lower
                            or ("declaration" in title_lower and "secondary" not in title_lower)
                        ))
                        or ("reference" in title_lower and "sign" in title_lower)
                    ):
                        doc_label = "Employment Reference Declaration"
                        is_emp_ref = True
                    elif "consent" in title_lower:
                        doc_label = "Consent Form"
                        is_emp_ref = False
                    elif "declaration" in title_lower:
                        doc_label = "Declaration Form"
                        is_emp_ref = False
                    else:
                        doc_label = envelope_title or "Signable Document"
                        is_emp_ref = False

                    # Try to pull a signer name from parties first, then the
                    # normalised signer_name we derived from envelope_fields,
                    # then as a last resort the tail of the document title
                    # ("... - Ademola Owoeye").
                    signer_name = ""
                    if isinstance(parties, list):
                        for party in parties:
                            if isinstance(party, dict):
                                signer_name = (party.get("party_name") or "").strip()
                                if signer_name:
                                    break
                    if not signer_name:
                        signer_name = (payload.get("signer_name") or "").strip()
                    if not signer_name and " - " in envelope_title:
                        signer_name = envelope_title.rsplit(" - ", 1)[-1].strip()

                    # Find the candidate. Preference order:
                    #   1. envelope_meta carrying a numeric candidate id
                    #      (set by our portal when it renders the widget URL)
                    #   2. email match
                    #   3. exact (case-insensitive) name match
                    # If nothing matches, the signing is logged as
                    # unmatched-widget-signing for later diagnosis.
                    cand = None
                    match_reason = ""
                    envelope_meta_raw = (payload.get("envelope_meta") or "").strip()
                    if envelope_meta_raw.isdigit():
                        try:
                            cand = s.get(Candidate, int(envelope_meta_raw))
                            if cand:
                                match_reason = f"envelope_meta cand_id={envelope_meta_raw}"
                        except Exception:
                            cand = None
                    # Paystream assignment — signer is the umbrella's
                    # contact, not the candidate. Match candidate via
                    # CompanyDetails.contact_email where umbrella contains
                    # "paystream".
                    if (cand is None and signer_email
                            and doc_label == "Umbrella Assignment (Paystream)"):
                        umbrella_row = s.execute(text(
                            "SELECT candidate_id FROM company_details "
                            "WHERE LOWER(contact_email) = :email "
                            "  AND LOWER(contracting_type) = 'umbrella' "
                            "  AND LOWER(COALESCE(umbrella_company_name, '')) LIKE '%paystream%' "
                            "ORDER BY updated_at DESC NULLS LAST LIMIT 1"
                        ).bindparams(email=signer_email.lower())).first()
                        if umbrella_row and umbrella_row.candidate_id:
                            cand = s.get(Candidate, int(umbrella_row.candidate_id))
                            if cand:
                                match_reason = f"paystream contact_email={signer_email}"
                    if cand is None and signer_email:
                        cand = s.scalar(
                            select(Candidate).where(func.lower(Candidate.email) == signer_email)
                        )
                        if cand:
                            match_reason = f"email={signer_email}"
                    ambiguous_ids = []
                    if cand is None and signer_name:
                        # Count all name matches first so two people sharing a
                        # name (e.g. two Alan Smiths) never get silently merged.
                        name_matches = s.scalars(
                            select(Candidate).where(
                                func.lower(Candidate.name) == signer_name.lower()
                            )
                        ).all()
                        if len(name_matches) == 1:
                            cand = name_matches[0]
                            match_reason = f"exact name={signer_name} (unique)"
                        elif len(name_matches) > 1:
                            # Ambiguous — refuse to auto-assign. cand stays
                            # None so we fall through to the unmatched branch;
                            # the breadcrumb below logs all matching ids so
                            # staff can link the signing manually.
                            ambiguous_ids = [c.id for c in name_matches]
                            match_reason = (
                                f"AMBIGUOUS: {len(name_matches)} candidates share "
                                f"name {signer_name!r} (ids={ambiguous_ids})"
                            )

                    # Always drop a WebhookEvent-style breadcrumb saying what
                    # we did (or didn't). Invaluable for diagnosing portal
                    # "still not updated" reports.
                    try:
                        current_app.logger.info(
                            "webhook widget signing | doc=%s | signer_name=%r | signer_email=%r | matched=%s | reason=%s",
                            doc_label, signer_name, signer_email,
                            bool(cand), match_reason or "no match",
                        )
                    except Exception:
                        pass
                    if cand is None:
                        # Record unmatched widget signings so the admin page
                        # can expose them even when no candidate got updated.
                        is_ambiguous = bool(ambiguous_ids)
                        try:
                            with Session(engine) as _ns:
                                _ns.add(WebhookEvent(
                                    source="esign",
                                    event_type=(
                                        "ambiguous-widget-signing"
                                        if is_ambiguous
                                        else "unmatched-widget-signing"
                                    ),
                                    payload=json.dumps({
                                        "doc_label": doc_label,
                                        "envelope_title": envelope_title,
                                        "envelope_fingerprint": envelope_fp,
                                        "signer_name": signer_name,
                                        "signer_email": signer_email,
                                        "match_reason": match_reason,
                                        "ambiguous_candidate_ids": ambiguous_ids,
                                        "hint": (
                                            "Multiple candidates share this name. "
                                            "Use the staff tool on /admin/webhook-events "
                                            "to link this signing to the correct candidate."
                                            if is_ambiguous
                                            else "No Candidate row matched. Check name "
                                                 "spelling in the DB vs Signable field."
                                        ),
                                    })[:39999],
                                ))
                                _ns.commit()
                        except Exception:
                            current_app.logger.exception("failed to log unmatched signing")

                    if cand:
                        # Stash the effective identifier for logging.
                        signer_email = signer_email or f"(matched by name: {signer_name})"
                        # Delegate to the shared helper so the webhook AND the
                        # staff manual-link AND replay all use one upsert path.
                        # The helper handles: emp-ref flag, secondary-job flag,
                        # ConsentRecord upsert, DeclarationRecord upsert +
                        # positional Yes/No dropdown mapping.
                        upsert_outcome = _apply_widget_signing(
                            s, cand, doc_label, signer_name, envelope_fp,
                            ip_address=(request.remote_addr or ""),
                            envelope_fields=fields_list,
                        )

                        # Success breadcrumb — visible on /admin/webhook-events
                        # in its own session so it's durable even if the outer
                        # session's commit later fails.
                        try:
                            with Session(engine) as _ns:
                                _ns.add(WebhookEvent(
                                    source="esign",
                                    event_type="matched-widget-signing",
                                    payload=json.dumps({
                                        "doc_label": doc_label,
                                        "envelope_title": envelope_title,
                                        "envelope_fingerprint": envelope_fp,
                                        "signer_name": signer_name,
                                        "cand_id": cand.id,
                                        "cand_name": cand.name,
                                        "upsert": upsert_outcome,
                                    })[:39999],
                                ))
                                _ns.commit()
                        except Exception:
                            current_app.logger.exception("failed to log matched signing")

                        # Activity note for ALL signed documents
                        s.add(CandidateNote(
                            candidate_id=cand.id,
                            user_email="Signable",
                            note_type="system",
                            content=f"{doc_label} signed via Signable."
                        ))
                        print(f"[Webhook] {doc_label} signed by {signer_email} (candidate {cand.id})")

        s.commit()
    return jsonify({"ok": True})


# ---- Request updated CV ----
@app.route("/action/request_updated_cv/<int:app_id>", methods=["POST"])
@login_required
def action_request_updated_cv(app_id):
    with Session(engine) as s:
        appn = s.scalar(select(Application).where(Application.id==app_id))
        cand = s.scalar(select(Candidate).where(Candidate.id==appn.candidate_id))
        link = f"{APP_BASE_URL}/candidate/{cand.id}/upload_cv"
        html = f"""
        <h3>Request for updated CV</h3>
        <p>Hi {cand.name}, we enjoyed working with you. Please upload an updated CV here:</p>
        <p><a href="{link}">{link}</a></p>
        """
        send_email(cand.email, "Please upload an updated CV", html)
    flash("CV update request sent", "success")
    return redirect(url_for("application_detail", app_id=app_id))

def _compute_verifile_preflight(s, cand_id: int, engagement=None):
    """Per-check-type readiness report for Verifile submission.

    Returns a list of dicts, one per vetting check type relevant to this
    candidate's engagement:
        {
            "check_type": "DBS Check",
            "required_by_engagement": True/False,
            "dbs_level": "Standard" | ...,    # only for DBS Check
            "status": "ok" | "warnings" | "blocked",
            "blocking": [ "Mother's maiden name", ...],
            "warnings": [ "Driving licence expiry date missing", ... ],
            "satisfied": [ "Current address", "NI number", ... ],
        }

    Blocking = missing a field Verifile's API will reject with a
    validation error (money not spent, but the order won't place).
    Warnings = fields that might cause the candidate's Verifile-side
    data-entry step to stall or the check to come back incomplete.
    """
    cand = s.get(Candidate, cand_id)
    if not cand:
        return []

    # Which checks does the engagement require?
    required_types = set()
    if engagement is not None:
        raw = getattr(engagement, "vetting_requirements", "") or ""
        try:
            import json as _j
            parsed = _j.loads(raw) if raw else []
            if isinstance(parsed, list):
                required_types = {str(x) for x in parsed}
        except Exception:
            required_types = set()

    # Pull all portal-side data in one pass.
    from associate_portal import _portal_model as _pm
    AssocProfile = _pm("AssociateProfile")
    AddressHistory = _pm("AddressHistory")
    EmploymentHistory = _pm("EmploymentHistory")
    ConsentRecord = _pm("ConsentRecord")
    QualificationRecord = _pm("QualificationRecord")
    ProfRegistration = _pm("ProfessionalRegistration")

    profile = s.query(AssocProfile).filter_by(candidate_id=cand_id).first() if AssocProfile else None
    addresses = s.query(AddressHistory).filter_by(candidate_id=cand_id).all() if AddressHistory else []
    employments = s.query(EmploymentHistory).filter_by(candidate_id=cand_id).filter_by(is_gap=False).all() if EmploymentHistory else []
    consent = s.query(ConsentRecord).filter_by(candidate_id=cand_id).first() if ConsentRecord else None
    qualifications = s.query(QualificationRecord).filter_by(candidate_id=cand_id).all() if QualificationRecord else []
    prof_regs = s.query(ProfRegistration).filter_by(candidate_id=cand_id).all() if ProfRegistration else []

    # Documents on file.
    rtw_doc_count = s.scalar(text(
        "SELECT COUNT(*) FROM documents WHERE candidate_id = :cid AND doc_type = 'right_to_work'"
    ).bindparams(cid=cand_id)) or 0
    id_doc_count = s.scalar(text(
        "SELECT COUNT(*) FROM documents WHERE candidate_id = :cid AND doc_type = 'proof_of_identity'"
    ).bindparams(cid=cand_id)) or 0
    addr_doc_count = s.scalar(text(
        "SELECT COUNT(*) FROM documents WHERE candidate_id = :cid AND doc_type = 'proof_of_address'"
    ).bindparams(cid=cand_id)) or 0

    # Convenience accessors with sensible defaults.
    def _p(attr, default=""):
        return (getattr(profile, attr, None) if profile else None) or default

    def _nonblank(v):
        return bool((v or "").strip()) if isinstance(v, str) else bool(v)

    # Total continuous address-history days.
    total_addr_days = 0
    if addresses:
        today_ = datetime.date.today()
        for a in addresses:
            fd = getattr(a, "from_date", None)
            td = getattr(a, "to_date", None) or (today_ if getattr(a, "is_current", False) else None)
            if fd and td:
                try:
                    total_addr_days += max(0, (td - fd).days)
                except Exception:
                    pass

    # Total employment-history days (non-gap).
    total_emp_days = 0
    for e in employments:
        fd = getattr(e, "start_date", None)
        td = getattr(e, "end_date", None)
        if fd and td:
            try:
                total_emp_days += max(0, (td - fd).days)
            except Exception:
                pass

    # Job for DBS settings (take the most recent application's job).
    latest_app = s.scalar(
        select(Application).where(Application.candidate_id == cand_id).order_by(Application.created_at.desc())
    )
    latest_job = s.get(Job, latest_app.job_id) if latest_app and latest_app.job_id else None

    # ----- Per-check-type checklists -----
    report = []

    def add(check_type, blocking=None, warnings=None, satisfied=None, extra=None):
        blocking = blocking or []
        warnings = warnings or []
        status = "blocked" if blocking else ("warnings" if warnings else "ok")
        rec = {
            "check_type": check_type,
            "required_by_engagement": (not required_types) or (check_type in required_types),
            "status": status,
            "blocking": blocking,
            "warnings": warnings,
            "satisfied": satisfied or [],
        }
        if extra:
            rec.update(extra)
        report.append(rec)

    # Common candidate-entry minimum
    name_parts = (_p("first_name"), _p("surname"))
    has_name = _nonblank(name_parts[0]) and _nonblank(name_parts[1])
    has_dob = bool(_p("dob", None))
    has_email = _nonblank(getattr(cand, "email", ""))

    # --- Right to Work ---
    blk, wrn, sat = [], [], []
    if not has_name: blk.append("Legal name (first + surname)")
    else: sat.append("Legal name")
    if not has_dob: blk.append("Date of birth")
    else: sat.append("Date of birth")
    if not has_email: blk.append("Candidate email address")
    else: sat.append("Candidate email")
    if rtw_doc_count == 0: wrn.append("No Right to Work document uploaded")
    else: sat.append("Right to Work document on file")
    add("Right to Work", blk, wrn, sat)

    # --- Identity Verification ---
    blk, wrn, sat = [], [], []
    if not has_name: blk.append("Legal name")
    else: sat.append("Legal name")
    if not has_dob: blk.append("Date of birth")
    else: sat.append("Date of birth")
    has_passport = _nonblank(_p("passport_number"))
    has_dl = _nonblank(_p("driving_licence_number"))
    if not has_passport and not has_dl:
        blk.append("Passport OR driving licence number")
    else:
        sat.append("Passport or driving licence")
    if id_doc_count == 0:
        wrn.append("No ID proof document uploaded")
    else:
        sat.append("ID document uploaded")
    add("Identity Verification", blk, wrn, sat)

    # --- Address History ---
    blk, wrn, sat = [], [], []
    if not addresses:
        blk.append("No address history entries in Portal")
    else:
        years = total_addr_days / 365.0
        if years < 5:
            blk.append(f"Only {years:.1f} yrs of address history (need 5)")
        else:
            sat.append(f"{years:.1f} yrs of address history")
    if addr_doc_count == 0:
        wrn.append("No proof of address document uploaded")
    else:
        sat.append("Proof of address uploaded")
    add("Address History", blk, wrn, sat)

    # --- DBS Check ---
    blk, wrn, sat = [], [], []
    if not has_name: blk.append("Legal name")
    if not has_dob: blk.append("Date of birth")
    if not _nonblank(_p("gender")): blk.append("Gender")
    else: sat.append("Gender")
    if not has_passport and not has_dl:
        blk.append("Passport OR driving licence number")
    ni = _nonblank(_p("national_insurance_number"))
    if not ni and not has_passport and not has_dl:
        blk.append("NI number (or passport/licence)")
    elif ni:
        sat.append("NI number")
    if not _nonblank(_p("country_of_birth")):
        blk.append("Country of birth")
    else:
        sat.append("Country of birth")
    if not _nonblank(_p("town_of_birth")):
        blk.append("Town of birth")
    else:
        sat.append("Town of birth")
    if not _nonblank(_p("mother_maiden_name")):
        wrn.append("Mother's maiden name (required for Standard/Enhanced)")
    else:
        sat.append("Mother's maiden name")
    # Job-level DBS fields
    if latest_job is None:
        wrn.append("Candidate has no application — DBS will have no job context")
    else:
        if not _nonblank(getattr(latest_job, "dbs_level", "")):
            blk.append("Job: DBS Level")
        else:
            sat.append(f"Job DBS Level: {latest_job.dbs_level}")
        if not _nonblank(getattr(latest_job, "dbs_sector", "")):
            blk.append("Job: DBS Sector")
        else:
            sat.append(f"Job DBS Sector: {latest_job.dbs_sector}")
        if not _nonblank(getattr(latest_job, "dbs_purpose", "")):
            wrn.append("Job: DBS Purpose of Check")
        if not _nonblank(getattr(latest_job, "dbs_position_applied_for", "")):
            wrn.append("Job: DBS Position Applied For")
        if not _nonblank(getattr(latest_job, "dbs_employer_name", "")):
            wrn.append("Job: DBS Employer Name")
        # Standard/Enhanced only
        if (getattr(latest_job, "dbs_level", "") or "").lower() in ("standard", "enhanced"):
            if not _nonblank(getattr(latest_job, "dbs_job_role", "")):
                blk.append(f"Job: DBS Job Role (required for {latest_job.dbs_level})")
    if total_addr_days < 5 * 365:
        blk.append("DBS requires 5 yrs of address history")
    add("DBS Check", blk, wrn, sat,
        extra={"dbs_level": getattr(latest_job, "dbs_level", "") if latest_job else ""})

    # --- Employment History ---
    blk, wrn, sat = [], [], []
    if not employments:
        blk.append("No employment history entries in Portal")
    else:
        eyrs = total_emp_days / 365.0
        target = (getattr(engagement, "reference_period_years", 3) or 3) if engagement else 3
        if eyrs < target:
            wrn.append(f"Only {eyrs:.1f} yrs employment (engagement wants {target})")
        else:
            sat.append(f"{eyrs:.1f} yrs employment history")
        # Any entry missing referee email?
        missing_ref = sum(1 for e in employments if not _nonblank(getattr(e, "referee_email", "")))
        if missing_ref:
            wrn.append(f"{missing_ref} employment entr{'ies' if missing_ref != 1 else 'y'} missing referee email")
        else:
            sat.append("All employment entries have referee emails")
    add("Employment History", blk, wrn, sat)

    # --- References ---
    blk, wrn, sat = [], [], []
    ref_entries = [e for e in employments if _nonblank(getattr(e, "referee_email", ""))]
    if not ref_entries:
        blk.append("No referee email addresses captured")
    else:
        sat.append(f"{len(ref_entries)} referee contact{'s' if len(ref_entries) != 1 else ''}")
    if consent and getattr(consent, "reference_consent", False):
        sat.append("Reference consent given")
    else:
        wrn.append("Reference consent not confirmed on consent form")
    add("References", blk, wrn, sat)

    # --- Qualifications ---
    blk, wrn, sat = [], [], []
    if not qualifications:
        wrn.append("No qualifications in Portal (skip if not applicable)")
    else:
        sat.append(f"{len(qualifications)} qualification entr{'ies' if len(qualifications) != 1 else 'y'}")
        for q in qualifications:
            if not _nonblank(getattr(q, "institution", "")):
                wrn.append(f"Qualification #{q.id}: institution missing")
            if not _nonblank(getattr(q, "institution_country", "")):
                wrn.append(f"Qualification #{q.id}: institution country missing")
    add("Qualifications", blk, wrn, sat)

    # --- Professional Registration ---
    blk, wrn, sat = [], [], []
    if not prof_regs:
        wrn.append("No professional registrations added (skip if not applicable)")
    else:
        sat.append(f"{len(prof_regs)} registration{'s' if len(prof_regs) != 1 else ''}")
    add("Professional Registration", blk, wrn, sat)

    # --- Credit Check ---
    blk, wrn, sat = [], [], []
    if not has_name: blk.append("Legal name")
    if not has_dob: blk.append("Date of birth")
    if not addresses: blk.append("At least one current address")
    elif total_addr_days < 6 * 365:
        wrn.append(f"Credit check prefers 6 yrs of address history (have {total_addr_days/365:.1f} yrs)")
    else:
        sat.append("6+ yrs of address history")
    add("Credit Check", blk, wrn, sat)

    # --- Directorship / Disqualification ---
    add("Directorship / Disqualification",
        [] if has_name and has_dob else ["Name + DOB"], [], ["Name + DOB"] if has_name and has_dob else [])

    # --- Sanctions / PEP ---
    add("Sanctions / PEP",
        [] if has_name and has_dob else ["Name + DOB"], [], ["Name + DOB"] if has_name and has_dob else [])

    # --- Social Media Review ---
    add("Social Media Review",
        [] if has_name else ["Candidate name"], [], ["Candidate name"] if has_name else [])

    # Filter to engagement-required checks if we know them; otherwise show all.
    if required_types:
        report = [r for r in report if r["check_type"] in required_types]

    return report


@app.route("/candidate/<int:cand_id>/vetting-preflight")
@login_required
def vetting_preflight(cand_id: int):
    """Render the Verifile pre-flight readiness report for a candidate."""
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)
        # Get the engagement via latest application's job
        latest_app = s.scalar(
            select(Application).where(Application.candidate_id == cand_id)
            .order_by(Application.created_at.desc())
        )
        engagement = None
        job = None
        if latest_app and latest_app.job_id:
            job = s.get(Job, latest_app.job_id)
            if job and job.engagement_id:
                engagement = s.get(Engagement, job.engagement_id)

        report = _compute_verifile_preflight(s, cand_id, engagement)

        summary = {
            "total": len(report),
            "ok": sum(1 for r in report if r["status"] == "ok"),
            "warnings": sum(1 for r in report if r["status"] == "warnings"),
            "blocked": sum(1 for r in report if r["status"] == "blocked"),
        }

        return render_template(
            "vetting_preflight.html",
            cand=cand,
            engagement=engagement,
            job=job,
            report=report,
            summary=summary,
        )


@app.route("/candidate/<int:cand_id>")
@login_required
def candidate_profile(cand_id: int):
    """
    Associate Profile page per wireframe requirements.

    Features:
    - Header with name, email, alert banner
    - Notes & Activity Panel (rich-text editor)
    - Profile sidebar (status, location, rate, CV)
    - Tags section with Retag from CV
    - Contract section with Issue Contract button
    - Vetting Checks grid
    - Vetting Progress Summary
    """
    # Optional context passed when arriving from engagement lists
    stage = (request.args.get("stage") or "").strip().lower()
    ctx = {
        "stage": stage or None,
        "job_id": request.args.get("job_id"),
        "job_title": request.args.get("job_title"),
        "interview_at": request.args.get("interview_at"),
    }

    # Req 26 — Employment History (covered by the References flow) and
    # Address History were retired as standalone vetting checks.
    VETTING_CHECK_TYPES = [
        "Right to Work",
        "Identity Verification",
        "DBS Check",
        "References",
        "Qualifications",
        "Professional Registration",
        "Credit Check",
        "Directorship / Disqualification",
        "Sanctions / PEP",
        "Social Media Review",
    ]

    # expire_on_commit=False is critical here: the route does an in-flight
    # commit (cand.status = "On Assignment" auto-link, see below) and then
    # passes `cand` plus several other ORM instances to render_template
    # AFTER the `with` block closes the session. Without this flag, every
    # attribute access in the template would trigger an attribute-refresh
    # against a detached instance and 500 the page with
    # DetachedInstanceError.
    with Session(engine, expire_on_commit=False) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)

        # Prefer the active/placed application over the newest one
        # so that a new application doesn't hide an existing placement
        _active_statuses = ("Placed", "Contract Signed", "Contract Sent", "On Assignment",
                            "Accepted", "Offered", "Ready to Contract")
        latest_app = s.scalar(
            select(Application)
            .where(Application.candidate_id == cand_id, Application.status.in_(_active_statuses))
            .order_by(Application.created_at.desc())
        )
        if not latest_app:
            latest_app = s.scalar(
                select(Application)
                .where(Application.candidate_id == cand_id)
                .order_by(Application.created_at.desc())
            )

        # newest_app: always the most recent application (for interview scheduling)
        newest_app = s.scalar(
            select(Application)
            .where(Application.candidate_id == cand_id)
            .order_by(Application.created_at.desc())
        )

        # interview_app: the app that has an interview scheduled, or newest
        interview_app = None
        _all_apps_for_interview = s.scalars(
            select(Application).where(Application.candidate_id == cand_id)
            .order_by(Application.created_at.desc())
        ).all()
        interview_history = []
        for _ia in _all_apps_for_interview:
            if _ia.interview_scheduled_at:
                if not interview_app:
                    interview_app = _ia
                _ia_job = s.get(Job, _ia.job_id) if _ia.job_id else None
                _ia_eng = s.get(Engagement, _ia_job.engagement_id) if _ia_job and _ia_job.engagement_id else None
                interview_history.append({
                    "role": (_ia_job.title if _ia_job else "") or "Unknown Role",
                    "project": (_ia_eng.name if _ia_eng else "") or "",
                    "scheduled_at": _ia.interview_scheduled_at,
                    "completed_at": _ia.interview_completed_at,
                    "app_id": _ia.id,
                    "is_current": interview_app and _ia.id == interview_app.id,
                    # Req 8 — Teams join URL is populated when the
                    # schedule action used Microsoft Graph (M365_GRAPH_ENABLED=1
                    # and admin consent granted). Falls back to "" for
                    # interviews that went via the legacy .ics path.
                    "teams_join_url": getattr(_ia, "interview_teams_join_url", "") or "",
                    # Req 9 — Pass / Fail / No Show outcome. Per-interview
                    # column on Application; the matching column on
                    # Candidate carries the LATEST interview's outcome
                    # for the resource-pool badge.
                    "outcome_result": getattr(_ia, "optimus_interview_result", "") or "",
                })
        if not interview_app:
            interview_app = newest_app

        job = None
        job_open = False
        applied_on = None
        docs = s.scalars(
            select(Document)
            .where(Document.candidate_id == cand.id)
            .order_by(Document.uploaded_at.desc().nullslast())
        ).all()

        # The staff Documents tile mirrors the 6 categories on the associate
        # portal Documents page (plus CV uploaded via /portal/upload-cv from
        # the Personal Details page). Other doc_types belong to their own
        # tiles and must NOT appear here:
        #   - gap_evidence       -> Employment History timeline
        #   - expense_receipt    -> Timesheet approvals
        #   - consent_signed     -> Declarations / Consent tile
        #   - signed_contract    -> Contract card
        #   - verifile_report    -> Vetting Checks tile
        #   - reference_evidence -> Reference Requests
        #   - hmrc_*             -> Employment History timeline
        PORTAL_DOC_TYPES = {
            "proof_of_identity",
            "proof_of_address",
            "right_to_work",
            "cv",
            "cv_resume",
            "qualifications",
            "other",
        }
        DOC_TYPE_LABELS = {
            "proof_of_identity": "Proof of Identity",
            "proof_of_address": "Proof of Address",
            "right_to_work": "Right to Work",
            "cv": "CV / Resume",
            "cv_resume": "CV / Resume",
            "qualifications": "Qualifications",
            "other": "Other",
        }

        # Build documents_ctx inside session to avoid DetachedInstanceError.
        # Legacy docs with NULL / empty doc_type are treated as CV uploads
        # (the historical default before the column existed) so they still
        # surface in this tile.
        documents_ctx = []
        for d in docs:
            doc_type_raw = (getattr(d, 'doc_type', '') or '').lower()
            doc_type_norm = doc_type_raw or 'cv'
            if doc_type_norm not in PORTAL_DOC_TYPES:
                continue
            documents_ctx.append({
                'id': d.id,
                'name': getattr(d, 'original_name', None) or d.filename or 'Untitled',
                'filename': d.filename,
                'doc_type': doc_type_norm,
                'doc_type_label': DOC_TYPE_LABELS.get(
                    doc_type_norm,
                    doc_type_norm.replace('_', ' ').title(),
                ),
                'ts': d.uploaded_at.strftime('%d %b %Y') if getattr(d, 'uploaded_at', None) else '',
            })

        engagement = None
        if latest_app:
            job = s.scalar(select(Job).where(Job.id == latest_app.job_id))
            job_open = _job_is_open(job)
            applied_on = latest_app.created_at
            if job and job.engagement_id:
                engagement = s.get(Engagement, job.engagement_id)

        # Vetting expiry config (needed for check display below)
        _DEFAULT_EXPIRY = {
            "Right to Work": 12, "Identity Verification": 36,
            "DBS Check": 12, "References": 36,
            "Qualifications": 0, "Professional Registration": 12,
            "Credit Check": 12, "Directorship / Disqualification": 12,
            "Sanctions / PEP": 12, "Social Media Review": 6,
        }
        CHECK_EXPIRY_MONTHS = dict(_DEFAULT_EXPIRY)
        try:
            _ec_row = s.scalar(select(VettingExpiryConfig))
            if _ec_row:
                _db_config = json.loads(_ec_row.config or "{}")
                if isinstance(_db_config, dict):
                    CHECK_EXPIRY_MONTHS.update({k: int(v) for k, v in _db_config.items()})
        except Exception:
            pass

        # Build combined vetting requirements from engagement + job.
        # Req 26 — drop any retired check types still stored in older
        # engagement/job vetting_requirements JSON so they cannot reappear.
        required_vetting_checks = set()
        if engagement and engagement.vetting_requirements:
            required_vetting_checks.update(from_json_safe(engagement.vetting_requirements))
        if job and getattr(job, 'vetting_requirements', None):
            required_vetting_checks.update(from_json_safe(job.vetting_requirements))
        required_vetting_checks = sorted(
            c for c in required_vetting_checks
            if c not in ("Employment History", "Address History")
        )

        # Engagements + roles the candidate has applied to (any status, deduped).
        # The Contract tile selector and "Applied For" panel use only these — a
        # recruiter shouldn't be able to swap to an engagement/role the
        # candidate never engaged with. Terminal statuses are kept in the
        # dropdowns so a previously-withdrawn role can still be re-issued.
        _applied_rows = s.execute(
            select(Application, Job, Engagement)
            .join(Job, Job.id == Application.job_id)
            .outerjoin(Engagement, Engagement.id == Job.engagement_id)
            .where(Application.candidate_id == cand_id)
            .order_by(Application.created_at.desc())
        ).all()

        _seen_eng_ids: list[int] = []
        all_engagements_for_contract = []
        engagement_jobs_map = {}
        cand_applied_apps = []
        _TERMINAL_APP_STATUSES = {"Rejected", "Withdrawn", "Closed", "Hired"}
        for _a, _j, _e in _applied_rows:
            if not _e:
                continue
            if _e.id not in _seen_eng_ids:
                _seen_eng_ids.append(_e.id)
                all_engagements_for_contract.append(_e)
                engagement_jobs_map[_e.id] = []
            if _j and not any(jr["id"] == _j.id for jr in engagement_jobs_map[_e.id]):
                engagement_jobs_map[_e.id].append({"id": _j.id, "title": _j.title})
            if (_a.status or "").strip() not in _TERMINAL_APP_STATUSES:
                cand_applied_apps.append({
                    "id": _a.id,
                    "engagement_id": _e.id,
                    "engagement_name": _e.name or "",
                    "client": _e.client or "",
                    "job_id": _j.id if _j else None,
                    "job_title": (_j.title if _j else "") or "",
                    "status": _a.status or "",
                })

        # Tags data for the sidebar card
        cand_tags = s.scalars(
            select(TaxonomyTag)
            .join(CandidateTag, CandidateTag.tag_id == TaxonomyTag.id)
            .where(CandidateTag.candidate_id == cand.id)
            .order_by(TaxonomyTag.tag.asc())
        ).all()

        cats = s.scalars(
            select(TaxonomyCategory).order_by(TaxonomyCategory.type.asc(), TaxonomyCategory.name.asc())
        ).all()

        tags_by_cat = {
            c.id: s.scalars(
                select(TaxonomyTag).where(TaxonomyTag.category_id == c.id).order_by(TaxonomyTag.tag.asc())
            ).all()
            for c in cats
        }
        
        # === Vetting Checks ===
        vetting_checks = []
        vetting_summary = {"complete": 0, "in_progress": 0, "not_started": 0, "na": 0}

        # Load profile to check for missing data per vetting check
        _profile_data = {}
        try:
            row = s.execute(text(
                "SELECT dob, gender, address_line1, postcode, passport_number, "
                "driving_licence_number FROM associate_profiles WHERE candidate_id = :cid"
            ), {"cid": cand_id}).first()
            if row:
                _profile_data = {
                    "dob": row[0],
                    "gender": row[1] or "",
                    "address_line1": row[2] or "",
                    "postcode": row[3] or "",
                    "passport_number": row[4] or "",
                    "driving_licence_number": row[5] or "",
                }
        except Exception:
            pass

        def _missing_for_check(check_type):
            """Return list of missing data items for this check type."""
            p = _profile_data
            missing = []
            if check_type in ("Identity Verification", "DBS Check"):
                if not p.get("passport_number") and not p.get("driving_licence_number"):
                    missing.append("Passport or Driving Licence number")
                if not p.get("dob"):
                    missing.append("Date of birth")
                if not p.get("gender"):
                    missing.append("Gender")
            if check_type == "DBS Check":
                if not p.get("address_line1"):
                    missing.append("Address")
                if not p.get("postcode"):
                    missing.append("Postcode")
            if check_type == "Right to Work":
                if not p.get("passport_number") and not p.get("driving_licence_number"):
                    missing.append("Passport or Driving Licence number")
            if check_type == "Credit Check":
                if not p.get("address_line1"):
                    missing.append("Address")
                if not p.get("dob"):
                    missing.append("Date of birth")
            if check_type == "Address History":
                if not p.get("address_line1"):
                    missing.append("Current address")
            if check_type == "Sanctions / PEP":
                if not p.get("dob"):
                    missing.append("Date of birth")
            return missing

        try:
            existing_checks = {
                vc.check_type: vc
                for vc in s.scalars(
                    select(VettingCheck).where(VettingCheck.candidate_id == cand_id)
                ).all()
            }
            
            # Build a lookup of user names for QC reviewer / analyst display
            _user_name_cache = {}
            def _get_user_name(uid):
                if not uid:
                    return ""
                if uid not in _user_name_cache:
                    u = s.get(User, uid)
                    _user_name_cache[uid] = u.name if u else f"User #{uid}"
                return _user_name_cache[uid]

            _display_checks = required_vetting_checks if required_vetting_checks else VETTING_CHECK_TYPES
            for check_type in _display_checks:
                if check_type in existing_checks:
                    check = existing_checks[check_type]
                    _completed = check.completed_at
                    _expiry = getattr(check, 'expiry_date', None)
                    if not _expiry and _completed:
                        _exp_months = CHECK_EXPIRY_MONTHS.get(check_type, 0)
                        if _exp_months > 0:
                            _expiry = _completed + datetime.timedelta(days=_exp_months * 30)
                    _expired = bool(_expiry and _expiry < datetime.datetime.utcnow())
                    vetting_checks.append({
                        "id": check.id,
                        "type": check_type,
                        "status": check.status or "NOT STARTED",
                        "notes": check.notes or "",
                        "automation_enabled": getattr(check, 'automation_enabled', True) if check.automation_enabled is not None else True,
                        "assigned_to": check.assigned_to,
                        "assigned_to_name": _get_user_name(check.assigned_to),
                        "qc_assigned_to": getattr(check, 'qc_assigned_to', None),
                        "qc_assigned_to_name": _get_user_name(getattr(check, 'qc_assigned_to', None)),
                        "colour": getattr(check, 'colour', 'white') or 'white',
                        "qc_status": getattr(check, 'qc_status', '') or '',
                        "qc_reviewed_by": check.qc_reviewed_by,
                        "qc_reviewed_by_name": _get_user_name(check.qc_reviewed_by),
                        "qc_reviewed_at": check.qc_reviewed_at,
                        "qc_notes": getattr(check, 'qc_notes', '') or '',
                        "referral_approved_by": check.referral_approved_by,
                        "referral_approved_by_name": _get_user_name(check.referral_approved_by),
                        "referral_approved_at": check.referral_approved_at,
                        "missing_data": _missing_for_check(check_type),
                        "completed_at": _completed,
                        "expiry_date": _expiry,
                        "expired": _expired,
                        "verifile_confirmed": getattr(check, 'verifile_confirmed', False) or False,
                        "verifile_confirmed_at": getattr(check, 'verifile_confirmed_at', None),
                        "verifile_result": getattr(check, 'verifile_result', None) or "",
                        # Req 27 — credit-check address review flag + addresses
                        "credit_address_review": (
                            _verifile_credit_address_review(getattr(check, 'external_result', None))
                            if check_type == "Credit Check" else None
                        ),
                    })
                else:
                    # Create a placeholder for display
                    vetting_checks.append({
                        "id": None,
                        "type": check_type,
                        "status": "NOT STARTED",
                        "notes": "",
                        "automation_enabled": True,
                        "assigned_to": None,
                        "assigned_to_name": "",
                        "qc_assigned_to": None,
                        "qc_assigned_to_name": "",
                        "colour": "white",
                        "qc_status": "",
                        "qc_reviewed_by": None,
                        "qc_reviewed_by_name": "",
                        "qc_reviewed_at": None,
                        "qc_notes": "",
                        "referral_approved_by": None,
                        "referral_approved_by_name": "",
                        "referral_approved_at": None,
                        "missing_data": _missing_for_check(check_type),
                        "credit_address_review": None,
                    })
            
            # Enrich vetting cards with portal-side context so the recruiter
            # can see issues without having to drill into the associate
            # portal. Each key is a VETTING_CHECK_TYPES entry; each value
            # is a list of short flag strings rendered as amber badges.
            portal_flag_map = {}

            def _scalar(sql, **params):
                """Helper: raw SQL scalar with try/except for missing tables."""
                try:
                    return s.scalar(text(sql).bindparams(**params))
                except Exception:
                    return None

            def _add(check_type, msg):
                portal_flag_map.setdefault(check_type, []).append(msg)

            # Employment History — count BOTH explicit gap rows (is_gap=TRUE,
            # added by the candidate to explain a period) AND gaps detected
            # dynamically between consecutive employment entries (>90 days
            # between one role's end_date and the next role's start_date).
            # The associate portal surfaces the dynamic gaps as "Gaps
            # detected in your employment history" — the recruiter should
            # see the same flag on the staff profile.
            emp_gaps = _scalar(
                "SELECT COUNT(*) FROM employment_history "
                "WHERE candidate_id = :cid AND is_gap = TRUE",
                cid=cand_id,
            ) or 0
            # Detect dynamic gaps between consecutive non-gap entries.
            try:
                emp_rows = s.execute(
                    text(
                        "SELECT start_date, end_date FROM employment_history "
                        "WHERE candidate_id = :cid AND is_gap = FALSE "
                        "AND start_date IS NOT NULL AND end_date IS NOT NULL "
                        "ORDER BY start_date ASC"
                    ).bindparams(cid=cand_id)
                ).all()
                detected_gaps = 0
                for i in range(len(emp_rows) - 1):
                    prev_end = emp_rows[i].end_date
                    next_start = emp_rows[i + 1].start_date
                    if prev_end and next_start:
                        try:
                            if (next_start - prev_end).days > 90:
                                detected_gaps += 1
                        except Exception:
                            pass
                if detected_gaps:
                    emp_gaps += detected_gaps
            except Exception:
                pass
            if emp_gaps:
                _add("Employment History",
                     f"{emp_gaps} gap{'s' if emp_gaps != 1 else ''} flagged")
            emp_total = _scalar(
                "SELECT COUNT(*) FROM employment_history "
                "WHERE candidate_id = :cid AND is_gap = FALSE",
                cid=cand_id,
            ) or 0
            emp_no_email = _scalar(
                "SELECT COUNT(*) FROM employment_history "
                "WHERE candidate_id = :cid AND is_gap = FALSE "
                "AND (referee_email IS NULL OR referee_email = '')",
                cid=cand_id,
            ) or 0
            if emp_total == 0:
                _add("Employment History", "No employment entries in Portal")
            elif emp_no_email:
                _add("Employment History",
                     f"{emp_no_email} entr{'ies' if emp_no_email != 1 else 'y'} missing referee email")

            # References — flagged if no referee emails AND declaration flags
            # referencing issues OR dismissal.
            ref_count = _scalar(
                "SELECT COUNT(*) FROM employment_history "
                "WHERE candidate_id = :cid AND is_gap = FALSE "
                "AND referee_email IS NOT NULL AND referee_email <> ''",
                cid=cand_id,
            ) or 0
            if ref_count == 0:
                _add("References", "No referees provided in Portal")

            # Qualifications.
            qual_count = _scalar(
                "SELECT COUNT(*) FROM qualification_records "
                "WHERE candidate_id = :cid",
                cid=cand_id,
            ) or 0
            if qual_count == 0:
                _add("Qualifications", "No qualifications added in Portal")

            # Professional Registration.
            prof_count = _scalar(
                "SELECT COUNT(*) FROM professional_registrations "
                "WHERE candidate_id = :cid",
                cid=cand_id,
            ) or 0
            if prof_count == 0:
                _add("Professional Registration",
                     "No professional registrations added in Portal")

            # Address History — flag under 3 years total coverage.
            try:
                addr_rows = s.execute(
                    text(
                        "SELECT from_date, to_date, is_current FROM address_history "
                        "WHERE candidate_id = :cid"
                    ).bindparams(cid=cand_id)
                ).all()
                addr_total_days = 0
                today_ = datetime.date.today()
                for r in addr_rows:
                    fd = getattr(r, "from_date", None)
                    td = getattr(r, "to_date", None)
                    if getattr(r, "is_current", False) and not td:
                        td = today_
                    if fd and td:
                        try:
                            addr_total_days += max(0, (td - fd).days)
                        except Exception:
                            pass
                if addr_rows and addr_total_days < 3 * 365:
                    years = addr_total_days / 365.0
                    _add("Address History",
                         f"Only {years:.1f} yrs covered in Portal (need 3)")
                elif not addr_rows:
                    _add("Address History",
                         "No address history in Portal")
            except Exception:
                pass

            # Identity Verification — need a passport OR driving licence.
            passport_num = _scalar(
                "SELECT passport_number FROM associate_profiles "
                "WHERE candidate_id = :cid", cid=cand_id,
            ) or ""
            dl_num = _scalar(
                "SELECT driving_licence_number FROM associate_profiles "
                "WHERE candidate_id = :cid", cid=cand_id,
            ) or ""
            if not passport_num and not dl_num:
                _add("Identity Verification",
                     "Neither passport nor driving licence on Portal profile")

            # Right to Work — flag if no RTW document uploaded.
            rtw_doc = _scalar(
                "SELECT COUNT(*) FROM documents "
                "WHERE candidate_id = :cid AND doc_type = 'right_to_work'",
                cid=cand_id,
            ) or 0
            if rtw_doc == 0:
                _add("Right to Work", "No Right to Work document uploaded")

            # DBS Check — DBS requires specific bio fields on the profile.
            ni_num = _scalar(
                "SELECT national_insurance_number FROM associate_profiles "
                "WHERE candidate_id = :cid", cid=cand_id,
            ) or ""
            cob = _scalar(
                "SELECT country_of_birth FROM associate_profiles "
                "WHERE candidate_id = :cid", cid=cand_id,
            ) or ""
            tob = _scalar(
                "SELECT town_of_birth FROM associate_profiles "
                "WHERE candidate_id = :cid", cid=cand_id,
            ) or ""
            missing_dbs = []
            if not ni_num:
                missing_dbs.append("NI number")
            if not cob:
                missing_dbs.append("country of birth")
            if not tob:
                missing_dbs.append("town of birth")
            if missing_dbs:
                _add("DBS Check",
                     "Missing for DBS: " + ", ".join(missing_dbs))

            # DeclarationRecord answers → flag the relevant check cards.
            try:
                decl_row = s.execute(
                    text(
                        "SELECT work_restrictions, criminal_convictions, ccj_debt, "
                        "bankruptcy, dismissed, referencing_issues "
                        "FROM declaration_records WHERE candidate_id = :cid"
                    ).bindparams(cid=cand_id)
                ).first()
                if decl_row:
                    if getattr(decl_row, "work_restrictions", False):
                        _add("Right to Work",
                             "Candidate declared work restrictions")
                    if getattr(decl_row, "criminal_convictions", False):
                        _add("DBS Check",
                             "Candidate declared unspent convictions")
                    if getattr(decl_row, "ccj_debt", False):
                        _add("Credit Check",
                             "Candidate declared CCJ / debt relief order")
                    if getattr(decl_row, "bankruptcy", False):
                        _add("Credit Check",
                             "Candidate declared bankruptcy / IVA")
                    if getattr(decl_row, "dismissed", False):
                        _add("References",
                             "Candidate declared prior dismissal")
                    if getattr(decl_row, "referencing_issues", False):
                        _add("References",
                             "Candidate declared referencing issues")
            except Exception:
                pass

            # Apply all collected flags to the matching vetting cards.
            for vc in vetting_checks:
                flags = portal_flag_map.get(vc.get("type"))
                if flags:
                    vc["portal_flags"] = flags

            # Calculate summary
            for vc in vetting_checks:
                status = (vc["status"] or "").upper()
                if status in ("COMPLETE", "QC COMPLETE", "QC NOT REQUIRED", "REFERRAL APPROVED", "CHECK STILL IN DATE"):
                    vetting_summary["complete"] += 1
                elif status in ("IN PROGRESS", "AWAITING QC", "SENT TO QC", "QC IN PROGRESS", "QC REWORK NEEDED", "AWAIT QC REWORK CHECK"):
                    vetting_summary["in_progress"] += 1
                elif status == "N/A":
                    vetting_summary["na"] += 1
                else:
                    vetting_summary["not_started"] += 1
        except Exception as _vc_exc:
            print(f"[VETTING-ERROR] cand={cand_id}: {_vc_exc}", flush=True)
            import traceback; traceback.print_exc()
            for check_type in _display_checks:
                vetting_checks.append({
                    "id": None,
                    "type": check_type,
                    "status": "NOT STARTED",
                    "notes": "",
                })
                vetting_summary["not_started"] += 1
        
        # === Notes & Activity ===
        # General Notes (user-added only, not auto-logged activities)
        candidate_notes = []
        try:
            candidate_notes = s.scalars(
                select(CandidateNote)
                .where(CandidateNote.candidate_id == cand_id)
                .where(CandidateNote.note_type == "note")
                .order_by(CandidateNote.created_at.desc())
                .limit(50)
            ).all()
        except Exception:
            pass

        # === Contracting entity (from associate portal /portal/company-details) ===
        company_details = None
        try:
            from associate_portal import _portal_model
            CompanyDetailsCls = _portal_model("CompanyDetails")
            if CompanyDetailsCls is not None:
                company_details = s.scalar(
                    select(CompanyDetailsCls).where(CompanyDetailsCls.candidate_id == cand_id)
                )
        except Exception:
            company_details = None
        # Raw-SQL fallback — partial ORM init can leave CompanyDetails
        # unresolvable on some Gunicorn workers.
        if company_details is None:
            try:
                _cd_row = s.execute(text(
                    "SELECT id, candidate_id, contracting_type, company_name, "
                    "       registration_number, vat_registered, vat_number, "
                    "       bank_account_number, bank_sort_code, "
                    "       umbrella_company_name, contact_email, updated_at "
                    "FROM company_details WHERE candidate_id = :cid"
                ).bindparams(cid=cand_id)).first()
                if _cd_row:
                    company_details = type("CD", (), {
                        col: getattr(_cd_row, col, None)
                        for col in (
                            "id", "candidate_id", "contracting_type",
                            "company_name", "registration_number",
                            "vat_registered", "vat_number",
                            "bank_account_number", "bank_sort_code",
                            "umbrella_company_name", "contact_email",
                            "updated_at",
                        )
                    })()
            except Exception:
                pass
        
        # === Consent & Declaration records (from portal) ===
        consent_record = None
        declaration_record = None
        try:
            from associate_portal import _portal_model
            _ConsentCls = _portal_model("ConsentRecord")
            if _ConsentCls:
                consent_record = s.scalar(select(_ConsentCls).where(_ConsentCls.candidate_id == cand_id))
            _DeclCls = _portal_model("DeclarationRecord")
            if _DeclCls:
                declaration_record = s.scalar(select(_DeclCls).where(_DeclCls.candidate_id == cand_id))
        except Exception:
            pass
        if consent_record is None:
            try:
                _cr = s.execute(text("SELECT consent_given, signed_date, legal_name, reference_consent, secondary_employment, secondary_employment_details FROM consent_records WHERE candidate_id = :cid").bindparams(cid=cand_id)).first()
                if _cr:
                    consent_record = type("CR", (), {"consent_given": _cr[0], "signed_date": _cr[1], "legal_name": _cr[2], "reference_consent": _cr[3], "secondary_employment": _cr[4], "secondary_employment_details": _cr[5] or ""})()
            except Exception:
                pass
        if declaration_record is None:
            try:
                _dr = s.execute(text("SELECT signed_date, legal_name, work_restrictions, work_restrictions_detail, criminal_convictions, criminal_convictions_detail, ccj_debt, ccj_debt_detail, bankruptcy, bankruptcy_detail, dismissed, dismissed_detail, referencing_issues, referencing_issues_detail FROM declaration_records WHERE candidate_id = :cid").bindparams(cid=cand_id)).first()
                if _dr:
                    declaration_record = type("DR", (), {"signed_date": _dr[0], "legal_name": _dr[1], "work_restrictions": _dr[2], "work_restrictions_detail": _dr[3] or "", "criminal_convictions": _dr[4], "criminal_convictions_detail": _dr[5] or "", "ccj_debt": _dr[6], "ccj_debt_detail": _dr[7] or "", "bankruptcy": _dr[8], "bankruptcy_detail": _dr[9] or "", "dismissed": _dr[10], "dismissed_detail": _dr[11] or "", "referencing_issues": _dr[12], "referencing_issues_detail": _dr[13] or ""})()
            except Exception:
                pass

        # === Employment History Timeline (for Declarations tile) ===
        emp_timeline = []
        try:
            _emp_rows = s.execute(text(
                "SELECT company_name, job_title, start_date, end_date, is_gap, gap_reason, "
                "permission_to_request, permission_delay_reason, gap_evidence_doc_id "
                "FROM employment_history WHERE candidate_id = :cid ORDER BY start_date DESC"
            ).bindparams(cid=cand_id)).all()

            _gap_doc_ids = [int(r[8]) for r in _emp_rows if r[8]]
            _gap_docs = {}
            if _gap_doc_ids:
                try:
                    for d in s.scalars(select(Document).where(Document.id.in_(_gap_doc_ids))).all():
                        _gap_docs[d.id] = {
                            "id": d.id,
                            "original_name": getattr(d, "original_name", "") or getattr(d, "filename", "") or "evidence",
                        }
                except Exception:
                    pass

            for _er in _emp_rows:
                ev = _gap_docs.get(int(_er[8])) if _er[8] else None
                emp_timeline.append({
                    "company": _er[0] or "",
                    "role": _er[1] or "",
                    "start_date": _er[2],
                    "end_date": _er[3],
                    "is_gap": bool(_er[4]),
                    "gap_reason": _er[5] or "",
                    "can_contact": bool(_er[6]) if _er[6] is not None else True,
                    "no_contact_reason": _er[7] or "",
                    "gap_evidence": ev,
                })
        except Exception:
            pass

        # === Employment History (from portal) ===
        employment_history = []
        try:
            from associate_portal import _ensure_models, _portal_model
            _ensure_models()
            EmpHistory = _portal_model("EmploymentHistory")
            if EmpHistory:
                emp_entries = s.scalars(
                    select(EmpHistory).where(EmpHistory.candidate_id == cand_id)
                    .order_by(EmpHistory.start_date.desc())
                ).all()
                for emp in emp_entries:
                    employment_history.append({
                        "company_name": getattr(emp, 'company_name', '') or '',
                        "job_title": getattr(emp, 'job_title', '') or '',
                        "start_date": emp.start_date,
                        "end_date": emp.end_date,
                        "is_gap": getattr(emp, 'is_gap', False),
                        "gap_reason": getattr(emp, 'gap_reason', '') or '',
                        "referee_email": getattr(emp, 'referee_email', '') or '',
                        "permission_to_request": getattr(emp, 'permission_to_request', True),
                        "permission_delay_reason": getattr(emp, 'permission_delay_reason', '') or '',
                    })
        except Exception:
            pass

        # === Reference Requests ===
        reference_requests = []
        try:
            reference_requests = [
                {
                    "id": rr.id,
                    "company_name": rr.company_name or "",
                    "referee_email": rr.referee_email or "",
                    "referee_name": rr.referee_name or "",
                    "status": rr.status or "not_sent",
                    "sent_at": rr.sent_at,
                    "chase_count": rr.chase_count or 0,
                    "colour": rr.colour or "white",
                    "permission_status": rr.permission_status or "yes",
                    "notes": rr.notes or "",
                }
                for rr in s.scalars(
                    select(ReferenceRequest)
                    .where(ReferenceRequest.candidate_id == cand_id)
                    .order_by(ReferenceRequest.created_at.desc())
                ).all()
            ]
        except Exception:
            pass

        # === Req 22 — Referencing timeline (chronological employment + gaps) ===
        # Builds the per-row data the rebuilt References tile renders:
        # for non-gap rows it carries both Company Email and Agency Email with
        # the ✓ / 🚩 / ✗ badge each gets, plus the linked ReferenceRequest if
        # one exists. Gap rows expose their reason + evidence doc.
        ref_timeline = []
        try:
            from associate_portal import _ensure_models, _portal_model
            _ensure_models()
            EmpHistory = _portal_model("EmploymentHistory")
            if EmpHistory:
                emp_rows = s.scalars(
                    select(EmpHistory).where(EmpHistory.candidate_id == cand_id)
                    .order_by(EmpHistory.start_date.asc())
                ).all()

                ref_by_emp_id = {}
                for rr in s.scalars(
                    select(ReferenceRequest)
                    .where(ReferenceRequest.candidate_id == cand_id)
                ).all():
                    if rr.employment_history_id:
                        ref_by_emp_id[rr.employment_history_id] = rr

                def _fmt_d(d):
                    if not d:
                        return ""
                    try:
                        return d.strftime("%d/%b/%Y")
                    except Exception:
                        return str(d)

                for emp in emp_rows:
                    start_d = getattr(emp, "start_date", None)
                    end_d = getattr(emp, "end_date", None)
                    start_label = _fmt_d(start_d)
                    end_label = _fmt_d(end_d) or ("Present" if start_d else "")
                    # Kept as the legacy single-line string for any caller
                    # that still wants the inline rendering. The template
                    # uses start_label / end_label so the cell can stack
                    # the two values one on top of the other and keep the
                    # Date Range column narrow.
                    date_range = (
                        f"{start_label} – {end_label}" if start_label else end_label
                    )
                    if getattr(emp, "is_gap", False):
                        ref_timeline.append({
                            "kind": "gap",
                            "emp_id": emp.id,
                            "date_range": date_range,
                            "start_label": start_label,
                            "end_label": end_label,
                            "gap_reason": getattr(emp, "gap_reason", "") or "",
                            "gap_evidence_doc_id": getattr(emp, "gap_evidence_doc_id", None),
                        })
                        continue

                    company_name = getattr(emp, "company_name", "") or ""
                    agency_name = getattr(emp, "agency_name", "") or ""
                    company_email = (
                        getattr(emp, "company_email", "") or ""
                    ) or (getattr(emp, "referee_email", "") or "")
                    agency_email = getattr(emp, "agency_email", "") or ""

                    company_badge = _classify_reference_email(
                        s, company_email, company_name=company_name, agency_name=None
                    ) if company_email else "missing"
                    agency_badge = _classify_reference_email(
                        s, agency_email, company_name=None, agency_name=agency_name
                    ) if agency_email else "missing"

                    rr = ref_by_emp_id.get(emp.id)
                    ref_dict = None
                    if rr:
                        ref_dict = {
                            "id": rr.id,
                            "status": rr.status or "not_sent",
                            "sent_at": rr.sent_at,
                            "recipient_type": rr.recipient_type or "",
                            "agreed_at": rr.agreed_at,
                            "reply_doc_id": rr.reply_doc_id,
                            "referee_email": rr.referee_email or "",
                            "colour": rr.colour or "white",
                        }

                    ref_timeline.append({
                        "kind": "employment",
                        "emp_id": emp.id,
                        "date_range": date_range,
                        "start_label": start_label,
                        "end_label": end_label,
                        "job_title": getattr(emp, "job_title", "") or "",
                        "company_name": company_name,
                        "company_email": company_email,
                        "company_badge": company_badge,
                        "agency_name": agency_name,
                        "agency_email": agency_email,
                        "agency_badge": agency_badge,
                        "ref": ref_dict,
                    })
        except Exception:
            current_app.logger.exception("ref_timeline build failed for cand=%s", cand_id)

        # === Contract Status ===
        # Only the most recent NON-ended ESigRequest drives the live Contract
        # card. Ended placements are surfaced separately via previous_placement
        # so the Contract card can reset to "no contract" once an assignment
        # has been ended.
        contract_status = None
        esig_request = None
        try:
            esig_request = s.scalar(
                select(ESigRequest)
                .where(ESigRequest.candidate_id == cand_id)
                .where(ESigRequest.ended_at.is_(None))
                .where(func.lower(ESigRequest.status) != "ended")
                .order_by(ESigRequest.created_at.desc())
            )
            if esig_request:
                contract_status = esig_request.status
        except Exception:
            pass

        # === Previous Contract (most recent ended placement) ===
        previous_placement = None
        try:
            row = s.execute(
                select(ESigRequest, Job, Engagement)
                .select_from(ESigRequest)
                .outerjoin(Application, Application.id == ESigRequest.application_id)
                .outerjoin(Job, Job.id == Application.job_id)
                .outerjoin(Engagement, Engagement.id == ESigRequest.engagement_id)
                .where(ESigRequest.candidate_id == cand_id)
                .where(ESigRequest.ended_at.isnot(None))
                .order_by(ESigRequest.ended_at.desc())
            ).first()
            if row:
                _esig, _job, _eng = row
                previous_placement = {
                    "id": _esig.id,
                    "application_id": _esig.application_id,
                    "client": (_eng.client if _eng else None),
                    "engagement_name": (_eng.name if _eng else None),
                    "role": (_job.title if _job else None),
                    "ended_at": _esig.ended_at,
                    "end_reason": _esig.end_reason,
                    "end_notes": _esig.end_notes,
                    "assignment_sent_at": _esig.assignment_sent_at,
                    "assignment_signed": bool(_esig.assignment_signed),
                    "assignment_signed_at": _esig.assignment_signed_at,
                }
        except Exception:
            pass
        
        # Check if there are any active applications (for alert banner)
        active_apps_count = s.scalar(
            select(func.count(Application.id))
            .where(Application.candidate_id == cand_id)
            .where(Application.status.notin_(["Rejected", "Hired", "Contract Signed"]))
        ) or 0

        # All applications for this candidate, joined to Job + Engagement, used by
        # the "Current Applications" tile + nav anchor on the profile page.
        _cand_apps_rows = s.execute(
            select(Application, Job, Engagement)
            .join(Job, Job.id == Application.job_id)
            .outerjoin(Engagement, Engagement.id == Job.engagement_id)
            .where(Application.candidate_id == cand_id)
            .order_by(Application.created_at.desc())
        ).all()
        cand_apps = [
            {
                "id": a.id,
                "job_title": (j.title if j else "") or "",
                "engagement_name": (e.name if e else "") or "",
                "client": (e.client if e else "") or "",
                "status": a.status or "",
                "created_at": a.created_at,
            }
            for a, j, e in _cand_apps_rows
        ]

        # === Placements History (Active and Historic) ===
        placements_active = []
        placements_historic = []
        try:
            # Only fetch ESigRequests with signed/completed/sent status (actual placements)
            all_contracts = s.execute(
                select(ESigRequest, Job, Engagement)
                .select_from(ESigRequest)
                .outerjoin(Application, Application.id == ESigRequest.application_id)
                .outerjoin(Job, Job.id == Application.job_id)
                .outerjoin(Engagement, Engagement.id == ESigRequest.engagement_id)
                .where(ESigRequest.candidate_id == cand_id)
                .where(ESigRequest.status.in_(["signed", "Signed", "completed", "Completed", "sent", "Sent"]))
                .order_by(ESigRequest.signed_at.desc())
            ).all()
            
            today = datetime.date.today()
            for esig, job_obj, eng in all_contracts:
                placement = {
                    'id': esig.id,
                    'engagement_name': eng.name if eng else (job_obj.title if job_obj else 'Unknown'),
                    'engagement_id': eng.id if eng else None,
                    'client': eng.client if eng else 'Unknown',
                    'role': job_obj.title if job_obj else 'N/A',
                    'start_date': eng.start_date if eng else None,
                    'end_date': eng.end_date if eng else None,
                    'status': esig.status,
                    'signed_at': esig.signed_at,
                }
                
                # Determine if active or historic based on end dates and status
                is_active = False
                esig_status_lower = (esig.status or "").lower()
                if esig_status_lower in ("signed", "completed"):
                    if eng and eng.end_date:
                        try:
                            end_dt = eng.end_date if isinstance(eng.end_date, datetime.date) else datetime.datetime.strptime(str(eng.end_date), '%Y-%m-%d').date()
                            is_active = end_dt >= today
                        except Exception:
                            is_active = True
                    elif esig.end_date:
                        try:
                            end_dt = esig.end_date.date() if isinstance(esig.end_date, datetime.datetime) else esig.end_date
                            is_active = end_dt >= today
                        except Exception:
                            is_active = True
                    else:
                        is_active = True
                placement['is_active'] = is_active
                if is_active:
                    placements_active.append(placement)
                else:
                    placements_historic.append(placement)
        except Exception:
            pass

        # === Auto-link status to "On Assignment" if active signed placement exists ===
        if placements_active and (cand.status or "Available") not in ("5", "Do Not Contact", "Do Not Use", "DNU"):
            if cand.status != "On Assignment":
                cand.status = "On Assignment"
                s.commit()

        # === Activity Feed (structured activity log) ===
        activity_feed = []
        try:
            # Get applications (with status changes)
            apps = s.execute(
                select(Application, Job)
                .join(Job, Job.id == Application.job_id)
                .where(Application.candidate_id == cand_id)
                .order_by(Application.created_at.desc())
                .limit(20)
            ).all()
            
            for app, job_obj in apps:
                activity_feed.append({
                    'type': 'application',
                    'icon': 'fa-file-alt',
                    'color': '#3b82f6',
                    'title': f'Applied for {job_obj.title}',
                    'timestamp': app.created_at,
                    'details': f'Status: {app.status}'
                })
                if app.interview_scheduled_at:
                    activity_feed.append({
                        'type': 'interview_scheduled',
                        'icon': 'fa-calendar-check',
                        'color': '#f59e0b',
                        'title': 'Interview Scheduled',
                        'timestamp': app.interview_scheduled_at,
                        'details': f'For {job_obj.title}'
                    })
                if app.interview_completed_at:
                    activity_feed.append({
                        'type': 'interview_completed',
                        'icon': 'fa-check-circle',
                        'color': '#10b981',
                        'title': 'Interview Completed',
                        'timestamp': app.interview_completed_at,
                        'details': f'For {job_obj.title}'
                    })
            
            # Get contract events
            contracts = s.scalars(
                select(ESigRequest)
                .where(ESigRequest.candidate_id == cand_id)
                .order_by(ESigRequest.created_at.desc())
                .limit(10)
            ).all()
            
            for contract in contracts:
                if contract.sent_at:
                    activity_feed.append({
                        'type': 'contract_sent',
                        'icon': 'fa-paper-plane',
                        'color': '#8b5cf6',
                        'title': 'Contract Issued',
                        'timestamp': contract.sent_at,
                        'details': f'Provider: {contract.provider or "N/A"}'
                    })
                if contract.signed_at:
                    activity_feed.append({
                        'type': 'contract_signed',
                        'icon': 'fa-file-signature',
                        'color': '#059669',
                        'title': 'Contract Signed',
                        'timestamp': contract.signed_at,
                        'details': f'Status: {contract.status}'
                    })
            
            # Get workflow stage change notes (activity type)
            stage_notes = s.scalars(
                select(CandidateNote)
                .where(CandidateNote.candidate_id == cand_id)
                .where(CandidateNote.note_type == "activity")
                .order_by(CandidateNote.created_at.desc())
                .limit(20)
            ).all()

            for note in stage_notes:
                activity_feed.append({
                    'type': 'status',
                    'icon': 'fa-exchange-alt',
                    'color': '#8b5cf6',
                    'title': 'Stage Change',
                    'timestamp': note.created_at,
                    'details': (note.content[:150] + '...') if note.content and len(note.content) > 150 else (note.content or '')
                })

            # AI score events (one per CV upload / apply / rescore)
            score_notes = s.scalars(
                select(CandidateNote)
                .where(CandidateNote.candidate_id == cand_id)
                .where(CandidateNote.note_type == "ai_score")
                .order_by(CandidateNote.created_at.desc())
                .limit(20)
            ).all()
            for note in score_notes:
                content = note.content or ""
                # Format: "AI Match Score: NN/100 — Job Title (Engagement)"
                title = "AI Match Score Calculated"
                details = content
                if " — " in content:
                    score_part, label_part = content.split(" — ", 1)
                    title = score_part  # e.g. "AI Match Score: 90/100"
                    details = label_part
                activity_feed.append({
                    'type': 'assessment',
                    'icon': 'fa-robot',
                    'color': '#0ea5e9',
                    'title': title,
                    'timestamp': note.created_at,
                    'details': details,
                })

            # Applicant Portal activity — every _add_note() call from the
            # associate portal writes with user_email="associate-portal".
            # Surface those in the staff-side feed so actions the candidate
            # takes (company details, personal details, documents, signing,
            # apply/withdraw, etc.) are visible here.
            portal_notes = s.scalars(
                select(CandidateNote)
                .where(CandidateNote.candidate_id == cand_id)
                .where(CandidateNote.user_email == "associate-portal")
                .order_by(CandidateNote.created_at.desc())
                .limit(40)
            ).all()
            for note in portal_notes:
                content = (note.content or "").strip()
                if not content:
                    continue
                activity_feed.append({
                    'type': 'note',
                    'icon': 'fa-user-edit',
                    'color': '#0891b2',
                    'title': 'Applicant Portal',
                    'timestamp': note.created_at,
                    'details': content[:300],
                })

            # Sort by timestamp descending
            activity_feed.sort(key=lambda x: x['timestamp'] if x['timestamp'] else datetime.datetime.min, reverse=True)
            activity_feed = activity_feed[:30]  # Limit to 30 most recent
        except Exception:
            pass

    # Build variables for candidate_profile.html template
    # documents_ctx is built inside the session block above to avoid DetachedInstanceError

    # Combine active + historic placements for template
    all_placements = placements_active + placements_historic

    # Build activity items for the template's activity feed
    # The template expects objects with: type, title, description, created_at
    activities = []
    for af in activity_feed:
        activities.append(type('Activity', (), {
            'type': af.get('type', 'note'),
            'title': af.get('title', ''),
            'description': af.get('details', ''),
            'created_at': af.get('timestamp'),
        })())

    # Vetting grouped by project/role — collapsible within the Vetting Checks section
    # Load vetting expiry config from DB (fallback to defaults if not configured)
    vetting_by_project = []
    try:
        with Session(engine) as _svh:
            _cand_apps = _svh.execute(
                select(Application.id, Application.status, Application.created_at.label("app_created"),
                       Job.title, Job.id.label("job_id"),
                       Engagement.id.label("eng_id"), Engagement.name.label("eng_name"),
                       Engagement.client, Engagement.vetting_requirements)
                .select_from(Application)
                .join(Job, Job.id == Application.job_id)
                .outerjoin(Engagement, Engagement.id == Job.engagement_id)
                .where(Application.candidate_id == cand_id)
                .order_by(Application.created_at.desc())
            ).all()

            _all_vc = _svh.scalars(
                select(VettingCheck).where(VettingCheck.candidate_id == cand_id)
            ).all()
            _vc_map = {}
            for vc in _all_vc:
                completed = vc.completed_at
                expiry = getattr(vc, "expiry_date", None)
                if not expiry and completed:
                    months = CHECK_EXPIRY_MONTHS.get(vc.check_type, 12)
                    if months > 0:
                        expiry = completed + datetime.timedelta(days=months * 30)
                _vc_map[vc.check_type] = {
                    "id": vc.id,
                    "status": vc.status or "NOT STARTED",
                    "completed_at": completed,
                    "expiry_date": expiry,
                    "assigned_to": vc.assigned_to,
                    "qc_assigned_to": vc.qc_assigned_to,
                    "qc_reviewed_by_name": "",
                    "qc_reviewed_at": vc.qc_reviewed_at,
                    "qc_notes": vc.qc_notes or "",
                    "colour": vc.colour or "white",
                    "verifile_confirmed": getattr(vc, "verifile_confirmed", False) or False,
                    "verifile_confirmed_at": getattr(vc, "verifile_confirmed_at", None),
                    "verifile_result": getattr(vc, "verifile_result", None) or "",
                }

            _seen_eng = set()
            _now = datetime.datetime.utcnow()
            for idx, _ca in enumerate(_cand_apps):
                eng_key = _ca.eng_id or f"job_{_ca.job_id}"
                if eng_key in _seen_eng:
                    continue
                _seen_eng.add(eng_key)
                required = from_json_safe(_ca.vetting_requirements or "[]")
                if not required:
                    continue
                is_latest = (idx == 0)
                checks_detail = []
                for check_type in required:
                    vc_data = _vc_map.get(check_type, {})
                    completed = vc_data.get("completed_at")
                    expiry = vc_data.get("expiry_date")
                    expired = bool(expiry and expiry < _now)
                    still_in_date = bool(not is_latest and completed and expiry and not expired)
                    prev_in_date = False
                    if is_latest and completed and expiry and not expired:
                        prev_in_date = True
                    checks_detail.append({
                        "type": check_type,
                        "status": vc_data.get("status", "NOT STARTED"),
                        "completed_at": completed,
                        "expiry_date": expiry,
                        "expired": expired,
                        "prev_in_date": prev_in_date,
                        "colour": vc_data.get("colour", "white"),
                        "assigned_to": vc_data.get("assigned_to"),
                        "qc_assigned_to": vc_data.get("qc_assigned_to"),
                        "verifile_confirmed": vc_data.get("verifile_confirmed", False),
                        "verifile_confirmed_at": vc_data.get("verifile_confirmed_at"),
                        "verifile_result": vc_data.get("verifile_result", ""),
                    })
                vetting_by_project.append({
                    "eng_id": _ca.eng_id,
                    "eng_name": _ca.eng_name or "No Project",
                    "client": _ca.client or "",
                    "role": _ca.title or "Unknown Role",
                    "app_status": _ca.status or "",
                    "is_latest": is_latest,
                    "checks": checks_detail,
                    "total": len(checks_detail),
                    "complete": sum(1 for c in checks_detail if c["status"].upper() in ("COMPLETE", "QC COMPLETE", "N/A", "QC NOT REQUIRED", "CHECK STILL IN DATE")),
                    "in_progress": sum(1 for c in checks_detail if c["status"].upper() in ("IN PROGRESS", "SENT TO QC", "QC IN PROGRESS", "AWAITING QC", "QC REWORK NEEDED")),
                })
    except Exception:
        pass

    # Staff users for analyst assignment dropdown (QC workflow)
    all_staff_users = []
    # Jobs for Match to Job / quick shortlist
    jobs_for_quick_pick = []
    try:
        with Session(engine) as s2:
            all_staff_users = [
                {"id": u.id, "name": u.name}
                for u in s2.scalars(
                    select(User).where(User.is_active == True).order_by(User.name)
                ).all()
            ]
            jobs_for_quick_pick = s2.scalars(
                select(Job).where(Job.title.isnot(None), Job.title != "").order_by(Job.title)
            ).all()
    except Exception:
        pass

    return render_template(
        "candidate_profile.html",
        appn=latest_app,            # can be None
        latest_app=latest_app,
        interview_app=interview_app,
        interview_history=interview_history,
        cand=cand,
        job=job,
        docs=docs,
        documents_ctx=documents_ctx,
        trust=None,
        esig=esig_request,
        interview_form=None,
        job_open=job_open,
        applied_on=applied_on,
        from_candidate=True,
        ai_summary=cand.ai_summary or "",
        skills=cand.skills or "",

        # taxonomy/tag data
        cand_tags=cand_tags,
        cats=cats,
        tags_by_cat=tags_by_cat,

        # engagement/list context for banner in template
        engagement=engagement,
        all_engagements_for_contract=all_engagements_for_contract,
        engagement_jobs_map=engagement_jobs_map,
        cand_applied_apps=cand_applied_apps,
        context=ctx if ctx.get("stage") else None,

        # === New wireframe data ===
        vetting_checks=vetting_checks,
        vetting_summary=vetting_summary,
        candidate_notes=candidate_notes,
        company_details=company_details,
        consent_record=consent_record,
        declaration_record=declaration_record,
        emp_timeline=emp_timeline,
        contract_status=contract_status,
        previous_placement=previous_placement,
        today_iso=datetime.date.today().isoformat(),
        active_apps_count=active_apps_count,
        cand_apps=cand_apps,
        VETTING_CHECK_TYPES=VETTING_CHECK_TYPES,
        required_vetting_checks=required_vetting_checks,
        vetting_by_project=vetting_by_project,
        current_vetting_project=next((p for p in vetting_by_project if p.get("is_latest")), None),
        # === QC workflow: staff users for analyst dropdown ===
        all_staff_users=all_staff_users,
        jobs_for_quick_pick=jobs_for_quick_pick,
        # === Activity Feed & Placements ===
        activity_feed=activity_feed,
        activities=activities,
        placements=all_placements,
        placements_active=placements_active,
        placements_historic=placements_historic,
        # Reference requests for preview/send
        reference_requests=reference_requests,
        ref_timeline=ref_timeline,
        # Req-027: Active engagements for manual placement creation
        active_engagements=s.scalars(
            select(Engagement).where(Engagement.status == "Active").order_by(Engagement.name)
        ).all(),
    )

# -------- Req-027: Manual Placement Creation --------
@app.route("/candidate/<int:cand_id>/create-placement", methods=["POST"])
@login_required
def create_manual_placement(cand_id):
    """Create a placement manually when contracts are handled offline."""
    engagement_id = request.form.get("engagement_id", type=int)
    role_title = request.form.get("role_title", "").strip()
    start_date_str = request.form.get("start_date", "").strip()
    end_date_str = request.form.get("end_date", "").strip()

    if not engagement_id:
        flash("Please select an engagement for this placement.", "error")
        return redirect(request.referrer or url_for("candidate_profile", cand_id=cand_id))

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        eng = s.get(Engagement, engagement_id)
        if not cand or not eng:
            flash("Candidate or engagement not found.", "error")
            return redirect(request.referrer or url_for("candidate_profile", cand_id=cand_id))

        # Get or create ESigRequest representing the manual placement
        # (Req 19 — never duplicate active ESigRequests for the same
        # candidate+engagement; the placements list joins on this row).
        esig = _get_or_create_active_esig(
            s,
            candidate_id=cand_id,
            engagement_id=engagement_id,
            provider="manual",
            status="completed",
            signer_email=cand.email or "",
            signed_at=datetime.datetime.utcnow(),
        )

        # Update candidate status
        cand.status = "On Assignment"

        log_audit_event(
            'create', 'placement',
            f'Manual placement created for {cand.name} on {eng.name}',
            'candidate', cand_id,
            {'engagement_id': engagement_id, 'role': role_title}
        )

        s.commit()
        flash(f"Placement created for {cand.name} on {eng.name}.", "success")

    return redirect(url_for("candidate_profile", cand_id=cand_id))


# -------- Add a single vetting check to a candidate --------
@app.route("/candidate/<int:cand_id>/add-vetting-check", methods=["POST"])
@login_required
def candidate_add_vetting_check(cand_id: int):
    """Add a new VettingCheck row for a candidate (only if it doesn't already exist)."""
    check_type = request.form.get("check_type", "").strip()
    ALL_VETTING_CHECKS = [
        "Right to Work", "Identity Verification", "DBS Check",
        "References", "Qualifications", "Professional Registration",
        "Credit Check", "Directorship / Disqualification", "Sanctions / PEP", "Social Media Review"
    ]
    if not check_type or check_type not in ALL_VETTING_CHECKS:
        flash("Invalid check type.", "warning")
        return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-vetting")
    with Session(engine) as s:
        existing = s.scalar(
            select(VettingCheck)
            .where(VettingCheck.candidate_id == cand_id, VettingCheck.check_type == check_type)
        )
        if not existing:
            s.add(VettingCheck(candidate_id=cand_id, check_type=check_type, status="NOT STARTED"))
            s.commit()
            flash(f"'{check_type}' check added.", "success")
        else:
            flash(f"'{check_type}' check already exists.", "info")
    return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-vetting")


# -------- Vetting Check Update --------
@app.route("/candidate/<int:cand_id>/vetting", methods=["POST"])
@login_required
def update_vetting_check(cand_id: int):
    """
    Update a vetting check status for a candidate.
    
    GAP 7.1 FIX: When all vetting checks are Complete or N/A, 
    auto-moves candidate to next workflow stage.
    GAP X.4: Audit trail for compliance-sensitive changes.
    """
    check_type = request.form.get("check_type", "").strip()
    new_status = request.form.get("status", "NOT STARTED")
    notes = request.form.get("notes", "")
    
    # Redirect back to referring page, anchored to vetting section
    referrer = request.referrer or url_for("candidate_profile", cand_id=cand_id)
    # Append #sec-vetting anchor so page scrolls back to the vetting section
    if "#" not in referrer:
        redirect_url = referrer + "#sec-vetting"
    else:
        redirect_url = referrer

    if not check_type:
        flash("Invalid vetting check type", "error")
        return redirect(redirect_url)
    
    # All vetting check types
    ALL_VETTING_CHECKS = [
        "Right to Work", "Identity Verification", "DBS Check",
        "References", "Qualifications", "Professional Registration",
        "Credit Check", "Directorship / Disqualification", "Sanctions / PEP", "Social Media Review"
    ]
    
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        old_status_value = None
        
        # Check if this vetting check already exists
        existing = s.scalar(
            select(VettingCheck)
            .where(VettingCheck.candidate_id == cand_id)
            .where(VettingCheck.check_type == check_type)
        )
        
        if existing:
            old_status_value = existing.status
            nu = new_status.upper()

            # QC gate: cannot mark as COMPLETE unless QC has been done or user is QC reviewer
            is_qc_check = existing.qc_assigned_to and current_user.is_authenticated and existing.qc_assigned_to == current_user.id
            if nu == "COMPLETE" and not is_qc_check and (existing.status or "").upper() not in ("QC COMPLETE", "QC NOT REQUIRED", "CHECK STILL IN DATE"):
                flash(f"{check_type}: cannot mark as Complete — must go through QC first.", "danger")
                return redirect(redirect_url)

            # Role-based status validation (non-admins only)
            user_role = getattr(current_user, "role", "") or ""
            is_admin = user_role == "admin"
            is_assignee = existing.assigned_to and current_user.is_authenticated and existing.assigned_to == current_user.id
            is_qc = existing.qc_assigned_to and current_user.is_authenticated and existing.qc_assigned_to == current_user.id

            ASSIGNEE_STATUSES = {"NOT STARTED", "IN PROGRESS", "SENT TO QC", "CHECK STILL IN DATE", "N/A"}
            QC_STATUSES = {"QC IN PROGRESS", "QC REWORK NEEDED", "QC COMPLETE", "QC NOT REQUIRED", "COMPLETE"}

            if not is_admin:
                if is_assignee and not is_qc and nu not in ASSIGNEE_STATUSES:
                    flash(f"{check_type}: as the assignee you can only set: {', '.join(sorted(ASSIGNEE_STATUSES))}.", "danger")
                    return redirect(redirect_url)
                if is_qc and not is_assignee and nu not in QC_STATUSES:
                    flash(f"{check_type}: as the QC reviewer you can only set QC statuses.", "danger")
                    return redirect(redirect_url)

            existing.status = new_status
            existing.notes = notes
            if nu in ("COMPLETE", "CHECK STILL IN DATE"):
                existing.completed_at = existing.completed_at or datetime.datetime.utcnow()
        else:
            new_check = VettingCheck(
                candidate_id=cand_id,
                check_type=check_type,
                status=new_status,
                notes=notes,
                completed_at=datetime.datetime.utcnow() if new_status.upper() == "COMPLETE" else None
            )
            s.add(new_check)
        
        # GAP X.4: Audit log for vetting changes (compliance critical)
        log_audit_event(
            'update', 'vetting',
            f'Vetting check "{check_type}" updated to "{new_status}"',
            'candidate', cand_id,
            {'check_type': check_type, 'old_status': old_status_value, 'new_status': new_status, 'notes': notes}
        )
        
        s.commit()
        
        # GAP 7.1: Check if all vetting is now complete
        all_checks = s.execute(
            select(VettingCheck)
            .where(VettingCheck.candidate_id == cand_id)
        ).scalars().all()
        
        check_statuses = {vc.check_type: vc.status.upper() for vc in all_checks}
        
        # Count completed checks (COMPLETE, N/A, or REFERRAL APPROVED are considered done)
        completed_count = sum(1 for ct in ALL_VETTING_CHECKS
                            if check_statuses.get(ct, "NOT STARTED") in ["COMPLETE", "N/A", "REFERRAL APPROVED", "QC COMPLETE"])
        
        all_vetting_complete = completed_count == len(ALL_VETTING_CHECKS)
        
        if all_vetting_complete:
            # Find the candidate's active application in Vetting In-Flight stage
            active_app = s.scalar(
                select(Application)
                .where(Application.candidate_id == cand_id)
                .where(Application.status == "Vetting In-Flight")
                .order_by(Application.created_at.desc())
            )
            
            if active_app:
                # Auto-move to Contract Issued (GAP 1.2 auto-trigger)
                # C-8: Default stage name — update if workflow stages are reconfigured
                active_app.status = "Contract Issued"
                cand.status = "In Vetting"  # Keep as In Vetting until contract signed
                cand.previously_vetted = True
                
                log_audit_event(
                    'update', 'workflow',
                    f'Auto-triggered: All vetting complete, moved to Contract Issued',
                    'application', active_app.id,
                    {'trigger': 'vetting_complete', 'new_status': 'Contract Issued'}
                )
                
                s.commit()
                flash(f"All vetting complete! {cand.name} has been moved to 'Contract Issued' stage.", "success")
                return redirect(redirect_url)

    flash(f"Vetting check '{check_type}' updated to '{new_status}'", "success")
    return redirect(redirect_url)


# -------- REQ-269: Manual Vetting Entry Fallback --------
@app.route("/candidate/<int:cand_id>/vetting-manual", methods=["POST"])
@login_required
def manual_vetting_entry(cand_id: int):
    """REQ-269: Manual vetting data entry fallback when Verifile API unavailable."""
    check_type = request.form.get("check_type", "").strip()
    status = request.form.get("status", "COMPLETE")
    result_text = request.form.get("result_text", "").strip()
    reference_number = request.form.get("reference_number", "").strip()
    completed_date = request.form.get("completed_date", "").strip()
    notes = request.form.get("notes", "").strip()

    redirect_url = request.referrer or url_for("candidate_profile", cand_id=cand_id)

    if not check_type:
        flash("Check type is required.", "danger")
        return redirect(redirect_url)

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            abort(404)

        existing = s.scalar(
            select(VettingCheck)
            .where(VettingCheck.candidate_id == cand_id)
            .where(VettingCheck.check_type == check_type)
        )

        completed_dt = None
        if completed_date:
            try:
                completed_dt = datetime.datetime.strptime(completed_date, "%Y-%m-%d")
            except ValueError:
                pass

        manual_result = json.dumps({
            "source": "manual_entry",
            "result_text": result_text,
            "reference_number": reference_number,
            "entered_by": current_user.email if current_user and hasattr(current_user, 'email') else "system",
            "entered_at": datetime.datetime.utcnow().isoformat(),
        })

        if existing:
            existing.status = status
            existing.notes = notes
            existing.external_provider = ""
            existing.external_result = manual_result
            existing.external_ref = reference_number
            if completed_dt:
                existing.completed_at = completed_dt
            elif status.upper() == "COMPLETE":
                existing.completed_at = datetime.datetime.utcnow()
        else:
            new_check = VettingCheck(
                candidate_id=cand_id,
                check_type=check_type,
                status=status,
                notes=notes,
                external_provider="",
                external_result=manual_result,
                external_ref=reference_number,
                automation_enabled=False,
                completed_at=completed_dt or (datetime.datetime.utcnow() if status.upper() == "COMPLETE" else None),
            )
            s.add(new_check)

        s.commit()

        try:
            log_audit_event(
                'create', 'vetting',
                f'Manual vetting entry: {check_type} = {status} for candidate {cand_id}',
                'candidate', cand_id,
                {'check_type': check_type, 'status': status, 'source': 'manual_entry'}
            )
        except Exception:
            pass

    flash(f"Manual vetting entry saved: {check_type} → {status}", "success")
    return redirect(redirect_url)


# =========================================================================
# CONTRADICTION FIX 1: Auto-create vetting checks when candidate added to project
# Status stays "WAITING FOR ASSOCIATE" until Start Vetting button is pressed.
# =========================================================================

ALL_VETTING_CHECK_TYPES = [
    "Right to Work", "Identity Verification", "DBS Check",
    "References", "Qualifications", "Professional Registration",
    "Credit Check", "Directorship / Disqualification", "Sanctions / PEP", "Social Media Review"
]

def _auto_create_vetting_checks(session, candidate_id: int, engagement_id: int = None):
    """
    Auto-create the VettingCheck records for a candidate with status
    'WAITING FOR ASSOCIATE'. These remain dormant until the 'Start Vetting'
    button is pressed by staff, which changes status to 'NOT STARTED' and
    triggers the API calls and emails.
    If engagement has specific vetting_requirements, only create those checks.
    """
    # Determine which checks to create
    checks_to_create = list(ALL_VETTING_CHECK_TYPES)
    if engagement_id:
        try:
            eng = session.get(Engagement, engagement_id)
            if eng and eng.vetting_requirements:
                required = json.loads(eng.vetting_requirements)
                if required:  # Only filter if non-empty list
                    checks_to_create = [c for c in ALL_VETTING_CHECK_TYPES if c in required]
        except Exception:
            pass

    # Don't duplicate existing checks
    existing_types = set(
        r[0] for r in session.execute(
            select(VettingCheck.check_type).where(VettingCheck.candidate_id == candidate_id)
        ).all()
    )

    created = 0
    for ct in checks_to_create:
        if ct not in existing_types:
            session.add(VettingCheck(
                candidate_id=candidate_id,
                check_type=ct,
                status="WAITING FOR ASSOCIATE"
            ))
            created += 1
    return created


def _auto_trigger_vetting(session, candidate_id: int, job_id: int = None):
    """
    Auto-trigger vetting for a candidate when they reach Accepted stage.
    Sets all WAITING FOR ASSOCIATE / NOT STARTED checks to In Progress.
    Updates application to Vetting In-Flight and candidate to In Vetting.
    """
    # Get engagement ID from job if available
    engagement_id = None
    if job_id:
        job = session.get(Job, job_id)
        if job:
            engagement_id = job.engagement_id

    # Ensure checks exist first
    _auto_create_vetting_checks(session, candidate_id, engagement_id)

    # Trigger: move all WAITING/NOT STARTED checks to In Progress
    checks = session.scalars(
        select(VettingCheck).where(VettingCheck.candidate_id == candidate_id)
    ).all()
    triggered = 0
    for vc in checks:
        if (vc.status or "").upper() in ("WAITING FOR ASSOCIATE", "NOT STARTED", ""):
            vc.status = "In Progress"
            triggered += 1

    # Update application status
    active_app = session.scalar(
        select(Application)
        .where(Application.candidate_id == candidate_id)
        .where(Application.status == "Accepted")
        .order_by(Application.created_at.desc())
    )
    if active_app:
        active_app.status = "Vetting In-Flight"

    # Update candidate status
    cand = session.get(Candidate, candidate_id)
    if cand:
        cand.status = "In Vetting"

    try:
        log_audit_event('update', 'vetting',
                       f'Auto-triggered vetting at Accepted stage ({triggered} checks)',
                       'candidate', candidate_id,
                       {'trigger': 'auto_accepted', 'checks_triggered': triggered})
    except Exception:
        pass

    return triggered


# =========================================================================
# GAP PLAN: VETTING START EMAIL (Batch 2.2)
# =========================================================================

@app.route("/action/start-vetting/<int:cand_id>", methods=["POST"])
@login_required
def start_vetting(cand_id: int):
    """
    Batch 2.2: Send vetting start email to candidate when vetting is triggered.
    Creates initial VettingCheck records for all check types.
    """
    ALL_VETTING_CHECKS = [
        "Right to Work", "Identity Verification", "DBS Check",
        "References", "Qualifications", "Professional Registration",
        "Credit Check", "Directorship / Disqualification", "Sanctions / PEP", "Social Media Review"
    ]
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            flash("Associate not found.", "danger")
            return redirect(url_for("workflow"))

        # Create vetting checks if they don't exist
        existing_types = set(
            r[0] for r in s.execute(
                select(VettingCheck.check_type).where(VettingCheck.candidate_id == cand_id)
            ).all()
        )
        created = 0
        for ct in ALL_VETTING_CHECKS:
            if ct not in existing_types:
                s.add(VettingCheck(candidate_id=cand_id, check_type=ct, status="NOT STARTED"))
                created += 1

        # Send email notification to candidate using the vetting_commencement template
        if cand.email:
            try:
                # Load vetting_commencement email template from DB
                vetting_tpl = s.scalar(
                    select(EmailTemplate).where(EmailTemplate.name == "vetting_commencement")
                )
                associate_name = cand.name or 'Associate'
                if vetting_tpl:
                    email_subject = (vetting_tpl.subject or "Optimus \u2013 Commencement of Vetting").replace("{associate_name}", associate_name)
                    email_body_text = (vetting_tpl.body or "").replace("{associate_name}", associate_name)
                    # Convert plain text to HTML (preserve line breaks and structure)
                    import html as _html_mod
                    html_body = "<div style='font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6;'>"
                    html_body += _html_mod.escape(email_body_text).replace("\n\n", "</p><p>").replace("\n", "<br>")
                    html_body += "</div>"
                    html_body = f"<p>{html_body}</p>"
                else:
                    # Fallback if template somehow missing
                    base_url = os.getenv("APP_BASE_URL", "http://localhost:5001")
                    email_subject = "Optimus \u2013 Commencement of Vetting"
                    html_body = f"""
                    <h2>Vetting Process Started</h2>
                    <p>Dear {associate_name},</p>
                    <p>Your pre-employment vetting process has been initiated. Please log in to the
                    Associate Portal to complete the required steps.</p>
                    <p><a href="{base_url}/portal/dashboard">Log in to the Portal</a></p>
                    <p>If you have any questions, please contact the Optimus compliance team
                    at compliance@optimussolutions.co.uk.</p>
                    <p>Regards,<br>Optimus Compliance Team</p>
                    """
                send_email(cand.email, email_subject, html_body)
                flash(f"Vetting started and email sent to {cand.email}.", "success")
            except Exception as e:
                flash(f"Vetting started but email failed: {str(e)}", "warning")
        else:
            flash(f"Vetting started ({created} checks created). No email — associate has no email address.", "warning")

        log_audit_event('create', 'vetting',
                        f'Vetting started for {cand.name} ({created} checks created)',
                        'candidate', cand_id,
                        {'checks_created': created, 'email_sent': bool(cand.email)})
        s.commit()

    return redirect(url_for("candidate_profile", cand_id=cand_id))


