@app.route("/action/mark-all-qc-complete/<int:cand_id>", methods=["POST"])
@login_required
def mark_all_qc_complete(cand_id: int):
    """Req 46 — bulk-flip every vetting check on a candidate to
    QC COMPLETE so the user doesn't have to save 12 dropdowns one at a
    time. Audit-logged so we can see who did it.
    """
    print(
        f"[QC_BULK] called user_id={getattr(current_user, 'id', None)} "
        f"role={getattr(current_user, 'role', None)} cand_id={cand_id}",
        flush=True,
    )
    SKIP_STATUSES = {"QC COMPLETE", "QC NOT REQUIRED", "COMPLETE",
                     "N/A", "CHECK STILL IN DATE"}
    try:
        with Session(engine) as s:
            cand = s.get(Candidate, cand_id)
            if not cand:
                flash(f"Candidate #{cand_id} not found.", "danger")
                return redirect(url_for("index"))

            checks = s.scalars(
                select(VettingCheck).where(VettingCheck.candidate_id == cand_id)
            ).all()

            flipped = 0
            skipped = 0
            skipped_breakdown = {}
            for vc in checks:
                current = (vc.status or "").upper().strip()
                if current in SKIP_STATUSES:
                    skipped += 1
                    skipped_breakdown[current] = skipped_breakdown.get(current, 0) + 1
                    continue
                vc.status = "QC COMPLETE"
                vc.qc_status = "qc_approved"
                if not vc.completed_at:
                    vc.completed_at = datetime.datetime.utcnow()
                flipped += 1

            if flipped:
                s.add(CandidateNote(
                    candidate_id=cand_id,
                    user_email=getattr(current_user, "email", "staff") or "staff",
                    note_type="activity",
                    content=f"Bulk Mark QC Complete — {flipped} check(s) flipped.",
                    created_at=datetime.datetime.utcnow(),
                ))
                try:
                    log_audit_event(
                        "update", "vetting",
                        f"Bulk Mark QC Complete: {flipped} checks for candidate #{cand_id}",
                        "candidate", cand_id,
                        {"flipped": flipped, "skipped": skipped},
                    )
                except Exception:
                    current_app.logger.exception("mark_all_qc_complete audit log failed")

            s.commit()

            print(
                f"[QC_BULK] done cand_id={cand_id} total={len(checks)} "
                f"flipped={flipped} skipped={skipped} breakdown={skipped_breakdown}",
                flush=True,
            )

            if not checks:
                flash(
                    f"No vetting checks exist on candidate #{cand_id} — nothing to mark. "
                    f"Use 'Start Full Vetting' first.",
                    "warning",
                )
            elif flipped:
                flash(
                    f"✅ Marked {flipped} check{'s' if flipped != 1 else ''} as QC Complete."
                    + (f" {skipped} already in a terminal state." if skipped else ""),
                    "success",
                )
            else:
                # All checks already in a terminal state — explain why nothing happened.
                breakdown = ", ".join(f"{n}× {st}" for st, n in skipped_breakdown.items())
                flash(
                    f"No changes — all {skipped} check(s) are already in a terminal state ({breakdown}).",
                    "info",
                )
    except Exception as exc:
        import traceback as _tb
        print(
            f"[QC_BULK] FAILED cand_id={cand_id} {type(exc).__name__}: {exc}\n"
            + _tb.format_exc(),
            flush=True,
        )
        flash(f"Mark QC Complete failed: {type(exc).__name__}: {exc}", "danger")

    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/action/assign-qc-reviewer-bulk/<int:cand_id>", methods=["POST"])
@login_required
def assign_qc_reviewer_bulk(cand_id: int):
    """Assign one QC reviewer to ALL vetting checks for a candidate."""
    reviewer_id = request.form.get("reviewer_id", type=int)

    with Session(engine) as s:
        checks = s.scalars(
            select(VettingCheck).where(VettingCheck.candidate_id == cand_id)
        ).all()

        reviewer_name = "Unassigned"
        if reviewer_id:
            reviewer = s.get(User, reviewer_id)
            reviewer_name = reviewer.name if reviewer else f"User #{reviewer_id}"

        for vc in checks:
            vc.qc_assigned_to = reviewer_id

        log_audit_event('update', 'vetting',
                        f'Bulk QC assign: all checks for candidate #{cand_id} assigned to {reviewer_name}',
                        'candidate', cand_id,
                        {'reviewer_id': reviewer_id, 'checks_updated': len(checks)})
        s.commit()
        flash(f"All vetting checks QC assigned to {reviewer_name}.", "success")

    return redirect(url_for("candidate_profile", cand_id=cand_id))

