@app.route("/action/preview-reference/<int:cand_id>/<int:ref_id>", methods=["GET"])
@login_required
def preview_reference_email(cand_id: int, ref_id: int):
    """Return JSON with the rendered reference request email for preview/edit before sending."""
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        ref_req = s.get(ReferenceRequest, ref_id)
        if not cand or not ref_req or ref_req.candidate_id != cand_id:
            return jsonify({"error": "Not found"}), 404

        merge_fields = {
            "candidate_name": cand.name or "",
            "company_name": ref_req.company_name or "",
            "referee_name": ref_req.referee_name or "Sir/Madam",
            "job_title": "",
            "start_date": "",
            "end_date": "",
        }
        if ref_req.employment_history_id:
            try:
                from associate_portal import _ensure_models, _portal_model
                _ensure_models()
                EmpHistory = _portal_model("EmploymentHistory")
                if EmpHistory:
                    emp = s.get(EmpHistory, ref_req.employment_history_id)
                    if emp:
                        merge_fields["job_title"] = getattr(emp, "job_title", "") or ""
                        sd = getattr(emp, "start_date", None)
                        ed = getattr(emp, "end_date", None)
                        if sd:
                            merge_fields["start_date"] = sd.strftime("%d/%m/%Y") if hasattr(sd, "strftime") else str(sd)
                        if ed:
                            merge_fields["end_date"] = ed.strftime("%d/%m/%Y") if hasattr(ed, "strftime") else str(ed)
            except Exception:
                pass

        email_tpl = s.scalar(select(EmailTemplate).where(EmailTemplate.name == "reference_request"))
        if email_tpl:
            subject = email_tpl.subject
            body = email_tpl.body
        else:
            subject = "Reference Request — {candidate_name}"
            body = """<h2>Reference Request</h2>
<p>Dear {referee_name},</p>
<p>We are writing to request a reference for <strong>{candidate_name}</strong>
who has listed your organisation (<strong>{company_name}</strong>) as a
previous employer.</p>
<p>Please could you confirm the following:</p>
<ul>
    <li>Dates of employment</li>
    <li>Job title / role</li>
    <li>Reason for leaving</li>
    <li>Any other relevant information</li>
</ul>
<p>Please reply directly to this email with the reference details.</p>
<p>The candidate's signed consent form is attached for your records.</p>
<p>Thank you for your assistance.</p>
<p>Regards,<br>Optimus Compliance Team</p>"""

        for field, value in merge_fields.items():
            subject = subject.replace("{" + field + "}", value)
            body = body.replace("{" + field + "}", value)

        # Req 10 — render the body as plain text WITH newlines so the
        # preview textarea is readable. The send path
        # (_normalise_email_body) wraps plain text back into <p>/<br>
        # HTML, so editing the preview round-trips cleanly.
        body = _html_to_plaintext_for_preview(body)

        return jsonify({
            "subject": subject,
            "body": body,
            "referee_email": ref_req.referee_email or "",
            "company_name": ref_req.company_name or "",
        })


@app.route("/action/preview-reference-template/<int:cand_id>", methods=["GET"])
@login_required
def preview_reference_template(cand_id: int):
    """Req 22 — return the rendered "reference_request" email template
    WITHOUT requiring a ReferenceRequest row to exist yet. Used by
    openSendReference when staff click Company / Agency / Manual on an
    employment row before Start Referencing has created a row for it.
    Merge fields are resolved from the EmploymentHistory identified by
    the `emp_id` query param. JSON shape matches preview_reference_email
    so the front-end populate logic is identical.
    """
    emp_id_raw = (request.args.get("emp_id") or "").strip()
    try:
        emp_id = int(emp_id_raw) if emp_id_raw else None
    except ValueError:
        emp_id = None

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            return jsonify({"error": "Candidate not found"}), 404

        merge_fields = {
            "candidate_name": cand.name or "",
            "company_name": "",
            "referee_name": "Sir/Madam",
            "job_title": "",
            "start_date": "",
            "end_date": "",
        }
        referee_email = ""
        if emp_id is not None:
            try:
                from associate_portal import _ensure_models, _portal_model
                _ensure_models()
                EmpHistory = _portal_model("EmploymentHistory")
                if EmpHistory:
                    emp = s.get(EmpHistory, emp_id)
                    if emp and getattr(emp, "candidate_id", None) == cand_id:
                        merge_fields["company_name"] = getattr(emp, "company_name", "") or ""
                        merge_fields["referee_name"] = getattr(emp, "referee_name", "") or "Sir/Madam"
                        merge_fields["job_title"] = getattr(emp, "job_title", "") or ""
                        sd = getattr(emp, "start_date", None)
                        ed = getattr(emp, "end_date", None)
                        if sd:
                            merge_fields["start_date"] = sd.strftime("%d/%m/%Y") if hasattr(sd, "strftime") else str(sd)
                        if ed:
                            merge_fields["end_date"] = ed.strftime("%d/%m/%Y") if hasattr(ed, "strftime") else str(ed)
                        referee_email = (
                            getattr(emp, "company_email", "") or ""
                        ) or (getattr(emp, "referee_email", "") or "")
            except Exception:
                current_app.logger.exception("preview_reference_template emp lookup failed")

        email_tpl = s.scalar(select(EmailTemplate).where(EmailTemplate.name == "reference_request"))
        if email_tpl:
            subject = email_tpl.subject or "Reference Request — {candidate_name}"
            body = email_tpl.body or ""
        else:
            subject = "Reference Request — {candidate_name}"
            body = (
                "<h2>Reference Request</h2>"
                "<p>Dear {referee_name},</p>"
                "<p>We are writing to request a reference for "
                "<strong>{candidate_name}</strong> who has listed your "
                "organisation (<strong>{company_name}</strong>) as a "
                "previous employer.</p>"
                "<p>Please reply directly to this email with the reference "
                "details.</p>"
                "<p>Regards,<br>Optimus Compliance Team</p>"
            )

        for field, value in merge_fields.items():
            subject = subject.replace("{" + field + "}", value)
            body = body.replace("{" + field + "}", value)

        body = _html_to_plaintext_for_preview(body)

        return jsonify({
            "subject": subject,
            "body": body,
            "referee_email": referee_email,
            "company_name": merge_fields["company_name"],
        })


def _html_to_plaintext_for_preview(html_text: str) -> str:
    """Req 10 — convert reference-request HTML to readable plain text
    for the preview textarea. Block-level tags become double newlines,
    <br> becomes single newlines, list items get a "- " prefix, and
    every other tag is stripped. The recruiter can then edit freely
    and the send-side _normalise_email_body re-wraps it back to HTML."""
    if not html_text:
        return ""
    import re as _re
    txt = html_text
    # Normalise self-closing variants of <br>
    txt = _re.sub(r"<br\s*/?>", "\n", txt, flags=_re.I)
    # Headings + paragraphs end with a blank line
    txt = _re.sub(r"</(h[1-6]|p|div|blockquote)>", "\n\n", txt, flags=_re.I)
    txt = _re.sub(r"<(h[1-6]|p|div|blockquote)[^>]*>", "", txt, flags=_re.I)
    # List items get a leading "- "
    txt = _re.sub(r"<li[^>]*>", "- ", txt, flags=_re.I)
    txt = _re.sub(r"</li>", "\n", txt, flags=_re.I)
    # Strip <ul>/<ol> wrappers (line-feeds already from the </li>)
    txt = _re.sub(r"</?(ul|ol)[^>]*>", "", txt, flags=_re.I)
    # Strip every other tag
    txt = _re.sub(r"<[^>]+>", "", txt)
    # Decode the most common HTML entities so the preview reads cleanly.
    try:
        import html as _htmllib
        txt = _htmllib.unescape(txt)
    except Exception:
        pass
    # Collapse 3+ blank lines to 2
    txt = _re.sub(r"\n{3,}", "\n\n", txt)
    return txt.strip()


@app.route("/action/send-reference/<int:cand_id>", methods=["POST"])
@login_required
def send_reference(cand_id: int):
    """Send a reference request email. Req 22: also accepts a `recipient_type`
    form field (agency / company / manual) so the row can record which
    side of the employment was approached. Defaults to 'company' when
    not supplied to keep the legacy callers working."""
    ref_id = request.form.get("ref_id", type=int)
    referee_email = request.form.get("referee_email", "").strip()
    company_name = request.form.get("company_name", "").strip()
    # Req 22 — agency / company / manual. Defaults to 'company' for any
    # legacy callers that don't supply it yet.
    recipient_type = (request.form.get("recipient_type") or "company").strip().lower()
    if recipient_type not in ("agency", "company", "manual"):
        recipient_type = "company"
    # Allow recruiter to pass a customised subject/body from the preview modal
    custom_subject = (request.form.get("email_subject") or "").strip()
    custom_body = (request.form.get("email_body") or "").strip()

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        if not cand:
            flash("Associate not found.", "danger")
            return redirect(url_for("workflow"))

        # Get or create ReferenceRequest
        ref_req = None
        if ref_id:
            ref_req = s.get(ReferenceRequest, ref_id)

        if not ref_req:
            ref_req = ReferenceRequest(
                candidate_id=cand_id,
                company_name=company_name,
                referee_email=referee_email
            )
            s.add(ref_req)
            s.flush()

        # Update referee email if the user changed it in the modal
        if referee_email and ref_req.referee_email != referee_email:
            ref_req.referee_email = referee_email

        if not ref_req.referee_email:
            flash("No referee email address provided.", "danger")
            return

        # Build merge field values from the ReferenceRequest + linked EmploymentHistory
        merge_fields = {
            "candidate_name": cand.name or "",
            "company_name": ref_req.company_name or "",
            "referee_name": ref_req.referee_name or "Sir/Madam",
            "job_title": "",
            "start_date": "",
            "end_date": "",
        }
        # Try to pull job_title, start_date, end_date from linked EmploymentHistory
        if ref_req.employment_history_id:
            try:
                from associate_portal import _ensure_models, _portal_model
                _ensure_models()
                EmpHistory = _portal_model("EmploymentHistory")
                if EmpHistory:
                    emp = s.get(EmpHistory, ref_req.employment_history_id)
                    if emp:
                        merge_fields["job_title"] = getattr(emp, "job_title", "") or ""
                        sd = getattr(emp, "start_date", None)
                        ed = getattr(emp, "end_date", None)
                        if sd:
                            merge_fields["start_date"] = sd.strftime("%d/%m/%Y") if hasattr(sd, "strftime") else str(sd)
                        if ed:
                            merge_fields["end_date"] = ed.strftime("%d/%m/%Y") if hasattr(ed, "strftime") else str(ed)
            except Exception:
                pass

        def _normalise_email_body(text: str) -> str:
            """Req 10 — the reference-request preview lives in a <textarea>
            which preserves newlines as raw \\n. When the recruiter sends
            the customised body as-is, those newlines collapsed in the
            final HTML email, producing one continuous line of text.
            Detect whether the body already contains HTML structure; if
            it does, leave it alone. If it's plain text (or mixed),
            wrap paragraphs in <p>...</p> and turn single newlines into
            <br> so the rendered email matches the preview."""
            if not text:
                return ""
            lower = text.lower()
            has_html = any(tag in lower for tag in ("<p", "<br", "<h1", "<h2", "<h3", "<ul", "<ol", "<li", "<table"))
            if has_html:
                return text
            # Plain-text → paragraph-wrapped HTML
            paragraphs = [p.strip() for p in text.split("\n\n") if p.strip()]
            return "".join("<p>" + p.replace("\n", "<br>") + "</p>" for p in paragraphs)

        # If the recruiter customised the email via the preview modal, use that directly
        if custom_subject and custom_body:
            email_subject = custom_subject
            html_body = _normalise_email_body(custom_body)
        else:
            # Load template from DB; fall back to hardcoded default
            email_tpl = s.scalar(select(EmailTemplate).where(EmailTemplate.name == "reference_request"))
            if email_tpl:
                email_subject = email_tpl.subject
                body_text = email_tpl.body
                # Replace merge fields
                for field, value in merge_fields.items():
                    email_subject = email_subject.replace("{" + field + "}", value)
                    body_text = body_text.replace("{" + field + "}", value)
                html_body = _normalise_email_body(body_text)
            else:
                # Hardcoded fallback
                email_subject = f"Reference Request — {cand.name}"
                html_body = f"""
                <h2>Reference Request</h2>
                <p>Dear {merge_fields['referee_name']},</p>
                <p>We are writing to request a reference for <strong>{cand.name}</strong>
                who has listed your organisation (<strong>{ref_req.company_name}</strong>) as a
                previous employer.</p>
                <p>Please could you confirm the following:</p>
                <ul>
                    <li>Dates of employment</li>
                    <li>Job title / role</li>
                    <li>Reason for leaving</li>
                    <li>Any other relevant information</li>
                </ul>
                <p>Please reply directly to this email with the reference details.</p>
                <p>The candidate's signed consent form is attached for your records.</p>
                <p>Thank you for your assistance.</p>
                <p>Regards,<br>Optimus Compliance Team</p>
                """

        # Send reference request email with consent form attached
        try:
            # Auto-attach signed consent form
            attachments = []
            consent_doc = s.scalar(
                select(Document)
                .where(Document.candidate_id == cand_id)
                .where(Document.doc_type == "consent_signed")
                .order_by(Document.uploaded_at.desc())
            )
            if consent_doc:
                consent_path = os.path.join(UPLOAD_FOLDER, consent_doc.filename)
                if os.path.exists(consent_path):
                    with open(consent_path, "rb") as f:
                        attachments.append((
                            consent_doc.original_name or "Consent_Form.pdf",
                            f.read(),
                            "application/pdf"
                        ))
            # User-uploaded attachment from the modal
            user_file = request.files.get("attachment")
            if user_file and user_file.filename:
                attachments.append((
                    user_file.filename,
                    user_file.read(),
                    user_file.content_type or "application/octet-stream",
                ))

            # Req 50 — reference request emails come from compliance@.
            send_email(ref_req.referee_email, email_subject, html_body,
                       attachments=attachments if attachments else None,
                       from_email=COMPLIANCE_FROM)
            ref_req.status = "sent"
            ref_req.sent_at = datetime.datetime.utcnow()
            # Req 22 — record which side of the employment row was sent
            ref_req.recipient_type = recipient_type
            flash(
                f"Reference request sent ({recipient_type}) to {ref_req.referee_email}.",
                "success",
            )
        except Exception as e:
            flash(f"Failed to send reference email: {str(e)}", "danger")

        log_audit_event('create', 'vetting',
                        f'Reference request sent to {ref_req.referee_email} for {company_name}',
                        'candidate', cand_id,
                        {'referee_email': ref_req.referee_email, 'company': company_name})
        s.commit()

    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/action/reference-approved-emails", methods=["GET"])
@login_required
def reference_approved_emails():
    """Req 22 — Manual Send picker source. Given a company name query,
    return the approved-list emails (from ReferenceContact) so the
    recruiter can pick from them or type a new one. Falls back to
    company-name "contains" matching when an exact lookup yields
    nothing, so prefixes / partials still suggest candidates."""
    company = (request.args.get("company") or "").strip()
    out = []
    if not company:
        return jsonify({"ok": True, "emails": out})
    try:
        from associate_portal import _ensure_models, _portal_model
        _ensure_models()
        ReferenceContact = _portal_model("ReferenceContact")
        if not ReferenceContact:
            return jsonify({"ok": True, "emails": out})
        with Session(engine) as s:
            rows = s.scalars(
                select(ReferenceContact)
                .where(func.lower(ReferenceContact.company_name) == company.lower())
                .order_by(ReferenceContact.referee_email)
            ).all()
            if not rows:
                rows = s.scalars(
                    select(ReferenceContact)
                    .where(ReferenceContact.company_name.ilike(f"%{company}%"))
                    .order_by(ReferenceContact.referee_email)
                    .limit(20)
                ).all()
            for r in rows:
                if r.referee_email:
                    out.append({
                        "company": r.company_name or "",
                        "email": r.referee_email,
                    })
    except Exception:
        current_app.logger.exception("reference_approved_emails lookup failed")
    return jsonify({"ok": True, "emails": out})


@app.route("/action/gap-evidence/upload/<int:cand_id>/<int:emp_id>", methods=["POST"])
@login_required
def gap_evidence_upload(cand_id: int, emp_id: int):
    """Req 22 follow-up — staff-side upload for gap evidence. The associate
    portal already lets the candidate attach evidence to a gap entry; this
    mirrors that for the recruiter on the candidate profile so a missing
    upload can be filled in without waiting on the candidate.

    Saves the file as a Document (doc_type='gap_evidence') and stores its
    id on EmploymentHistory.gap_evidence_doc_id.
    """
    evidence_file = request.files.get("evidence_file")
    if not evidence_file or not evidence_file.filename:
        flash("Please choose a file before uploading.", "warning")
        return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-refs")

    try:
        from associate_portal import _ensure_models, _portal_model
        _ensure_models()
        EmpHistory = _portal_model("EmploymentHistory")
    except Exception:
        EmpHistory = None
    if not EmpHistory:
        flash("Employment history model not available — could not save the upload.", "warning")
        return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-refs")

    with Session(engine) as s:
        emp = s.get(EmpHistory, emp_id)
        if not emp or emp.candidate_id != cand_id:
            flash("Gap entry not found.", "warning")
            return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-refs")
        if not getattr(emp, "is_gap", False):
            flash("That row isn't a gap — no evidence required.", "warning")
            return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-refs")

        try:
            orig_name = secure_filename(evidence_file.filename) or "gap_evidence"
            ext = orig_name.rsplit(".", 1)[-1].lower() if "." in orig_name else ""
            if ext not in ("pdf", "doc", "docx", "jpg", "jpeg", "png", "eml", "msg"):
                flash(
                    "Evidence must be a PDF, DOC, DOCX, JPG, PNG, EML or MSG file.",
                    "warning",
                )
                return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-refs")
            new_name = f"{uuid.uuid4()}_{orig_name}"
            target_dir = os.path.join(app.config["UPLOAD_FOLDER"], "gap_evidence")
            os.makedirs(target_dir, exist_ok=True)
            evidence_file.save(os.path.join(target_dir, new_name))

            doc = Document(
                candidate_id=cand_id,
                doc_type="gap_evidence",
                filename=os.path.join("gap_evidence", new_name),
                original_name=orig_name,
                uploaded_at=datetime.datetime.utcnow(),
            )
            s.add(doc)
            s.flush()

            emp.gap_evidence_doc_id = doc.id

            s.add(CandidateNote(
                candidate_id=cand_id,
                user_email=getattr(current_user, "email", "staff") or "staff",
                note_type="activity",
                content=(
                    f"Gap evidence uploaded by staff for {emp.start_date}–{emp.end_date}: {orig_name}"
                ),
                created_at=datetime.datetime.utcnow(),
            ))
            log_audit_event(
                "update", "references",
                f"Gap evidence uploaded for candidate {cand_id} gap #{emp_id}",
                "candidate", cand_id,
                {"employment_history_id": emp_id, "doc_id": doc.id},
            )
            s.commit()
            flash("Gap evidence uploaded.", "success")
        except Exception:
            s.rollback()
            current_app.logger.exception(
                "gap_evidence_upload failed for cand=%s emp=%s", cand_id, emp_id,
            )
            flash("Could not save the evidence — please try again.", "warning")

    return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-refs")


@app.route("/action/reference-confirm-agreed/<int:cand_id>/<int:ref_id>", methods=["POST"])
@login_required
def reference_confirm_agreed(cand_id: int, ref_id: int):
    """Req 22 — recruiter marks a reference as agreed and uploads the
    referee's reply email (PDF / EML). Stamps `agreed_at`, attaches the
    uploaded file as a `Document`, links it on `reply_doc_id`, flips the
    request status to `received`, and writes a CandidateNote."""
    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        ref = s.get(ReferenceRequest, ref_id) if ref_id else None
        if not cand or not ref or ref.candidate_id != cand_id:
            flash("Reference request not found.", "warning")
            return redirect(url_for("candidate_profile", cand_id=cand_id))

        reply_file = request.files.get("reply_file")
        notes = (request.form.get("notes") or "").strip()

        if not reply_file or not reply_file.filename:
            flash("Please attach the referee's reply email before confirming.", "warning")
            return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-refs")

        try:
            # Reply emails can be PDF or EML — bypass the global
            # allowed_file() which only permits PDF/DOC/DOCX, and write
            # straight to the uploads dir.
            orig_name = secure_filename(reply_file.filename) or "reference_reply"
            ext = orig_name.rsplit(".", 1)[-1].lower() if "." in orig_name else ""
            if ext not in ("pdf", "eml", "msg", "doc", "docx"):
                flash(
                    "Reply must be a PDF, EML, MSG, DOC or DOCX file.",
                    "warning",
                )
                return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-refs")
            new_name = f"{uuid.uuid4()}_{orig_name}"
            target_dir = os.path.join(app.config["UPLOAD_FOLDER"], "reference_replies")
            os.makedirs(target_dir, exist_ok=True)
            reply_file.save(os.path.join(target_dir, new_name))

            doc = Document(
                candidate_id=cand_id,
                doc_type="reference_reply",
                filename=os.path.join("reference_replies", new_name),
                original_name=orig_name,
                uploaded_at=datetime.datetime.utcnow(),
            )
            s.add(doc)
            s.flush()

            ref.reply_doc_id = doc.id
            ref.agreed_at = datetime.datetime.utcnow()
            ref.status = "received"
            ref.colour = "green"
            if notes:
                ref.notes = (ref.notes + "\n" if ref.notes else "") + f"Agreed: {notes}"

            s.add(CandidateNote(
                candidate_id=cand_id,
                user_email=getattr(current_user, "email", "staff") or "staff",
                note_type="activity",
                content=(
                    f"Reference agreed for {ref.company_name or '(unnamed company)'}; "
                    f"reply email uploaded ({reply_file.filename})."
                ),
                created_at=datetime.datetime.utcnow(),
            ))
            log_audit_event(
                "update", "vetting",
                f"Reference confirmed agreed for {ref.company_name or '?'}",
                "candidate", cand_id,
                {"reference_request_id": ref.id, "reply_doc_id": doc.id},
            )
            s.commit()
            flash("Reference marked agreed — reply email saved against the row.", "success")
        except Exception:
            s.rollback()
            current_app.logger.exception(
                "reference_confirm_agreed failed for cand=%s ref=%s", cand_id, ref_id,
            )
            flash("Could not save the reply email — please try again.", "warning")

    return redirect(url_for("candidate_profile", cand_id=cand_id) + "#sec-refs")


@app.route("/action/chase-reference/<int:cand_id>", methods=["POST"])
@login_required
def chase_reference(cand_id: int):
    """Batch 5.3: Chase (resend) a reference request with a reminder."""
    ref_id = request.form.get("ref_id", type=int)

    with Session(engine) as s:
        cand = s.get(Candidate, cand_id)
        ref_req = s.get(ReferenceRequest, ref_id) if ref_id else None
        if not ref_req or ref_req.candidate_id != cand_id:
            flash("Reference request not found.", "danger")
            return

        if ref_req.chase_count >= 3:
            ref_req.status = "on_hold"
            ref_req.colour = "orange"
            s.commit()
            flash(f"Max 3 chases reached for {ref_req.company_name}. Moved to On Hold.", "warning")
            return

        try:
            html_body = f"""
            <h2>Reminder: Reference Request</h2>
            <p>Dear Sir/Madam,</p>
            <p>This is a follow-up to our previous request for a reference for
            <strong>{cand.name if cand else 'the candidate'}</strong>
            (previously employed at <strong>{ref_req.company_name}</strong>).</p>
            <p>We would be grateful if you could provide the requested information
            at your earliest convenience.</p>
            <p>Regards,<br>Optimus Compliance Team</p>
            """
            # Req 50 — reference reminder also comes from compliance@.
            send_email(ref_req.referee_email,
                       f"Reminder: Reference Request — {cand.name if cand else 'Candidate'}",
                       html_body,
                       from_email=COMPLIANCE_FROM)
            ref_req.chase_count = (ref_req.chase_count or 0) + 1
            ref_req.last_chased_at = datetime.datetime.utcnow()
            flash(f"Chase #{ref_req.chase_count} sent to {ref_req.referee_email}.", "success")
        except Exception as e:
            flash(f"Failed to send chase: {str(e)}", "danger")

        log_audit_event('update', 'vetting',
                        f'Reference chased (#{ref_req.chase_count}) for {ref_req.company_name}',
                        'candidate', cand_id,
                        {'chase_count': ref_req.chase_count, 'referee_email': ref_req.referee_email})
        s.commit()

    return redirect(url_for("candidate_profile", cand_id=cand_id))


@app.route("/action/receive-reference/<int:cand_id>", methods=["POST"])
@login_required
def receive_reference(cand_id: int):
    """Batch 5: Mark a reference as received and optionally upload the response."""
    ref_id = request.form.get("ref_id", type=int)
    notes = request.form.get("notes", "").strip()
    colour = request.form.get("colour", "green").strip()

    with Session(engine) as s:
        ref_req = s.get(ReferenceRequest, ref_id) if ref_id else None
        if not ref_req or ref_req.candidate_id != cand_id:
            flash("Reference request not found.", "danger")
            return

        ref_req.status = "received"
        ref_req.received_at = datetime.datetime.utcnow()
        ref_req.colour = colour if colour in ("white", "green", "orange") else "green"
        if notes:
            ref_req.notes = notes

        # Handle attachment upload (.msg, .pdf, .eml, .doc, .docx)
        file = request.files.get("attachment")
        if file and file.filename:
            ext = file.filename.rsplit(".", 1)[-1].lower() if "." in file.filename else ""
            if ext in ("msg", "pdf", "eml", "doc", "docx"):
                upload_dir = os.path.join(UPLOAD_FOLDER, "references")
                os.makedirs(upload_dir, exist_ok=True)
                safe_name = f"{cand_id}_ref_{ref_id}_{uuid.uuid4().hex[:8]}.{ext}"
                filepath = os.path.join(upload_dir, safe_name)
                file.save(filepath)
                ref_req.attachment_path = filepath

        log_audit_event('update', 'vetting',
                        f'Reference received for {ref_req.company_name}',
                        'candidate', cand_id,
                        {'company': ref_req.company_name, 'colour': ref_req.colour})
        s.commit()
        flash(f"Reference from {ref_req.company_name} marked as received.", "success")

    return redirect(url_for("candidate_profile", cand_id=cand_id))


